      if(!liveBelong[did] && !belong[did]) return;
      var ov = state.draftBrandOverrides[did];
      if(!ov) return;
      var sid = String(ov.roadmapStepId || '');
      if(idMap[sid]) ov.roadmapStepId = idMap[sid];
