function getDraftBrandMeta_(draft, catId, draftIndex){
  var cat = CATEGORIES[catId];
  var total = cat && cat.drafts ? cat.drafts.length : 0;
  var idx = typeof draftIndex === 'number' ? draftIndex : -1;
  var series = draft && draft.series ? String(draft.series).trim() : getDefaultSeriesForCat_(catId);
  var step = draft && draft.step ? String(draft.step).trim() : (idx >= 0 && total ? (idx + 1) + '/' + total : '');
  var pillar = draft && draft.pillar ? String(draft.pillar).trim() : getDefaultPillarForCat_(catId);
  var rationale = draft && draft.rationale ? String(draft.rationale).trim() : '';
  return {
    series: localizeProgramDisplayName_(series),
    step: step,
    pillar: localizeProgramDisplayName_(pillar),
    rationale: rationale
  };
}
function formatDraftStepBadgeForDisplay_(draft, catId, draftIndex){
  var idx = typeof draftIndex === 'number' ? draftIndex : -1;
  var stepId = getDraftRoadmapStepId_(draft, catId, idx);
  if(String(stepId) === SUBGOAL_MISC_ID) return '기타';
  var parts = getDraftStepParts_(draft, catId, idx);
  if(isValidStepTopicSlot_(parts.step) && parts.total >= 1 && parts.step <= parts.total){
    return parts.step + '/' + parts.total;
  }
  var slotMap = buildStepSlotDraftMap_(catId, stepId, { live: true });
  for(var si = 0; si < slotMap.length; si++){
    if(slotMap[si] === draft){
      var filled = 0;
      for(var fj = 0; fj < slotMap.length; fj++) if(slotMap[fj]) filled++;
      return (si + 1) + '/' + stepTopicSlotTotalForCount_(filled);
    }
  }
  var inStep = getDraftsForSubGoalStep_(catId, stepId, { live: true });
  var pos = inStep.indexOf(draft);
  if(pos >= 0){
    return (pos + 1) + '/' + stepTopicSlotTotalForCount_(inStep.length);
  }
  if(isValidStepTopicSlot_(parts.step)){
    return parts.step + '/' + stepTopicSlotTotalForCount_(parts.total || parts.step);
  }
  return '기타';
}
/** step 배지가 7/5처럼 분모보다 큰 초안을 정리 (슬롯 정규화는 normalizeAllStepDraftSlots_ 에서) */
function repairInvalidStepBadgeDrafts_(catId){
  if(!canReassignDraftSteps_()) return false;
  var cat = CATEGORIES[catId];
  var plan = getSubGoalPlan_(catId);
  if(!cat || !plan || !plan.steps) return false;
  var changed = false;
  var stepsNeedingDensify = {};
  (cat.drafts || []).forEach(function(d, di){
    if(!d || !d.id) return;
    var parts = getDraftStepParts_(d, catId, di);
    var badDenom = parts.step >= 1 && parts.total >= 1 && parts.step > parts.total;
    if(!badDenom) return;
    var sid = getDraftRoadmapStepId_(d, catId, di);
    if(sid && String(sid) !== SUBGOAL_MISC_ID){
      stepsNeedingDensify[sid] = true;
    }
  });
  Object.keys(stepsNeedingDensify).forEach(function(sid){
    if(densifyStepSlotTotalsOnly_(catId, sid)) changed = true;
  });
  if(normalizeMiscUserAddedOrder_(catId)) changed = true;
  return changed;
}
function applyTopicFieldsToDraft_(draft, obj, catId){
  if(!draft || !obj) return;
  if(obj.topic) draft.topic = String(obj.topic).trim();
  if(obj.angle != null) draft.angle = String(obj.angle || '').trim();
  if(obj.series) draft.series = localizeProgramDisplayName_(String(obj.series).trim());
  else if(!draft.series) draft.series = getDefaultSeriesForCat_(catId);
  if(obj.step) draft.step = String(obj.step).trim();
  if(obj.pillar) draft.pillar = localizeProgramDisplayName_(String(obj.pillar).trim());
  else if(!draft.pillar) draft.pillar = getDefaultPillarForCat_(catId);
  if(obj.rationale) draft.rationale = stripTopicRationaleStepPrefix_(String(obj.rationale).trim());
  if(obj.topic || obj.angle != null || obj.rationale || obj.pillar) delete draft.writingBrief;
}
