  if(!act) return;
  if(!readCachedDriveToken_()){
    hideDriveOAuthBusy_();
    if(typeof setAppToast === 'function'){
      setAppToast('Drive 로그인은 됐지만 이 기기에 토큰을 저장하지 못했어요.\nSafari·Chrome에서 다시 Drive를 눌러 주세요.', { duration: 9000, variant: 'err' });
    }
    return;
  }
