/** JSON 문자열에서 최상위 객체 속성 값만 교체 (대용량 parse 전에 generatedOnly 제거용) */
function replaceJsonTopLevelObjectProp_(raw, propName, replacement){
  raw = String(raw || '');
  var needle = '"' + propName + '"';
  var idx = raw.indexOf(needle);
  if(idx < 0) return raw;
  var colon = raw.indexOf(':', idx + needle.length);
  if(colon < 0) return raw;
  var i = colon + 1;
  while(i < raw.length && /\s/.test(raw.charAt(i))) i++;
  var start = i;
  var ch0 = raw.charAt(i);
  if(ch0 === '{'){
    var depth = 0;
    for(; i < raw.length; i++){
      var ch = raw.charAt(i);
      if(ch === '"'){
        i++;
        while(i < raw.length){
          if(raw.charAt(i) === '\\'){ i += 2; continue; }
          if(raw.charAt(i) === '"') break;
          i++;
        }
        continue;
      }
      if(ch === '{') depth++;
      else if(ch === '}'){
        depth--;
        if(depth === 0){
          return raw.slice(0, start) + replacement + raw.slice(i + 1);
        }
      }
    }
  } else if(ch0 === '['){
    var depthA = 0;
    for(; i < raw.length; i++){
      var c2 = raw.charAt(i);
      if(c2 === '"'){
        i++;
        while(i < raw.length){
          if(raw.charAt(i) === '\\'){ i += 2; continue; }
          if(raw.charAt(i) === '"') break;
          i++;
        }
        continue;
      }
      if(c2 === '[') depthA++;
      else if(c2 === ']'){
        depthA--;
        if(depthA === 0){
          return raw.slice(0, start) + replacement + raw.slice(i + 1);
        }
      }
    }
  }
  return raw;
}
/** 미발행 생성 초안 본문만 비움 — 주제 카드·발행본 유지 (부팅 멈춤·용량 한도 완화) */
function stripGeneratedContentBodiesInPayload_(payload){
  if(!payload || !payload.generatedOnly) return 0;
  var n = 0;
  Object.keys(payload.generatedOnly).forEach(function(id){
    var g = payload.generatedOnly[id];
    if(!g || typeof g !== 'object') return;
    if(g.content != null){
      g.content = { _prunedForBoot: true };
      n++;
      return;
    }
    if(g.blog || g.thread || g.community || g.insta || g.threads || g.images){
      payload.generatedOnly[id] = { _prunedForBoot: true, topic: g.topic || '' };
      n++;
    }
  });
  return n;
}
