function setupPlannerServiceWorker_(){
  if(!('serviceWorker' in navigator) || location.protocol === 'file:') return;
  try {
    if(navigator.onLine === false) sessionStorage.setItem('ht_planner_offline_boot', '1');
  } catch(eOff){}
  // 첫 화면 이후에만 등록 — URL 이동 자체가 SW에 막히지 않게
  var registerLater_ = function(){
    navigator.serviceWorker.register('planner-sw.js?v=192').then(function(reg){
      try { reg.update(); } catch(eUp){}
      if(reg.waiting) suggestPlannerSwRefresh_('waiting');
      reg.addEventListener('updatefound', function(){
        var nw = reg.installing;
        if(!nw) return;
        nw.addEventListener('statechange', function(){
          if(nw.state === 'installed' && navigator.serviceWorker.controller){
            suggestPlannerSwRefresh_('updatefound');
          }
        });
      });
    }).catch(function(e){ console.warn('[SW]', e); });
  };
  if(typeof requestIdleCallback === 'function'){
    requestIdleCallback(function(){ setTimeout(registerLater_, 1500); }, { timeout: 4000 });
  } else {
    setTimeout(registerLater_, 2500);
  }
  if(!window.__plannerSwControllerBound){
    window.__plannerSwControllerBound = true;
    navigator.serviceWorker.addEventListener('controllerchange', function(){
      suggestPlannerSwRefresh_('controllerchange', { preferReload: false });
    });
  }
}

