window.addDraft = async function(){
  if(state.newItem.imageAnalyzing){
    if(typeof setAppToast === 'function') setAppToast('사진 분석이 끝날 때까지 잠시만 기다려 주세요.', { duration: 3200, variant: 'err' });
    return;
  }
  if(state.newItem.flowProposalsLoading){
    if(typeof setAppToast === 'function') setAppToast('글 흐름 제안이 끝날 때까지 잠시만 기다려 주세요.', { duration: 3200, variant: 'err' });
    return;
  }
  var isDaily = isDailyShareCategory(state.newItem.catId);
  var isThought = isDaily && isDailyThoughtNewItem_();
  var keywords = isDaily ? getDailyNewItemKeywords_() : (state.newItem.topic || '').trim();
  var refNote = (state.newItem.refNote || '').trim();
  var sourceNote = buildDraftSourceNote_(keywords, refNote);
  var hasPhoto = newItemHasRefImages_();
  var hasMedia = newItemHasMediaSource_();
  var selectedFlow = getSelectedNewItemFlow_();
  var hasFlow = !!state.newItem.flowProposalsReady && !!selectedFlow;
  if(isThought){
    if(!getDailyThoughtText_(state.newItem)){
      if(typeof setAppToast === 'function') setAppToast('떠오른 한 줄을 적어 주세요.', { duration: 3500, variant: 'err' });
      else alert('생각 한 줄을 적어 주세요');
      return;
    }
  } else if(!sourceNote && !(isDaily && hasPhoto)){
    if(typeof setAppToast === 'function') setAppToast(isDaily ? '누구와·무엇을·몸 느낌을 적거나 사진을 올려 주세요.' : '키워드 또는 참고 메모를 입력해 주세요.', { duration: 3500, variant: 'err' });
    else alert(isDaily ? '재료 세 칸 또는 사진이 필요합니다' : '키워드 또는 참고 메모를 입력해주세요');
    return;
  }
  if(!hasFlow){
    if(typeof setAppToast === 'function') setAppToast('먼저 「글의 흐름 만들기」를 눌러 흐름을 받고 하나를 선택해 주세요.', { duration: 4000, variant: 'err' });
    return;
  }
  if(!String(selectedFlow.title || '').trim()){
    if(typeof setAppToast === 'function') setAppToast('선택한 흐름의 제목을 입력해 주세요.', { duration: 3500, variant: 'err' });
    return;
  }
  if(!state.apiKey){ openApiModal(); return; }
  var youtubeUrls = extractYoutubeUrlsFromText_(sourceNote);
  if(youtubeUrls.length && !isGeminiYoutubeAvailable_()){
    if(typeof setAppToast === 'function'){
      setAppToast('유튜브 URL이 있어요.\nApps Script 스크립트 속성에 GEMINI_API_KEY를 넣고 배포를 새로 해 주세요.', { duration: 6000, variant: 'ok' });
    }
  }
  var btn = document.getElementById('btn-add-draft-submit');
  var youtubeAnalysis = state.newItem.cachedYoutubeAnalysis || '';
  var addEstSec = hasFlow ? ADD_DRAFT_FULL_ESTIMATE_SEC : ADD_DRAFT_TOPIC_ESTIMATE_SEC;
  if(youtubeUrls.length && isGeminiYoutubeAvailable_() && !youtubeAnalysis && !hasMedia) addEstSec += 15;
  if(btn){
    startButtonCountdown_(btn, {
      estimateSec: addEstSec,
      busyLabel: hasFlow ? '초안 생성 중' : '주제 생성 중'
    });
  }
  if(typeof setAppToast === 'function') setAppToast(
    hasFlow ? '선택한 글 흐름으로 주제 카드를 만들고 초안을 준비하고 있어요…' :
    (youtubeUrls.length && isGeminiYoutubeAvailable_() && !youtubeAnalysis ? '공개 유튜브 영상을 분석한 뒤 주제를 만들고 있어요…' :
    (isDaily && hasPhoto ? '사진을 보고 주제·일상 글을 만들고 있어요…' : '주제 제목·각도를 만들고 있어요…')),
    { duration: 3200, variant: 'ok' }
  );
  try {
    if(!hasMedia && youtubeUrls.length && isGeminiYoutubeAvailable_() && !youtubeAnalysis){
      try {
        youtubeAnalysis = await analyzeYoutubeWithGemini_(youtubeUrls[0], state.newItem.catId);
      } catch(ytErr){
        var ytMsg = (ytErr && ytErr.message) ? ytErr.message : String(ytErr);
        var ytToast = '유튜브 분석 실패 — 메모만으로 주제를 만들게요.';
        if(ytMsg) ytToast += '\n' + ytMsg;
        if(typeof setAppToast === 'function') setAppToast(ytToast, { duration: /할당량|quota|limit/i.test(ytMsg) ? 12000 : 7000, variant: 'err' });
      }
    }
    var gen;
    if(hasFlow){
      var selected = selectedFlow;
      gen = {
        topic: String(selected.title || '').trim(),
        angle: String(selected.angle || '').trim() || (CATEGORIES[state.newItem.catId].audience + ' 관점'),
        series: getDefaultSeriesForCat_(state.newItem.catId),
        pillar: getDefaultPillarForCat_(state.newItem.catId),
        rationale: (selected.steps || []).join(' → ')
      };
    } else {
      gen = await generateTopicFromKeywords_(state.newItem.catId, keywords, state.newItem.refImages, sourceNote, youtubeAnalysis);
    }
    var cat = CATEGORIES[state.newItem.catId];
    var id = 'd' + state.newItem.catId + '-c' + Date.now();
    var draft = { id: id, topic: gen.topic, angle: gen.angle, createdAt: new Date().toISOString() };
    if(isDaily) draft.shareMonth = getCurrentShareMonthKey_();
    applyTopicFieldsToDraft_(draft, gen, state.newItem.catId);
    if(hasFlow){
      var picked = selectedFlow;
      draft.articleFlow = {
        title: String(picked.title || '').trim(),
        angle: String(picked.angle || '').trim(),
        steps: (picked.steps || []).slice()
      };
      draft.articleKind = getNewItemArticleKind_() || '';
    }
    assignUserAddedDraftToMisc_(draft, state.newItem.catId);
    if(!draft.articleKind) draft.articleKind = getNewItemArticleKind_() || '';
    if(sourceNote) draft.sourceNote = sourceNote;
    if(isDaily){
      draft.dailyShareKind = isThought ? 'thought' : 'scene';
      draft.dailyThought = getDailyThoughtText_(state.newItem);
      draft.dailyWho = String(state.newItem.dailyWho || '').trim();
      draft.dailyWhat = String(state.newItem.dailyWhat || '').trim();
      draft.dailyBody = String(state.newItem.dailyBody || '').trim();
    }
    if(hasFlow && youtubeAnalysis){
      draft.youtubeAnalysis = youtubeAnalysis;
      if(youtubeUrls.length) draft.youtubeUrls = [youtubeUrls[0]];
    } else if(youtubeAnalysis){
      draft.youtubeAnalysis = youtubeAnalysis;
      draft.youtubeUrls = [youtubeUrls[0]];
    }
    var refImages = normalizeRefImages_(state.newItem.refImages);
    if(refImages.length){
      draft.refImages = refImages.map(function(img){
        return { mediaType: img.mediaType, data: img.data, name: img.name || '' };
      });
      draft.refImage = {
        mediaType: refImages[0].mediaType,
        data: refImages[0].data,
        name: refImages[0].name || ''
      };
    }
    cat.drafts.push(draft);
    var savedCatId = state.newItem.catId;
    state.newItem = createEmptyNewItem_(savedCatId);
    state.showAdd = false;
    document.getElementById('add-toggle-btn').textContent = '추가';
    state.currentCat = cat.id;
    renderTabs();
    renderMain();
    save();
    var openTab = isThreadCategory(cat.id) ? 'thread' : (isHeiljagyaeCategory(cat.id) ? 'community' : 'blog');
    var genLabel = openTab === 'blog' ? '블로그 초안' : (openTab === 'thread' ? '일상 글' : '게시판·이미지 초안');
    if(btn) stopButtonCountdown_(btn);
    if(typeof setAppToast === 'function') {
      var toastMsg = '「' + gen.topic + '」\n' + genLabel + '을 만들고 있어요…';
      if(youtubeAnalysis) toastMsg += '\n유튜브 분석 내용이 반영됐어요.';
      setAppToast(toastMsg, { duration: 5200, variant: 'ok' });
    }
    await window.enqueueDraftGeneration(cat.id, id, { openDetailOnComplete: true, openDetailTab: openTab });
  } catch(e){
    var msg = (e && e.message) ? e.message : String(e);
    if(typeof setAppToast === 'function') setAppToast('주제 생성 실패\n' + msg, { duration: 7000, variant: 'err' });
    else alert(msg);
  } finally {
    if(btn) stopButtonCountdown_(btn);
  }
};


window.deleteDraft = function(catId, draftId){
  var cat = CATEGORIES[catId];
  if(!cat || !draftId) return;
  var d = (cat.drafts || []).find(function(x){ return x && x.id === draftId; });
  if(!d){
    if(typeof setAppToast === 'function') setAppToast('주제를 찾을 수 없어요.', { duration: 3200 });
    return;
  }
  var t0 = d.topic || '주제';
  var short = t0.length > 28 ? t0.slice(0, 28) + '…' : t0;
  var hasExtra = draftHasContent(d) || draftHasAnyPublish_(draftId);
  var msg = hasExtra
    ? '「' + short + '」와 작성된 초안·발행 정보를 삭제합니다.\n되돌릴 수 없어요. 계속할까요?'
    : '「' + short + '」 주제를 목록에서 삭제할까요?';
  if(!confirm(msg)) return;

  cat.drafts = (cat.drafts || []).filter(function(x){ return !x || x.id !== draftId; });
  if(!state.deletedDraftIds) state.deletedDraftIds = {};
  state.deletedDraftIds[draftId] = new Date().toISOString();
  if(state.pinnedDraftIds && state.pinnedDraftIds[draftId]) delete state.pinnedDraftIds[draftId];
  if(state.draftBrandOverrides) delete state.draftBrandOverrides[draftId];
  delete state.published[draftId];
  delete state.generatedOnly[draftId];
  if(typeof instaBgByDraft !== 'undefined') delete instaBgByDraft[draftId];
  if(typeof threadsBgByDraft !== 'undefined') delete threadsBgByDraft[draftId];

  if(state.selectedId === draftId){
    closeSheetUiOnly_();
    clearOpenDetailHash_();
  }

  state._syncFocusDraftIds = {};
  state._syncFocusDraftIds[draftId] = true;
  try {
    save({ driveImmediate: false, gasImmediate: true });
  } finally {
    state._syncFocusDraftIds = null;
  }
  renderMain();
  if(state.planWorkshopMode === 'topic') refreshTopicWorkshop_();
  if(typeof setAppToast === 'function') setAppToast('「' + short + '」을(를) 삭제했어요. 서버에도 반영 중…', { duration: 3600, variant: 'ok' });
};

/** 자세히 보기 — 카테고리(단계) 칩. 예전 「순서」 버튼과 같은 크기 */
function renderMoveDraftStepChipsHTML_(fromCatId, draftId){
  var cat = CATEGORIES[fromCatId];
  var draft = cat && (cat.drafts || []).find(function(d){ return d && d.id === draftId; });
  var draftIndex = draft && cat.drafts ? cat.drafts.indexOf(draft) : -1;
  var currentStepId = draft ? String(getDraftRoadmapStepId_(draft, fromCatId, draftIndex) || '') : '';
  var plan = getSubGoalPlan_(fromCatId);
  var steps = (plan && plan.steps) ? plan.steps : [];
  var stepBtns = steps.map(function(step, idx){
    if(!step) return '';
    var sid = String(step.id);
    var tip = String(step.title || '').trim();
    var label = isFlatProgramRoadmapCategory_(fromCatId)
      ? (displaySubGoalStepTitle_(tip, fromCatId) || ((idx + 1) + ''))
      : ((idx + 1) + '단계');
    var current = sid === currentStepId;
    return '<button type="button" class="draft-card-tidy-mini card-step-chip' + (current ? ' is-current' : '') + '"' +
      (current ? ' disabled' : '') +
      (tip ? ' title="' + escapeHtml(tip) + '"' : ' title="이 카테고리로 옮기기"') +
      ' onclick="event.stopPropagation();moveDraftToStep_(' + fromCatId + ',\'' + draftId + '\',\'' + sid.replace(/'/g, '') + '\')">' +
      escapeHtml(label) + '</button>';
  }).join('');
  var miscCurrent = currentStepId === SUBGOAL_MISC_ID;
  stepBtns += '<button type="button" class="draft-card-tidy-mini card-step-chip' + (miscCurrent ? ' is-current' : '') + '"' +
    (miscCurrent ? ' disabled' : '') +
    ' title="기타 주제" onclick="event.stopPropagation();moveDraftToStep_(' + fromCatId + ',\'' + draftId + '\',\'' + SUBGOAL_MISC_ID + '\')">기타</button>';
  if(!steps.length && !stepBtns) stepBtns = '<span class="card-move-empty">생성된 단계가 없어요</span>';
  return stepBtns;
}

window.moveDraftToStep_ = function(catId, draftId, stepId){
  catId = parseInt(catId, 10);
  stepId = String(stepId || '');
  var cat = CATEGORIES[catId];
  if(!cat || !draftId || !stepId) return;
  var draft = (cat.drafts || []).find(function(d){ return d && d.id === draftId; });
  if(!draft){
    if(typeof setAppToast === 'function') setAppToast('주제를 찾을 수 없어요.', { duration: 3200 });
    return;
  }
  var plan = getSubGoalPlan_(catId);
  if(!plan || !plan.steps) return;
  if(stepId === SUBGOAL_MISC_ID){
    dropDraftOnStep_(catId, draftId, SUBGOAL_MISC_ID, null);
    return;
  }
  var step = null;
  var stepIdx = -1;
  plan.steps.forEach(function(s, i){
    if(s && String(s.id) === stepId){ step = s; stepIdx = i; }
  });
  if(!step) return;
  var di = cat.drafts.indexOf(draft);
  var current = String(getDraftRoadmapStepId_(draft, catId, di) || '');
  var label = (stepIdx + 1) + '단계';
  if(current === String(step.id)){
    if(typeof setAppToast === 'function') setAppToast('이미 ' + label + '에 있어요.', { duration: 2800 });
    return;
  }
  dropDraftOnStep_(catId, draftId, step.id, null);
};

var _topicDragState = { draftId: '', catId: null, moved: false, suppressClick: false };

window.onTopicCardClick_ = function(ev, draftId, catId){
  if(_topicDragState.suppressClick){
    _topicDragState.suppressClick = false;
    if(ev){ ev.preventDefault(); ev.stopPropagation(); }
    return;
  }
  openDetail(draftId, catId);
};

function clearTopicDropHighlights_(){
  document.querySelectorAll('.subgoal-step-block.is-drop-target, .draft-card.topic-line.is-drop-before, .draft-card.topic-line.is-drop-after').forEach(function(el){
    el.classList.remove('is-drop-target', 'is-drop-before', 'is-drop-after');
  });
}

function topicDropLabel_(catId, stepId){
  if(String(stepId) === SUBGOAL_MISC_ID) return getSubGoalMiscLabel_(getSubGoalPlan_(catId)) || '기타 주제';
  var plan = getSubGoalPlan_(catId);
  if(!plan || !plan.steps) return '주제';
  for(var i = 0; i < plan.steps.length; i++){
    if(plan.steps[i] && String(plan.steps[i].id) === String(stepId)){
      var raw = plan.steps[i].title || '';
      if(isFlatProgramRoadmapCategory_(catId)){
        return displaySubGoalStepTitle_(raw, catId) || ('주제 ' + (i + 1));
      }
      return (i + 1) + '단계';
    }
  }
  return '주제';
}

function reindexDraftsInStep_(catId, stepId, ordered){
  var plan = getSubGoalPlan_(catId);
  var title = String(stepId) === SUBGOAL_MISC_ID
    ? getSubGoalMiscLabel_(plan)
    : getSubGoalStepTitle_(plan, stepId);
  var total = stepTopicSlotTotalForCount_(ordered.length);
  ordered.forEach(function(d, i){
    if(!d) return;
    applyDraftRoadmapAssignment_(d, catId, stepId, title || '', i + 1, Math.max(total, 1));
    try { ensurePendingAssignmentForDraft_(catId, stepId, i + 1, d.id); } catch(eA){}
  });
  try { densifyStepSlotTotalsOnly_(catId, stepId); } catch(eD){}
}

/** 저장·렌더 없이 단계 배정만 바꾼다. 일괄 이동은 끝에서 한 번만 save. */
function relocateDraftToStepNoSave_(catId, draft, targetStepId, beforeDraftId){
  var cat = CATEGORIES[catId];
  if(!cat || !draft || !draft.id || !targetStepId) return null;
  var plan = getSubGoalPlan_(catId);
  if(!plan) return null;
  if(targetStepId !== SUBGOAL_MISC_ID){
    var ok = (plan.steps || []).some(function(s){ return s && String(s.id) === targetStepId; });
    if(!ok) return null;
  }
  var draftId = draft.id;
  var di = cat.drafts.indexOf(draft);
  var fromStep = String(getDraftRoadmapStepId_(draft, catId, di) || '');
  var peers = getDraftsForSubGoalStep_(catId, targetStepId, { live: true }).filter(function(d){
    return d && d.id && d.id !== draftId;
  });
  var insertAt = peers.length;
  if(beforeDraftId){
    for(var i = 0; i < peers.length; i++){
      if(peers[i] && peers[i].id === beforeDraftId){ insertAt = i; break; }
    }
  }
  var ordered = peers.slice();
  ordered.splice(insertAt, 0, draft);
  var sameStep = fromStep === targetStepId;
  if(sameStep && beforeDraftId === draftId) return null;
  reindexDraftsInStep_(catId, targetStepId, ordered);
  if(!sameStep && fromStep){
    var left = getDraftsForSubGoalStep_(catId, fromStep, { live: true }).filter(function(d){
      return d && d.id && d.id !== draftId;
    });
    reindexDraftsInStep_(catId, fromStep, left);
  }
  return { sameStep: sameStep, fromStep: fromStep };
}

window.dropDraftOnStep_ = function(catId, draftId, targetStepId, beforeDraftId){
  catId = parseInt(catId, 10);
  targetStepId = String(targetStepId || '');
  beforeDraftId = beforeDraftId ? String(beforeDraftId) : '';
  var cat = CATEGORIES[catId];
  if(!cat || !draftId || !targetStepId) return;
  var draft = (cat.drafts || []).find(function(d){ return d && d.id === draftId; });
  if(!draft){
    if(typeof setAppToast === 'function') setAppToast('주제를 찾을 수 없어요.', { duration: 3200 });
    return;
  }
  var moved = relocateDraftToStepNoSave_(catId, draft, targetStepId, beforeDraftId);
  if(!moved) return;
  var sameStep = moved.sameStep;
  save({ driveImmediate: true, gasImmediate: true });
  renderMain();
  if(typeof setAppToast === 'function'){
    var t0 = draft.topic || '주제';
    var short = t0.length > 24 ? t0.slice(0, 24) + '…' : t0;
    var label = topicDropLabel_(catId, targetStepId);
    setAppToast(
      sameStep
        ? ('「' + short + '」 순서를 바꿨어요.')
        : ('「' + short + '」을(를) ' + label + '로 옮겼어요.'),
      { duration: 3000, variant: 'ok' }
    );
  }
};

/** 서랍 일괄 정리 규칙 — 단계 제목으로 현재 기획안의 단계 id를 찾는다. 주제 제목 2점·각도 1점. */
var BULK_STEP_KEYWORD_RULES_ = {
  '0': [
    { title: '치료상식', re: /딱\s*소리|마사지|도수치료|도수|카이로|기대|오해|몇\s*번|횟수|호전|치료\s*(후|받|중)|병원|원인\s*위치|통증\s*위치/g },
    { title: '목·등·어깨', re: /거북목|목디스크|경추|어깨|오십견|회전근|날개뼈|견갑|승모|등\s*(이|을|은|통증|뻐근|결림)|목(이|을|은|과|·|,|\s|$)/g },
    { title: '허리·골반·고관절', re: /허리|요통|디스크|골반|고관절|엉덩|좌골|천장관절|척추관|꼬리뼈/g },
    { title: '사지', re: /무릎|발목|발바닥|족저|팔꿈치|엘보|손목|손가락|다리|종아리|허벅지|햄스트링|아킬레스|팔(이|을|은|이|\s|$)|발(이|을|은|\s|$)/g },
    { title: '전신', re: /전신|재발|만성|온몸|여러\s*곳|자세\s*패턴|패턴|유지|습관|연결/g }
  ],
  '1': [
    { title: '운동상식', re: /운동상식|무엇부터|오해|기본|왜\s*움직|근력|순서|횟수/g },
    { title: '유연성·스트레칭', re: /스트레칭|유연|이완|뻣뻣|가동|햄스트링/g },
    { title: '자세·거북목·라운드 숄더', re: /자세|거북목|라운드|굽은\s*등|정렬|어깨\s*말림/g },
    { title: '앉기·걷기 생활습관', re: /앉|걷|보행|출퇴근|업무|책상|의자|계단|생활/g },
    { title: '코어 기능운동', re: /코어|기능\s*운동|복근|플랭크|버드독|균형|밸런스|호흡/g }
  ],
  '2': [
    { title: '얼굴상식', re: /얼굴\s*관리|얼굴상식|기대|오해|기본|작은\s*얼굴|효과/g },
    { title: '비대칭·한쪽 얼굴', re: /비대칭|짝짝이|한쪽|셀카|틀어/g },
    { title: '윤곽·이중턱·붓기', re: /윤곽|이중턱|붓기|부종|턱선|광대|팔자|처짐/g },
    { title: '턱관절·씹기', re: /턱관절|이갈|씹|저작|입\s*벌|딱딱\s*소리/g },
    { title: '목·자세와 얼굴', re: /목(이|을|은|과|·|,|\s|$)|자세|경추|거북목|어깨/g }
  ]
};

function countBulkKeywordHits_(re, text){
  if(!re || !text) return 0;
  re.lastIndex = 0;
  var m = String(text).match(re);
  return m ? m.length : 0;
}

/** 규칙 표가 없는 카테고리: 단계 제목을 ·/공백으로 쪼갠 2글자 이상 토큰 */
function buildBulkStepRulesForPlan_(catId, plan){
  var out = [];
  var covered = {};
  var table = BULK_STEP_KEYWORD_RULES_[String(catId)];
  if(table){
    table.forEach(function(r){
      var sid = findPlanStepIdByTitle_(plan, r.title);
      if(sid && !covered[sid]){
        covered[sid] = true;
        out.push({ stepId: sid, re: r.re });
      }
    });
  }
  (plan.steps || []).forEach(function(s){
    if(!s || !s.id || covered[String(s.id)]) return;
    var toks = String(s.title || '').split(/[·,\/\s]+/).filter(function(t){ return t.length >= 2; });
    if(!toks.length) return;
    var src = toks.map(function(t){ return t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }).join('|');
    out.push({ stepId: String(s.id), re: new RegExp(src, 'g') });
  });
  return out;
}

function suggestBulkStepForDraft_(rules, d){
  var topic = String((d && d.topic) || '');
  var angle = String((d && (d.angle || d.hook || '')) || '');
  var best = null;
  var bestScore = 0;
  var tie = false;
  rules.forEach(function(r){
    var score = countBulkKeywordHits_(r.re, topic) * 2 + countBulkKeywordHits_(r.re, angle);
    if(score > bestScore){ bestScore = score; best = r.stepId; tie = false; }
    else if(score && score === bestScore && r.stepId !== best){ tie = true; }
  });
  if(!best || tie) return { stepId: '', score: bestScore, tie: tie };
  return { stepId: best, score: bestScore, tie: false };
}

function canBulkReassignCategory_(catId){
  if(isDailyShareCategory(catId) || isOpsManualCategory(catId)) return false;
  var plan = getSubGoalPlan_(catId);
  return !!(plan && plan.steps && plan.steps.length);
}

/** 준비 글 + 완료 글(빈 기획 칸 제외). 이동 제안(moves), 규칙 미매칭(held), 같은 제목 중복(dups) */
function previewBulkReassignDraftSteps_(catId){
  catId = parseInt(catId, 10);
  var res = { catId: catId, moves: [], held: [], dups: [] };
  var cat = CATEGORIES[catId];
  if(!cat || !canBulkReassignCategory_(catId)) return res;
  var plan = getSubGoalPlan_(catId);
  res.dups = previewBulkDuplicateDrafts_(catId, plan);
  var rules = buildBulkStepRulesForPlan_(catId, plan);
  if(!rules.length) return res;
  (cat.drafts || []).forEach(function(d, di){
    if(!d || !d.id) return;
    if(draftIsShelfEmpty_(d, catId)) return;
    var cur = String(getDraftRoadmapStepId_(d, catId, di) || '');
    var sug = suggestBulkStepForDraft_(rules, d);
    var item = {
      draftId: d.id,
      topic: d.topic || '(제목 없음)',
      published: draftShowsOnPublishedList_(d.id, catId),
      fromStepId: cur,
      fromLabel: cur ? (cur === SUBGOAL_MISC_ID ? getSubGoalMiscLabel_(plan) : (getSubGoalStepTitle_(plan, cur) || cur)) : '미배정',
      toStepId: sug.stepId,
      toLabel: sug.stepId ? (getSubGoalStepTitle_(plan, sug.stepId) || sug.stepId) : ''
    };
    if(!sug.stepId){
      if(!cur || cur === SUBGOAL_MISC_ID) res.held.push(item);
      return;
    }
    if(sug.stepId === cur) return;
    res.moves.push(item);
  });
  return res;
}

function previewBulkDuplicateDrafts_(catId, plan){
  catId = parseInt(catId, 10);
  var cat = CATEGORIES[catId];
  var groups = [];
  if(!cat) return groups;
  plan = plan || peekSubGoalPlan_(catId) || getSubGoalPlan_(catId);
  var byKey = {};
  (cat.drafts || []).forEach(function(d, di){
    if(!d || !d.id) return;
    if(draftIsShelfEmpty_(d, catId)) return;
    var key = typeof normalizeTopicKey_ === 'function'
      ? normalizeTopicKey_(d.topic)
      : String(d.topic || '').replace(/\s+/g, '').toLowerCase();
    if(!key) return;
    if(!byKey[key]) byKey[key] = [];
    var cur = String(getDraftRoadmapStepId_(d, catId, di) || '');
    var hasDraft = !!(typeof draftHasContent === 'function' && draftHasContent(d)) ||
      !!(typeof draftIsPendingPublish_ === 'function' && draftIsPendingPublish_(d));
    byKey[key].push({
      draftId: d.id,
      topic: d.topic || '(제목 없음)',
      published: draftShowsOnPublishedList_(d.id, catId),
      hasDraft: hasDraft,
      stepLabel: cur
        ? (cur === SUBGOAL_MISC_ID ? getSubGoalMiscLabel_(plan) : (getSubGoalStepTitle_(plan, cur) || cur))
        : '미배정',
      score: draftDuplicateKeepScore_(d, catId)
    });
  });
  Object.keys(byKey).forEach(function(key){
    var list = byKey[key];
    if(list.length < 2) return;
    list.sort(function(a, b){ return (b.score || 0) - (a.score || 0); });
    var keep = list[0];
    groups.push({
      topic: keep.topic,
      keepId: keep.draftId,
      keepLabel: keep.stepLabel,
      keepPublished: keep.published,
      keepHasDraft: keep.hasDraft,
      drops: list.slice(1)
    });
  });
  return groups;
}

function bulkDupStatusLabel_(row){
  if(!row) return '';
  if(row.published) return '완료';
  if(row.hasDraft) return '초안';
  return '빈 카드';
}

/** items: [{draftId, toStepId}] — 기본은 끝에서 저장·렌더. skipSave 면 호출측에서 한 번만. */
function applyBulkReassignDraftSteps_(catId, items, opts){
  opts = opts || {};
  catId = parseInt(catId, 10);
  var cat = CATEGORIES[catId];
  if(!cat || !items || !items.length) return 0;
  var n = 0;
  items.forEach(function(it){
    if(!it || !it.draftId || !it.toStepId) return;
    var draft = (cat.drafts || []).find(function(d){ return d && d.id === it.draftId; });
    if(!draft) return;
    var r = relocateDraftToStepNoSave_(catId, draft, String(it.toStepId), null);
    if(r && !r.sameStep) n++;
  });
  if(n && !opts.skipSave){
    save({ driveImmediate: true, gasImmediate: true });
    renderMain();
  }
  return n;
}

var _bulkReassignPreview = null;

window.openBulkReassignModal_ = function(catId){
  catId = parseInt(catId != null ? catId : state.currentCat, 10);
  var ov = document.getElementById('bulk-reassign-overlay');
  if(!ov) return;
  if(!canBulkReassignCategory_(catId)){
    if(typeof setAppToast === 'function') setAppToast('이 카테고리는 단계 기획안이 있어야 정리할 수 있어요.', { duration: 3200 });
    return;
  }
  _bulkReassignPreview = previewBulkReassignDraftSteps_(catId);
  renderBulkReassignModalBody_();
  var wasOpen = ov.classList.contains('open');
  ov.classList.add('open');
  if(!wasOpen && typeof lockBodyScroll_ === 'function') lockBodyScroll_();
};

window.closeBulkReassignModal_ = function(e){
  if(e && e.target && e.target.id !== 'bulk-reassign-overlay') return;
  _bulkReassignPreview = null;
  dismissPlannerOverlayOpenState_('bulk-reassign-overlay');
};

function renderBulkReassignModalBody_(){
  var body = document.getElementById('bulk-reassign-body');
  var applyBtn = document.getElementById('bulk-reassign-apply');
  var titleEl = document.getElementById('bulk-reassign-title');
  var p = _bulkReassignPreview;
  if(!body || !p) return;
  var cat = CATEGORIES[p.catId];
  if(titleEl) titleEl.textContent = '서랍 정리 · ' + (cat ? cat.name : '');
  var dups = p.dups || [];
  var dupDropN = 0;
  dups.forEach(function(g){ dupDropN += (g.drops || []).length; });
  var html = '';
  if(dups.length){
    html += '<div class="bulk-reassign-section">' +
      '<div class="bulk-reassign-toolbar">' +
        '<span>중복 제목 <strong>' + dups.length + '</strong>묶음 · 체크한 복사본만 삭제</span>' +
        '<button type="button" class="bulk-reassign-toggle" onclick="toggleAllBulkDupDelete_()">전체 선택/해제</button>' +
      '</div><div class="bulk-reassign-dup-list">';
    dups.forEach(function(g){
      html += '<div class="bulk-reassign-dup-group">' +
        '<div class="bulk-reassign-topic">' + escapeHtml(g.topic) + '</div>' +
        '<div class="bulk-reassign-path">남김 · ' + escapeHtml(g.keepLabel || '미배정') +
          ' · ' + escapeHtml(bulkDupStatusLabel_({ published: g.keepPublished, hasDraft: g.keepHasDraft })) + '</div>';
      (g.drops || []).forEach(function(d){
        html += '<label class="bulk-reassign-row bulk-reassign-dup-row">' +
          '<input type="checkbox" class="bulk-reassign-dup-chk" data-draft-id="' + escapeHtml(d.draftId) +
            '" data-keep-id="' + escapeHtml(g.keepId) + '" checked onchange="updateBulkReassignApplyBtn_()">' +
          '<span class="bulk-reassign-txt">' +
            '<span class="bulk-reassign-topic">삭제 · ' + (d.published ? '<span class="bulk-reassign-pub">완료</span>' : '') +
              escapeHtml(d.stepLabel || '미배정') + '</span>' +
            '<span class="bulk-reassign-path">' + escapeHtml(bulkDupStatusLabel_(d)) + '</span>' +
          '</span>' +
        '</label>';
      });
      html += '</div>';
    });
    html += '</div></div>';
  }
  if(!p.moves.length){
    if(!dups.length){
      html += '<div class="bulk-reassign-empty">옮길 주제와 중복 제목이 없어요. 모두 맞는 서랍에 있거나, 제목만으로는 판단이 어려워요.</div>';
    }
  } else {
    html += '<div class="bulk-reassign-section">' +
      '<div class="bulk-reassign-toolbar">' +
        '<span>옮길 주제 <strong>' + p.moves.length + '</strong>개 · 체크한 것만 옮겨요</span>' +
        '<button type="button" class="bulk-reassign-toggle" onclick="toggleAllBulkReassign_()">전체 선택/해제</button>' +
      '</div><div class="bulk-reassign-list">';
    p.moves.forEach(function(m, i){
      html += '<label class="bulk-reassign-row">' +
        '<input type="checkbox" class="bulk-reassign-chk" data-idx="' + i + '" checked onchange="updateBulkReassignApplyBtn_()">' +
        '<span class="bulk-reassign-txt">' +
          '<span class="bulk-reassign-topic">' + (m.published ? '<span class="bulk-reassign-pub">완료</span>' : '') + escapeHtml(m.topic) + '</span>' +
          '<span class="bulk-reassign-path">' + escapeHtml(m.fromLabel) + ' → <strong>' + escapeHtml(m.toLabel) + '</strong></span>' +
        '</span>' +
      '</label>';
    });
    html += '</div></div>';
  }
  if(p.held.length){
    html += '<details class="bulk-reassign-held"><summary>보류 ' + p.held.length + '개 · 제목만으로 서랍을 정할 수 없어요 (직접 옮겨 주세요)</summary><ul>';
    p.held.forEach(function(h){
      html += '<li>' + (h.published ? '<span class="bulk-reassign-pub">완료</span>' : '') + escapeHtml(h.topic) + '</li>';
    });
    html += '</ul></details>';
  }
  body.innerHTML = html;
  if(applyBtn) applyBtn.style.display = (p.moves.length || dupDropN) ? '' : 'none';
  updateBulkReassignApplyBtn_();
}

window.toggleAllBulkReassign_ = function(){
  var chks = document.querySelectorAll('#bulk-reassign-body .bulk-reassign-chk');
  var anyOff = Array.prototype.some.call(chks, function(c){ return !c.checked; });
  Array.prototype.forEach.call(chks, function(c){ c.checked = anyOff; });
  updateBulkReassignApplyBtn_();
};

window.toggleAllBulkDupDelete_ = function(){
  var chks = document.querySelectorAll('#bulk-reassign-body .bulk-reassign-dup-chk');
  var anyOff = Array.prototype.some.call(chks, function(c){ return !c.checked; });
  Array.prototype.forEach.call(chks, function(c){ c.checked = anyOff; });
  updateBulkReassignApplyBtn_();
};

window.updateBulkReassignApplyBtn_ = function(){
  var btn = document.getElementById('bulk-reassign-apply');
  if(!btn) return;
  var nMove = document.querySelectorAll('#bulk-reassign-body .bulk-reassign-chk:checked').length;
  var nDup = document.querySelectorAll('#bulk-reassign-body .bulk-reassign-dup-chk:checked').length;
  btn.disabled = !nMove && !nDup;
  if(nMove && nDup) btn.textContent = '옮기기 ' + nMove + ' · 중복 ' + nDup + '개 삭제';
  else if(nDup) btn.textContent = '중복 ' + nDup + '개 삭제';
  else if(nMove) btn.textContent = '선택 ' + nMove + '개 옮기기';
  else btn.textContent = '옮기거나 삭제할 항목을 선택하세요';
};

window.applyBulkReassignFromModal_ = function(){
  var p = _bulkReassignPreview;
  if(!p) return;
  var dropIds = [];
  document.querySelectorAll('#bulk-reassign-body .bulk-reassign-dup-chk:checked').forEach(function(c){
    var id = c.getAttribute('data-draft-id');
    var keepId = c.getAttribute('data-keep-id');
    if(id && keepId) absorbDraftKeyedMaps_(id, keepId);
    if(id) dropIds.push(id);
  });
  var dropSet = {};
  dropIds.forEach(function(id){ dropSet[id] = true; });
  var items = [];
  document.querySelectorAll('#bulk-reassign-body .bulk-reassign-chk:checked').forEach(function(c){
    var m = p.moves[parseInt(c.getAttribute('data-idx'), 10)];
    if(m && m.draftId && !dropSet[m.draftId]) items.push({ draftId: m.draftId, toStepId: m.toStepId });
  });
  if(!items.length && !dropIds.length) return;
  var n = items.length ? applyBulkReassignDraftSteps_(p.catId, items, { skipSave: true }) : 0;
  dropIds.forEach(function(id){ deleteDraftSilent_(p.catId, id); });
  save({ driveImmediate: true, gasImmediate: true });
  closeBulkReassignModal_();
  renderMain();
  if(typeof setAppToast === 'function'){
    var parts = [];
    if(n) parts.push('주제 ' + n + '개를 서랍으로 옮겼어요');
    if(dropIds.length) parts.push('중복 ' + dropIds.length + '개를 삭제했어요');
    setAppToast(parts.length ? parts.join('. ') + '.' : '변경한 항목이 없어요.', { duration: 3600, variant: (n || dropIds.length) ? 'ok' : undefined });
  }
};

/** 주제 서랍 직접 편집 (도수·무브먼트·페이스·힐자계). 저장 시 plan.hubCustom → 시드 복구가 덮어쓰지 않음 */
var DRAWER_EDIT_MAX_ = 12;
var _drawerEdit = null;

window.openDrawerEditor_ = function(catId){
  catId = parseInt(catId != null ? catId : state.currentCat, 10);
  var ov = document.getElementById('drawer-edit-overlay');
  var plan = peekSubGoalPlan_(catId) || ensureProgramIdentityPlan_(catId);
  if(!ov || !plan) return;
  _drawerEdit = {
    catId: catId,
    custom: !!plan.hubCustom,
    rows: (plan.steps || []).filter(function(s){ return s && s.id; }).map(function(s){
      return {
        id: String(s.id),
        title: displaySubGoalStepTitle_(s.title || '', catId),
        rationale: String(s.rationale || s.summary || '').trim(),
        count: getDraftsForSubGoalStep_(catId, String(s.id), { live: true }).length
      };
    })
  };
  renderDrawerEditorBody_();
  var wasOpen = ov.classList.contains('open');
  ov.classList.add('open');
  if(!wasOpen && typeof lockBodyScroll_ === 'function') lockBodyScroll_();
};

window.closeDrawerEditor_ = function(e){
  if(e && e.target && e.target.id !== 'drawer-edit-overlay') return;
  _drawerEdit = null;
  dismissPlannerOverlayOpenState_('drawer-edit-overlay');
};

function renderDrawerEditorBody_(){
  var body = document.getElementById('drawer-edit-body');
  var titleEl = document.getElementById('drawer-edit-title');
  var ed = _drawerEdit;
  if(!body || !ed) return;
  var cat = CATEGORIES[ed.catId];
  if(titleEl) titleEl.textContent = '주제 서랍 · ' + (cat ? cat.name : '');
  var n = ed.rows.length;
  var html = '<div class="drawer-edit-list">';
  ed.rows.forEach(function(r, i){
    html += '<div class="drawer-edit-row ' + getStepToneClass_(i) + '">' +
      '<div class="drawer-edit-row-head">' +
        '<span class="drawer-edit-num">' + (i + 1) + '</span>' +
        '<input type="text" class="drawer-edit-title-input" maxlength="30" placeholder="서랍 이름" value="' + escapeHtml(r.title) + '" oninput="drawerEditSetField_(' + i + ',\'title\',this.value)">' +
        '<button type="button" class="drawer-edit-icon" title="위로" aria-label="위로"' + (i === 0 ? ' disabled' : '') + ' onclick="drawerEditMove_(' + i + ',-1)">↑</button>' +
        '<button type="button" class="drawer-edit-icon" title="아래로" aria-label="아래로"' + (i === n - 1 ? ' disabled' : '') + ' onclick="drawerEditMove_(' + i + ',1)">↓</button>' +
        '<button type="button" class="drawer-edit-icon drawer-edit-del" title="서랍 삭제" aria-label="서랍 삭제"' + (n <= 1 ? ' disabled' : '') + ' onclick="drawerEditRemove_(' + i + ')">×</button>' +
      '</div>' +
      '<textarea class="drawer-edit-intent" rows="2" placeholder="이 서랍에 어떤 글을 담을지 (선택)" oninput="drawerEditSetField_(' + i + ',\'rationale\',this.value)">' + escapeHtml(r.rationale) + '</textarea>' +
      (r.count ? '<div class="drawer-edit-count">주제 ' + r.count + '개</div>' : '') +
    '</div>';
  });
  html += '</div>';
  if(n < DRAWER_EDIT_MAX_){
    html += '<button type="button" class="drawer-edit-add" onclick="drawerEditAdd_()">+ 서랍 추가</button>';
  }
  html += '<p class="drawer-edit-note">서랍을 지우면 안에 있던 주제는 <strong>기타 주제</strong>로 옮겨져요.</p>';
  if(ed.custom){
    html += '<button type="button" class="drawer-edit-reset" onclick="drawerEditResetToSeed_()">기본 서랍으로 되돌리기</button>';
  }
  body.innerHTML = html;
}

window.drawerEditSetField_ = function(i, field, value){
  if(!_drawerEdit || !_drawerEdit.rows[i]) return;
  _drawerEdit.rows[i][field] = String(value || '');
};

window.drawerEditMove_ = function(i, dir){
  if(!_drawerEdit) return;
  var rows = _drawerEdit.rows;
  var j = i + dir;
  if(j < 0 || j >= rows.length) return;
  var tmp = rows[i]; rows[i] = rows[j]; rows[j] = tmp;
  renderDrawerEditorBody_();
};

window.drawerEditRemove_ = function(i){
  if(!_drawerEdit || _drawerEdit.rows.length <= 1) return;
  var r = _drawerEdit.rows[i];
  if(!r) return;
  if(r.count && !confirm('「' + (r.title || '이 서랍') + '」의 주제 ' + r.count + '개는 기타 주제로 옮겨져요. 지울까요?')) return;
  _drawerEdit.rows.splice(i, 1);
  renderDrawerEditorBody_();
};

window.drawerEditAdd_ = function(){
  if(!_drawerEdit || _drawerEdit.rows.length >= DRAWER_EDIT_MAX_) return;
  _drawerEdit.rows.push({ id: '', title: '', rationale: '', count: 0 });
  renderDrawerEditorBody_();
  var inputs = document.querySelectorAll('#drawer-edit-body .drawer-edit-title-input');
  if(inputs.length) inputs[inputs.length - 1].focus();
};

window.saveDrawerEditor_ = function(){
  var ed = _drawerEdit;
  if(!ed) return;
  var catId = ed.catId;
  var plan = peekSubGoalPlan_(catId);
  if(!plan) return;
  var rows = ed.rows.map(function(r){
    return { id: r.id, title: String(r.title || '').trim(), rationale: String(r.rationale || '').trim() };
  });
  if(!rows.length) return;
  var seen = {};
  for(var i = 0; i < rows.length; i++){
    if(!rows[i].title){
      setAppToast((i + 1) + '번 서랍 이름을 적어 주세요.', { duration: 3000, variant: 'err' });
      return;
    }
    var key = stepTitleDedupeKey_(rows[i].title);
    if(seen[key]){
      setAppToast('「' + rows[i].title + '」 서랍이 두 개예요. 이름을 다르게 적어 주세요.', { duration: 3400, variant: 'err' });
      return;
    }
    seen[key] = true;
  }
  var keepIds = {};
  rows.forEach(function(r){ if(r.id) keepIds[r.id] = true; });
  (plan.steps || []).forEach(function(s){
    if(!s || !s.id || keepIds[String(s.id)]) return;
    getDraftsForSubGoalStep_(catId, String(s.id), { live: true }).forEach(function(d){
      relocateDraftToStepNoSave_(catId, d, SUBGOAL_MISC_ID, null);
    });
  });
  // 정규화가 id를 위치(s1…sN)로 다시 매기며 연쇄 remap 하면 맞바꾼 서랍의 주제가 엇갈린다 → 목록을 먼저 잡고 직접 재배정
  var byId = {};
  var draftsById = {};
  (plan.steps || []).forEach(function(s){
    if(!s || !s.id) return;
    byId[String(s.id)] = s;
    draftsById[String(s.id)] = getDraftsForSubGoalStep_(catId, String(s.id), { live: true }).slice();
  });
  plan.steps = rows.map(function(r, i){
    var st = (r.id && byId[r.id]) ? byId[r.id] : { layer: '', pinned: false };
    st.id = 's' + (i + 1);
    st.title = r.title;
    st.rationale = r.rationale;
    st.summary = r.rationale.replace(/\s+/g, ' ').slice(0, 90);
    return st;
  });
  plan.hubCustom = true;
  plan.updatedAt = new Date().toISOString();
  rows.forEach(function(r, i){
    var list = (r.id && draftsById[r.id]) || [];
    if(list.length) reindexDraftsInStep_(catId, 's' + (i + 1), list);
  });
  save({ driveImmediate: true, gasImmediate: true });
  closeDrawerEditor_();
  renderMain();
  setAppToast('주제 서랍을 저장했어요.', { duration: 2800, variant: 'ok' });
};

window.drawerEditResetToSeed_ = function(){
  var ed = _drawerEdit;
  if(!ed) return;
  if(!confirm('기본 서랍 구성으로 되돌릴까요? 기본에 없는 서랍의 주제는 기타 주제로 옮겨져요.')) return;
  var plan = peekSubGoalPlan_(ed.catId);
  if(!plan) return;
  delete plan.hubCustom;
  plan.hubRev = '';
  syncCuriosityHubPlanFromSeed_(ed.catId);
  plan.updatedAt = new Date().toISOString();
  save({ driveImmediate: true, gasImmediate: true });
  closeDrawerEditor_();
  renderMain();
  setAppToast('기본 서랍으로 되돌렸어요.', { duration: 2800, variant: 'ok' });
};

function ensureTopicDragDropBound_(){
  var mc = document.getElementById('main-content');
  if(!mc || mc._topicDndBound) return;
  mc._topicDndBound = true;
  mc.addEventListener('dragstart', function(ev){
    var card = ev.target && ev.target.closest ? ev.target.closest('.draft-card.topic-line[data-draft-id]') : null;
    if(!card || !mc.contains(card)) return;
    if(ev.target && ev.target.closest && ev.target.closest('button, a, input, textarea, select')){
      ev.preventDefault();
      return;
    }
    var draftId = card.getAttribute('data-draft-id');
    var catId = parseInt(card.getAttribute('data-cat-id'), 10);
    if(!draftId || isNaN(catId)) return;
    _topicDragState.draftId = draftId;
    _topicDragState.catId = catId;
    _topicDragState.moved = false;
    _topicDragState.suppressClick = false;
    card.classList.add('is-dragging');
    try {
      ev.dataTransfer.effectAllowed = 'move';
      ev.dataTransfer.setData('text/plain', draftId);
      ev.dataTransfer.setData('application/x-planner-draft', JSON.stringify({ draftId: draftId, catId: catId }));
    } catch(eDt){}
  });
  mc.addEventListener('dragend', function(ev){
    var card = ev.target && ev.target.closest ? ev.target.closest('.draft-card.topic-line') : null;
    if(card) card.classList.remove('is-dragging');
    clearTopicDropHighlights_();
    if(_topicDragState.moved) _topicDragState.suppressClick = true;
    _topicDragState.draftId = '';
    _topicDragState.catId = null;
    _topicDragState.moved = false;
  });
  mc.addEventListener('dragover', function(ev){
    if(!_topicDragState.draftId) return;
    var block = ev.target && ev.target.closest ? ev.target.closest('.subgoal-step-block[data-drop-step]') : null;
    if(!block || !mc.contains(block)) return;
    ev.preventDefault();
    try { ev.dataTransfer.dropEffect = 'move'; } catch(eDf){}
    clearTopicDropHighlights_();
    block.classList.add('is-drop-target');
    var overCard = ev.target.closest('.draft-card.topic-line[data-draft-id]');
    if(overCard && overCard.getAttribute('data-draft-id') !== _topicDragState.draftId){
      var rect = overCard.getBoundingClientRect();
      var before = (ev.clientY - rect.top) < rect.height / 2;
      overCard.classList.add(before ? 'is-drop-before' : 'is-drop-after');
    }
  });
  mc.addEventListener('dragleave', function(ev){
    var block = ev.target && ev.target.closest ? ev.target.closest('.subgoal-step-block[data-drop-step]') : null;
    if(!block) return;
    var related = ev.relatedTarget;
    if(related && block.contains(related)) return;
    block.classList.remove('is-drop-target');
  });
  mc.addEventListener('drop', function(ev){
    if(!_topicDragState.draftId) return;
    var block = ev.target && ev.target.closest ? ev.target.closest('.subgoal-step-block[data-drop-step]') : null;
    if(!block || !mc.contains(block)) return;
    ev.preventDefault();
    ev.stopPropagation();
    var draftId = _topicDragState.draftId;
    var catId = _topicDragState.catId;
    var targetStep = block.getAttribute('data-drop-step');
    var dropCat = parseInt(block.getAttribute('data-drop-cat'), 10);
    if(!isNaN(dropCat)) catId = dropCat;
    var beforeId = null;
    var overCard = ev.target.closest('.draft-card.topic-line[data-draft-id]');
    if(overCard && overCard.getAttribute('data-draft-id') !== draftId){
      var rect = overCard.getBoundingClientRect();
      var before = (ev.clientY - rect.top) < rect.height / 2;
      if(before) beforeId = overCard.getAttribute('data-draft-id');
      else {
        var next = overCard.nextElementSibling;
        while(next && !(next.classList && next.classList.contains('draft-card'))){
          next = next.nextElementSibling;
        }
        beforeId = next ? next.getAttribute('data-draft-id') : null;
      }
    }
    _topicDragState.moved = true;
    _topicDragState.suppressClick = true;
    clearTopicDropHighlights_();
    dropDraftOnStep_(catId, draftId, targetStep, beforeId);
  });
}
window.moveDraftToCategory_ = function(fromCatId, draftId, toCatId){
  fromCatId = parseInt(fromCatId, 10);
  toCatId = parseInt(toCatId, 10);
  var from = CATEGORIES[fromCatId];
  var to = CATEGORIES[toCatId];
  if(!from || !to || fromCatId === toCatId || isOpsManualCategory(toCatId)) return;
  var src = null;
  var idx = -1;
  (from.drafts || []).forEach(function(d, i){
    if(d && d.id === draftId){ src = d; idx = i; }
  });
  if(!src){
    if(typeof setAppToast === 'function') setAppToast('주제를 찾을 수 없어요.', { duration: 3200 });
    return;
  }
  var destName = CAT_TAB_SHORT[toCatId] || to.name;
  var t0 = src.topic || '주제';
  var short = t0.length > 28 ? t0.slice(0, 28) + '…' : t0;
  if(!confirm('「' + short + '」을(를) 「' + destName + '」으로 옮길까요?')) return;
  var newId = makeExtraDraftId_(toCatId);
  var copy = cloneSyncValue_(src) || {};
  copy.id = newId;
  copy.updatedAt = new Date().toISOString();
  if(!copy.createdAt) copy.createdAt = copy.updatedAt;
  var ov = state.draftBrandOverrides && state.draftBrandOverrides[draftId];
  if(ov){
    ['topic', 'angle', 'pillar', 'rationale', 'writingBrief'].forEach(function(key){
      if(ov[key] != null && String(ov[key]).trim()) copy[key] = ov[key];
    });
  }
  delete copy.previousRoadmapStepId;
  delete copy.previousSeries;
  from.drafts.splice(idx, 1);
  if(!to.drafts) to.drafts = [];
  to.drafts.push(copy);
  function moveKeyed_(map, oldId, nextId){
    if(!map || !Object.prototype.hasOwnProperty.call(map, oldId)) return;
    map[nextId] = map[oldId];
    delete map[oldId];
  }
  moveKeyed_(state.published, draftId, newId);
  moveKeyed_(state.generatedOnly, draftId, newId);
  moveKeyed_(state.pinnedDraftIds, draftId, newId);
  if(state.draftBrandOverrides) delete state.draftBrandOverrides[draftId];
  if(typeof instaBgByDraft !== 'undefined') moveKeyed_(instaBgByDraft, draftId, newId);
  if(typeof threadsBgByDraft !== 'undefined') moveKeyed_(threadsBgByDraft, draftId, newId);
  if(!state.deletedDraftIds) state.deletedDraftIds = {};
  state.deletedDraftIds[draftId] = new Date().toISOString();
  var plan = (typeof peekSubGoalPlan_ === 'function' && peekSubGoalPlan_(toCatId)) || getSubGoalPlan_(toCatId);
  applyDraftRoadmapAssignment_(copy, toCatId, SUBGOAL_MISC_ID, getSubGoalMiscLabel_(plan), 1, 1, { dropRescueHints: true });
  if(state.selectedId === draftId){
    try { closeSheetUiOnly_(); } catch(eClose){}
    try { clearOpenDetailHash_(); } catch(eHash){}
  }
  save({ driveImmediate: true, gasImmediate: true });
  renderTabs();
  renderMain();
  if(typeof setAppToast === 'function') setAppToast('「' + short + '」을(를) ' + destName + ' 기타 주제로 옮겼어요.', { duration: 4200, variant: 'ok' });
};


const AUTO_TOPIC_REPLENISH_ENABLED_KEY = 'ht_auto_topic_replenish_enabled';
function isAutoTopicReplenishEnabled_(){
  try {
    return localStorage.getItem(AUTO_TOPIC_REPLENISH_ENABLED_KEY) === '1';
  } catch(e){ return false; }
}
function withDetailHashSyncLock_(fn){
  detailHashSyncLock_ = true;
  try { fn(); } finally { detailHashSyncLock_ = false; }
}
function clearOpenDetailHash_(){
  try {
    if(location.hash && /^#open\//.test(location.hash)){
      withDetailHashSyncLock_(function(){
        history.replaceState(null, '', location.pathname + (location.search || ''));
      });
    }
  } catch(e){}
}
function normalizeSheetTabForCategory_(tab, catId){
  tab = String(tab || '').toLowerCase();
  if(isThreadCategory(catId)) return (tab === 'thread' || tab === 'images') ? tab : '';
  if(isHeiljagyaeCategory(catId)) return (tab === 'community' || tab === 'images') ? tab : '';
  if(isBlogInstaCategory(catId)) return (tab === 'blog' || tab === 'insta' || tab === 'threads' || tab === 'images' || tab === 'news') ? tab : '';
  return '';
}
function setOpenDetailHash_(draftId, catId, tab){
  try {
    var h = 'open/' + encodeURIComponent(draftId) + '/' + catId;
    var safeTab = normalizeSheetTabForCategory_(tab, catId);
    if(safeTab) h += '/' + safeTab;
    withDetailHashSyncLock_(function(){
      if(location.hash === '#' + h) return;
      location.hash = h;
    });
  } catch(e){}
}
function closeSheetUiOnly_(){
  if(typeof forceCloseProgramColorPreview_ === 'function' && isProgramColorPreviewOpen_()){
    forceCloseProgramColorPreview_(true);
  }
  releaseModalFocusTrap_();
  var sheetEl = document.getElementById('detail-sheet');
  if(sheetEl){
    resetBottomSheet_(sheetEl);
    sheetEl.classList.remove('open');
  }
  state.selectedId = null;
  state.selectedCatId = null;
  var closeGen = ++_detailCloseGen_;
  setTimeout(function(){
    if(closeGen !== _detailCloseGen_) return;
    var ov = document.getElementById('detail-overlay');
    if(ov) ov.classList.remove('open');
    unlockBodyScroll_();
    scheduleAppToastLift_();
  }, 280);
}
function onPlannerHashChange_(){
  if(detailHashSyncLock_) return;
  var h = (location.hash || '').replace(/^#/, '');
  var m = h.match(/^open\/([^/]+)\/(\d+)(?:\/([a-z]+))?$/);
  if(!m){
    var ov = document.getElementById('detail-overlay');
    if(ov && ov.classList.contains('open')) closeSheetUiOnly_();
    return;
  }
  var draftId = decodeURIComponent(m[1]);
  var catId = parseInt(m[2], 10);
  var tab = normalizeSheetTabForCategory_(m[3], catId) || undefined;
  var detailOv = document.getElementById('detail-overlay');
  if(state.selectedId === draftId && detailOv && detailOv.classList.contains('open')){
    // 같은 초안이면 탭만 해시로 바뀐 경우 반영
    if(tab && tab !== state.activeTab && typeof switchTab === 'function'){
      switchTab(tab);
    }
    return;
  }
  if(catId != null && state.currentCat !== catId){
    state.currentCat = catId;
    renderTabs();
  }
  renderMain();
  openDetail(draftId, catId, tab, { skipHash: true });
}
function openDetailFromDeepLink_(draftId, catId, tab){
  if(catId != null && state.currentCat !== catId){
    state.currentCat = catId;
    renderTabs();
  }
  renderMain();
  openDetail(draftId, catId, tab);
}
function openNextPublishRecommendationFromEntry_(fallbackDraftId, fallbackCatId){
  var rec = getNextPublishRecommendation();
  if(rec && rec.draft && rec.draft.id){
    openDetailFromDeepLink_(rec.draft.id, rec.cat.id);
    return true;
  }
  if(fallbackDraftId && fallbackCatId != null && !draftIsPublished_(fallbackDraftId)){
    openDetailFromDeepLink_(fallbackDraftId, fallbackCatId);
    return true;
  }
  try {
    clearOpenDetailHash_();
  } catch(e){}
  renderMain();
  return false;
}
function consumeDeepLinkFromHash_(){
  var h = (location.hash || '').replace(/^#/, '');
  var m = h.match(/^open\/([^/]+)\/(\d+)(?:\/([a-z]+))?$/);
  if(!m) return;
  var draftId = decodeURIComponent(m[1]);
  var catId = parseInt(m[2], 10);
  var tab = normalizeSheetTabForCategory_(m[3], catId);
  if(tab){
    openDetailFromDeepLink_(draftId, catId, tab);
    return;
  }
  if(draftIsPublished_(draftId)){
    openNextPublishRecommendationFromEntry_(draftId, catId);
    return;
  }
  openDetailFromDeepLink_(draftId, catId);
}
function focusPlannerAndOpenDraft_(draftId, catId){
  try { window.focus(); } catch(e){}
  openDetailFromDeepLink_(draftId, catId);
}
function buildSheetTabsHTML(tab){
  const cid = state.selectedCatId;
  if(isThreadCategory(cid)){
    return `<div class="sheet-tabs-scroll"><div class="sheet-tabs">
    <button type="button" class="sheet-tab${tab==='thread'?' active':''}" onclick="switchTab('thread')">일상 공유</button>
    <button type="button" class="sheet-tab${tab==='images'?' active':''}" onclick="switchTab('images')">이미지</button>
  </div></div>`;
  }
  if(isHeiljagyaeCategory(cid)){
    return `<div class="sheet-tabs-scroll"><div class="sheet-tabs">
    <button type="button" class="sheet-tab${tab==='community'?' active':''}" onclick="switchTab('community')">게시판</button>
    <button type="button" class="sheet-tab${tab==='images'?' active':''}" onclick="switchTab('images')">이미지</button>
  </div></div>`;
  }
  return `<div class="sheet-tabs-scroll"><div class="sheet-tabs">
    <button type="button" class="sheet-tab${tab==='images'?' active':''}" onclick="switchTab('images')">이미지</button>
    <button type="button" class="sheet-tab${tab==='blog'?' active':''}" onclick="switchTab('blog')">블로그</button>
    <button type="button" class="sheet-tab${tab==='insta'?' active':''}" onclick="switchTab('insta')">인스타</button>
    <button type="button" class="sheet-tab${tab==='threads'?' active':''}" onclick="switchTab('threads')">쓰레드</button>
    <button type="button" class="sheet-tab${tab==='news'?' active':''}" onclick="switchTab('news')">소식</button>
  </div></div>`;
}
function composeSheetTabLayout_(tab, restHtml){
  return buildSheetTabsHTML(tab) + (restHtml || '');
}
function scrollSheetBodyToStart_(){
  var body = document.getElementById('sheet-body');
  if(!body) return;
  requestAnimationFrame(function(){
    body.scrollTop = 0;
    scheduleWorkshopTextareaGrow_(body);
  });
}

function clampMangoTitle_(s){
  return String(s || '').trim().slice(0, MANGO_DETAIL_TITLE_MAX);
}
function clampMangoIntro_(s){
  return String(s || '').trim().slice(0, MANGO_DETAIL_INTRO_MAX);
}

/** 블로그 제목이 길면 포인트를 살린 채 30자 이내로 줄임 */
function shortenMangoProductName_(raw){
  var s = String(raw || '').replace(/\s+/g, ' ').trim();
  s = s.replace(/^["'「『\s]+|["'」』\s]+$/g, '').trim();
  if(!s) return '';
  if(s.length <= MANGO_DETAIL_TITLE_MAX) return s;

  var parts = s.split(/\s*[—–―－|·|:：]\s*/).map(function(p){ return p.trim(); }).filter(Boolean);
  if(parts.length >= 2){
    var after = parts[parts.length - 1];
    var before = parts[0];
    // 대시 뒤가 핵심 포인트인 경우가 많음
    if(after.length >= 6 && after.length <= MANGO_DETAIL_TITLE_MAX) return after;
    if(before.length <= MANGO_DETAIL_TITLE_MAX) return before;
    // 앞·뒤를 짧게 합치기
    var room = MANGO_DETAIL_TITLE_MAX - 1;
    var aLen = Math.min(after.length, Math.floor(room * 0.45));
    var bLen = room - aLen;
    var combo = before.slice(0, bLen).replace(/[\s,，、]+$/,'') + ' ' + after.slice(0, aLen).replace(/^[\s,，、]+/,'');
    if(combo.length >= 8 && combo.length <= MANGO_DETAIL_TITLE_MAX) return combo;
  }

  // 물음표 질문형: 질문 문장만 남기기
  var q = s.match(/^(.+?[?？])/);
  if(q && q[1].length <= MANGO_DETAIL_TITLE_MAX) return q[1].trim();

  var cut = s.slice(0, MANGO_DETAIL_TITLE_MAX);
  var lastBreak = -1;
  for(var i = cut.length - 1; i >= 10; i--){
    if(/[\s,，、·・]/.test(cut.charAt(i))){ lastBreak = i; break; }
  }
  if(lastBreak > 0) return cut.slice(0, lastBreak).trim();
  var trimmed = cut.replace(/\s+\S*$/, '').trim();
  return (trimmed.length >= 8 ? trimmed : cut).slice(0, MANGO_DETAIL_TITLE_MAX);
}

function normalizeMangoBrief_(brief){
  if(!brief || typeof brief !== 'object') return null;
  var intro = clampMangoIntro_(brief.intro || brief.mangoInputPaste || '');
  var paste = clampMangoIntro_(brief.mangoInputPaste || intro);
  if(!paste) paste = intro;
  if(!intro) intro = paste;
  return {
    productName: shortenMangoProductName_(brief.productName || '') || clampMangoTitle_(brief.productName || ''),
    intro: intro,
    features: Array.isArray(brief.features) ? brief.features.map(function(f){ return String(f || '').trim(); }).filter(Boolean).slice(0, 8) : [],
    slidePlan: Array.isArray(brief.slidePlan) ? brief.slidePlan.slice(0, 7) : [],
    designTone: brief.designTone != null ? String(brief.designTone) : '',
    photoTip: brief.photoTip != null ? String(brief.photoTip) : '',
    mangoInputPaste: paste
  };
}

function normalizeImagesBlock(raw){
  if(!raw || typeof raw !== 'object') return null;
  return {
    gptVisuals: Array.isArray(raw.gptVisuals) ? raw.gptVisuals : [],
    mangoBrief: normalizeMangoBrief_(raw.mangoBrief)
  };
}

/** 구형 2장(썸네일+본문) 초안 호환 — 힐자계·레거시 */
function trimBlogInstaImages_(gptVisuals){
  var list = (gptVisuals || []).filter(function(x){ return x && x.prompt; });
  if(list.length <= 2) return list;
  function isThumb(x){
    return x.role === 'thumbnail' || x.role === 'problem' || x.role === 'cover' ||
      (/썸네일|thumbnail|①|표지|공감|문제/i.test(String(x.title || '')) &&
        !/②|③|본문|동작|시연|셀프|원리|body|selfCare|explanation/i.test(String(x.title || '')));
  }
  function isBody(x){
    return x.role === 'body' || x.role === 'selfCare' ||
      /②|본문|동작|시연|셀프|body|stretch|exercise|self/i.test(String(x.title || ''));
  }
  var thumb = list.find(isThumb);
  var body = list.find(function(x){ return isBody(x) && x !== thumb; });
  if(thumb && body) return [thumb, body];
  if(thumb){
    var rest = list.filter(function(x){ return x !== thumb; });
    var bodyAlt = rest.find(isBody) || rest[0];
    if(bodyAlt) return [thumb, bodyAlt];
  }
  var self = list.find(isBody);
  var scene = list.find(function(x){
    return /썸네일|thumbnail|공감|일상|클로즈|close|cover|문제/i.test(String(x.title || ''));
  });
  if(scene && self && scene !== self) return [scene, self];
  if(list.length >= 5) return [list[0], list[list.length - 1]].filter(Boolean);
  return list.slice(0, 2);
}

function sortMangoBlogVisuals_(list){
  var rank = {
    problem: 0, cover: 0, thumbnail: 0, hook: 0,
    selfCare: 1, body: 1, demo: 1, outline: 1,
    explanation: 2, principle: 2, draft: 2
  };
  return (list || []).slice().sort(function(a, b){
    var ra = a && a.role != null && rank[a.role] != null ? rank[a.role] : 9;
    var rb = b && b.role != null && rank[b.role] != null ? rank[b.role] : 9;
    if(ra !== rb) return ra - rb;
    return 0;
  });
}

/** 이미지 탭·저장·복사에 쓰는 정규화 목록 */
function getDisplayGptVisuals_(gptVisuals, catId){
  var raw = (gptVisuals || []).filter(function(x){ return x && x.prompt; });
  var cap = getImageSlotCount(catId) || 2;
  if(isDailyShareCategory(catId)) return [];
  if(isHeiljagyaeCategory(catId)) return trimBlogInstaImages_(raw).slice(0, 2);
  if(raw.length <= cap) return sortMangoBlogVisuals_(raw);
  // 슬롯이 많으면 역할 순으로 cap장만
  var sorted = sortMangoBlogVisuals_(raw);
  var picked = [];
  var want = ['problem', 'selfCare', 'explanation'];
  want.forEach(function(role){
    if(picked.length >= cap) return;
    var hit = sorted.find(function(x){ return x.role === role && picked.indexOf(x) < 0; });
    if(hit) picked.push(hit);
  });
  sorted.forEach(function(x){
    if(picked.length >= cap) return;
    if(picked.indexOf(x) < 0) picked.push(x);
  });
  return picked.slice(0, cap);
}

function normalizeContentImages_(content, catId){
  if(!content || !content.images) return content;
  if(content.images.gptVisuals){
    content.images.gptVisuals = getDisplayGptVisuals_(content.images.gptVisuals, catId);
  }
  enrichImageOverlays_(content, catId);
  return content;
}

function getCommunityProblemText_(c){
  if(!c) return '';
  if(c.problem && String(c.problem).trim()) return String(c.problem).trim();
  var parts = [];
  if(c.empathyLead && String(c.empathyLead).trim()) parts.push(String(c.empathyLead).trim());
  if(c.empathyBullets && c.empathyBullets.length){
    c.empathyBullets.forEach(function(b){
      var t = String(b || '').replace(/^[\s•]+/, '').trim();
      if(t) parts.push(t);
    });
  }
  return parts.join('\n');
}

function normalizeCommunityBlock(raw){
  if(!raw || typeof raw !== 'object') return null;
  var problem = raw.problem != null ? String(raw.problem).trim() : '';
  if(!problem) problem = getCommunityProblemText_(raw);
  return {
    title: raw.title != null ? String(raw.title) : '',
    problem: problem,
    empathyLead: raw.empathyLead != null ? String(raw.empathyLead) : '',
    empathyBullets: Array.isArray(raw.empathyBullets) ? raw.empathyBullets.filter(Boolean).slice(0, 3) : [],
    explanation: raw.explanation != null ? String(raw.explanation) : '',
    selfCare: raw.selfCare != null ? String(raw.selfCare) : '',
  };
}

function normalizeThreadBlock(raw){
  if(!raw || typeof raw !== 'object') return null;
  var topicTitle = raw.topicTitle != null ? String(raw.topicTitle).trim() : '';
  var summary = raw.summary != null ? String(raw.summary).trim() : (raw.body != null ? String(raw.body).trim() : '');
  var posts = Array.isArray(raw.posts) ? raw.posts.map(function(p){ return String(p).trim(); }).filter(Boolean) : [];
  if(!summary && posts.length){
    summary = posts.join(' ');
  }
  if(!summary) return null;
  return { topicTitle: topicTitle, summary: summary };
}

function getThreadPlainText(th){
  if(!th || !th.summary) return '';
  return (th.topicTitle ? th.topicTitle + '\n\n' : '') + th.summary;
}

function formatCommunityPostText(c){
  if(!c) return '';
  const co = normalizeCommunityBlock(c) || c;
  return [
    (co.title || '').trim(),
    '',
    COMMUNITY_FIXED_GREETING,
    '',
    ensureProseParagraphBreaks_(getCommunityProblemText_(co)),
    '',
    formatSelfCareStepsForCopy_(co.selfCare || ''),
    '',
    ensureProseParagraphBreaks_(co.explanation || ''),
    '',
    COMMUNITY_FIXED_CLOSING
  ].join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function isStructuredGeneralBlog_(b){
  if(!b) return false;
  return !!(b.problem || b.selfCare || b.explanation);
}
function blogUsesStructuredGeneralFormat_(catId, b){
  return isGeneralAudienceCategory(catId) || isStructuredGeneralBlog_(b);
}
function getGeneralBlogProblemText_(b){
  if(!b) return '';
  if(b.problem && String(b.problem).trim()) return String(b.problem).trim();
  if(b.hook && String(b.hook).trim()) return String(b.hook).trim();
  return '';
}
function normalizeBlogBlock(raw, catId){
  if(!raw || typeof raw !== 'object') return null;
  if(blogUsesStructuredGeneralFormat_(catId, raw)){
    var problem = raw.problem != null ? String(raw.problem).trim() : '';
    if(!problem) problem = getGeneralBlogProblemText_(raw);
    return {
      title: raw.title != null ? String(raw.title).trim() : '',
      problem: problem,
      selfCare: raw.selfCare != null ? String(raw.selfCare).trim() : '',
      explanation: raw.explanation != null ? String(raw.explanation).trim() : '',
      cta: raw.cta != null ? String(raw.cta).trim() : '',
      hashtags: Array.isArray(raw.hashtags) ? raw.hashtags.filter(Boolean) : [],
      hook: raw.hook != null ? String(raw.hook) : '',
      outline: Array.isArray(raw.outline) ? raw.outline : [],
      draft: raw.draft != null ? String(raw.draft) : ''
    };
  }
  return {
    title: raw.title != null ? String(raw.title) : '',
    hook: raw.hook != null ? String(raw.hook) : '',
    outline: Array.isArray(raw.outline) ? raw.outline : [],
    draft: raw.draft != null ? String(raw.draft) : '',
    cta: raw.cta != null ? String(raw.cta) : '',
    hashtags: Array.isArray(raw.hashtags) ? raw.hashtags.filter(Boolean) : []
  };
}
function formatGeneralBlogPostText(b, catId){
  if(!b) return '';
  var tags = (b.hashtags || []).map(function(h){ return '#' + String(h).replace(/^#/, ''); }).join(' ');
  var body = [
    (b.title || '').trim(),
    '',
    ensureProseParagraphBreaks_(getGeneralBlogProblemText_(b)),
    '',
    formatSelfCareStepsForCopy_(b.selfCare || ''),
    '',
    ensureProseParagraphBreaks_(b.explanation || ''),
    '',
    ensureProseParagraphBreaks_(b.cta || ''),
    tags
  ].filter(function(p, i, arr){
    if(i === 0) return true;
    return String(p || '').trim();
  }).join('\n').replace(/\n{3,}/g, '\n\n').trim();
  return withExpertCourseBlogFooter_(withRealMovementBlogFooter_(body, catId), catId);
}
function blogHasMinimumContent_(catId, b){
  if(!b || !String(b.title || '').trim()) return false;
  if(blogUsesStructuredGeneralFormat_(catId, b)){
    return !!(getGeneralBlogProblemText_(b) || String(b.selfCare || '').trim());
  }
  return !!String(b.draft || '').trim();
}

function buildImagePromptGuide(topic, angle, customGuide, catId){
  const t = String(topic || '').trim();
  const a = String(angle || '').trim();
  const g = String(customGuide || '').trim();
  const id = parseInt(catId, 10);
  const pillar = CAT_DEFAULT_PILLAR[id] || '';
  const p = getMangoPaletteForCat_(id);
  const tone = getMangoDesignToneLine_(id);
  var model = getMangoModelGuideForCat_(id);
  return `
[본문 삽입 사진 + 선택 망고보드]
이번 초안 주제: "${t}"
작성 각도: "${a}"
${pillar ? '프로그램 톤: ' + pillar : ''}
인물: ${model.briefHint} (${model.label})

${BLOG_INSERT_GPT_VISUALS_RULE}

[부차 mangoBrief — 빈 칸이어도 됨. 채울 때만 아래 형식]
${getMangoDetailBriefRule_(id)}
- productName: 「제품명 혹은 주제」 **최대 ${MANGO_DETAIL_TITLE_MAX}자**, blog.title 축약
- intro / mangoInputPaste: 「소개」 **최대 ${MANGO_DETAIL_INTRO_MAX}자**, **동일 한글**. 【1~7장】이미지용 헤드+불릿. **블로그 원문·말줄임(…) 금지**
- intro **맨 끝**에 [디자인]+[레이아웃] (배경 ${p.bg}·${p.bg2}, 글·헤드 ${p.head}, 포인트 ${p.point}, 카드 ${p.card}·${p.card2}, 구분선 ${p.divider || p.head}${isMangoSparseAccentCat_(id) ? ' · 【필수】포인트는 작은 체크·기호·키워드만 · 빨강 전체 배경·큰 빨간 원 아이콘·넓은 면 채움 금지 · 표지 스크림은 차콜만' : ''}, 지정 외 색·흑백 모노 금지, 표 금지, 쉬운 말, ${model.briefHint}, 한발서기만 X·일상 전/후)
- photoTip: 실사·시연 (${model.label} 모델) 1~2문장
- slidePlan: 정확히 7개 — 각 장은 한 메시지, 표 없음, copyHint는 짧은 헤드
- designTone: ${tone}

${g ? '[카테고리별 이미지 지침]\n' + g : ''}
`;
}

function buildHeiljagyaeImagePromptGuide(topic, angle, customGuide){
  const t = String(topic || '').trim();
  const a = String(angle || '').trim();
  const g = String(customGuide || '').trim();
  return `
[힐자계 이미지 — 망고보드 AI 디자이너]
주제: "${t}" / 각도: "${a}"
community.selfCare(따라하기)를 보고 **images.gptVisuals 2개**(상황 컷 + 따라하기 컷)에 **한글** 프롬프트를 디테일하게 작성하세요.
따라하기 컷이 핵심입니다. 동작·손 위치·자세가 보이도록. mangoBrief는 null.
${g ? '\n[카테고리 이미지 지침]\n' + g : ''}
`;
}

function formatMangoBriefPaste_(brief, catId){
  if(!brief) return '';
  // 소개란 = intro/mangoInputPaste + 디자인 블록(망고보드가 색을 읽도록)
  return ensureMangoIntroHasDesignBlock_(brief.intro || brief.mangoInputPaste || '', catId);
}

function formatMangoTitlePaste_(brief){
  if(!brief) return '';
  return shortenMangoProductName_(brief.productName || '') || clampMangoTitle_(brief.productName || '');
}

function mangoIntroMatchesPalette_(body, palette){
  if(!body || !palette) return false;
  if(!/\[디자인\]/.test(body) || !/\[레이아웃\]/.test(body)) return false;
  // bg·head·point·divider 가 모두 본문에 있어야 최신 팔레트로 간주 (예: head만 #333333로 남는 경우 방지)
  var must = ['bg', 'head', 'point', 'divider'];
  for(var i = 0; i < must.length; i++){
    var hex = String(palette[must[i]] || '').replace(/^#/, '');
    if(!hex) continue;
    if(!new RegExp('#' + hex, 'i').test(body)) return false;
  }
  // 카드 색도 있으면 함께 확인 (잘린 intro 대비 optional)
  var card = String(palette.card || '').replace(/^#/, '');
  if(card && !new RegExp('#' + card, 'i').test(body)) return false;
  return true;
}

/** 구버전 팔레트·하드코딩 색이 남아 있으면 디자인 블록 재작성 */
function mangoIntroHasStalePaletteColors_(body, palette){
  var t = String(body || '');
  if(!t) return false;
  var head = String(palette && palette.head || '').toLowerCase();
  var point = String(palette && palette.point || '').toLowerCase();
  // 리:얼 무브먼트 등에서 자주 남던 구형 헤드·주의 포인트
  if(/#333333\b/i.test(t) && head && head !== '#333333') return true;
  if(/#474747\b/i.test(t) && point && point !== '#474747') return true;
  // 구형 무브먼트 팔레트(차콜·쿨그레이) → 크림슨 팔레트로 교체
  if(/#576169\b/i.test(t) && point && point !== '#576169') return true;
  if(/#1a1a1a\b/i.test(t) && head && head !== '#1a1a1a') return true;
  // 예전 크림·테라코타 잔재
  if(/#eddcd2|#c4785a|#b07a62/i.test(t)) return true;
  return false;
}

/** 리:얼 무브먼트 7장(다음) — 잘린·영문 잔여 카피를 고정 문구로 교체 */
function repairMangoMovementNextSlide_(body, catId){
  if(Number(catId) !== 1 && Number(catId) !== 5) return body;
  var t = String(body || '');
  if(!/【\s*7\.\s*다음】/.test(t)) return t;
  var nextBlock = mangoFormatSlideBlock_(7, '다음', '다음에 할 일', [
    '오늘 글처럼, 뭉침의 원인과 결과를 구분하는 것부터 시작해요',
    '\'왜 안 풀리는지\'를 먼저 이해하고 나면, 그다음 움직임이 달라져요'
  ], 'CTA 한 줄, 여백 넉넉히');
  return t.replace(
    /【\s*7\.\s*다음】[\s\S]*?(?=\n*【|\n*\[디자인\]|\n*\[레이아웃\]|$)/i,
    nextBlock + '\n\n'
  );
}

/** 소개 끝에 [디자인]·[레이아웃] 지침이 없으면 붙임 (카테고리 팔레트 기준, 디자인 블록은 잘리지 않게 본문만 줄임) */
function ensureMangoIntroHasDesignBlock_(intro, catId){
  var resolvedCatId = catId != null ? catId : state.selectedCatId;
  var palette = getMangoPaletteForCat_(resolvedCatId);
  var tone = buildMangoDesignToneLineFromPalette_(palette);
  var layoutPaste = getMangoLayoutPasteBlock_(resolvedCatId);
  var designBlock =
    '[디자인]\n' + tone +
    '\n\n[레이아웃]\n' + layoutPaste;
  var body = repairMangoMovementNextSlide_(String(intro || '').trim(), resolvedCatId);
  if(!body){
    return clampMangoIntro_(designBlock);
  }
  var layoutSec = '';
  var layoutMatch = body.match(/\n*\[레이아웃\]([\s\S]*)$/i);
  if(layoutMatch) layoutSec = layoutMatch[1] || '';
  // 레이아웃 블록 안에 로고·타이포 규칙이 있어야 최신으로 간주 (디자인 톤의 '우하단'만으로는 통과시키지 않음)
  var hasFreshLayout = /\[레이아웃\]/i.test(body) &&
    /로고:\s*우하단/.test(layoutSec) &&
    /타이포/.test(layoutSec);
  var model = getMangoModelGuideForCat_(resolvedCatId);
  var hasMatchingModel = model.gender === 'female'
    ? /인물=여성|여성 실사|여성 모델/.test(layoutSec)
    : model.gender === 'male'
      ? /인물=남성|남성 실사|남성 모델/.test(layoutSec)
      : true;
  var hasMatchingDesign = mangoIntroMatchesPalette_(body, palette) && !mangoIntroHasStalePaletteColors_(body, palette);
  // 무브먼트·움직임: 크림슨 스파스 규칙이 디자인 블록에 없으면 갱신
  if(isMangoSparseAccentCat_(resolvedCatId) && !/체크·기호|핵심 키워드|포인트색.*금지|크림슨.*금지|차콜.*스크림|빨간 원|전체 배경/.test(body)){
    hasMatchingDesign = false;
  }
  if(hasMatchingDesign && hasFreshLayout && hasMatchingModel){
    if(body.length <= MANGO_DETAIL_INTRO_MAX) return body;
  }
  var stripped = body
    .replace(/\n*\[디자인\][\s\S]*?(?=\n*\[레이아웃\]|$)/i, '')
    .replace(/\n*\[레이아웃\][\s\S]*$/i, '')
    .replace(/\n*흑[·.\s]*백[·.\s]*미니멀[^\n]*/g, '')
    .replace(/\n*색:\s*배경\s*#[0-9a-fA-F]{3,8}[^\n]*/gi, '')
    .trim();
  if(!stripped) stripped = body.replace(/\n*\[디자인\][\s\S]*$/i, '').trim();
  // 본문 장 카피에 남은 구형 포인트·영문 프로그램명 정리
  var pointHex = String(palette.point || '#dc143c');
  var cardHex = String(palette.card || '#FAF6F0');
  var headHex = String(palette.head || '#333333');
  var cautionSparse = isMangoSparseAccentCat_(resolvedCatId)
    ? ('주의 안내 카드(헤드 ' + headHex + ' · 카드 ' + cardHex + ' · 체크만 포인트 ' + pointHex + ')')
    : ('주의 안내 카드(포인트 ' + pointHex + ' · 카드 ' + cardHex + ')');
  stripped = stripped
    .replace(/주의 안내 카드\([^)]*\)/gi, cautionSparse);
  if(typeof localizeProgramDisplayName_ === 'function'){
    stripped = localizeProgramDisplayName_(stripped);
  }
  if(typeof scrubNonClinicalTreatmentCopy_ === 'function'){
    stripped = scrubNonClinicalTreatmentCopy_(stripped, resolvedCatId);
  }
  var room = MANGO_DETAIL_INTRO_MAX - designBlock.length - 2;
  // 디자인 블록이 잘리지 않도록: room이 너무 작아도 본문만 줄이고 블록은 끝까지 유지
  if(room < 200) room = 200;
  if(stripped.length > room){
    var cut = stripped.slice(0, room);
    var br = Math.max(cut.lastIndexOf('\n\n'), cut.lastIndexOf('\n'));
    stripped = (br >= Math.floor(room * 0.55) ? cut.slice(0, br) : cut).trim();
  }
  var combined = stripped + '\n\n' + designBlock;
  if(combined.length > MANGO_DETAIL_INTRO_MAX){
    // 최후: 본문을 더 줄여 디자인 블록 전체 보존
    var keepDesign = designBlock.length + 2;
    var bodyRoom = MANGO_DETAIL_INTRO_MAX - keepDesign;
    if(bodyRoom < 80) bodyRoom = 80;
    stripped = stripped.slice(0, bodyRoom).trim();
    combined = stripped + '\n\n' + designBlock;
    if(combined.length > MANGO_DETAIL_INTRO_MAX){
      combined = combined.slice(0, MANGO_DETAIL_INTRO_MAX);
    }
  }
  return combined;
}

/** 망고보드: 소개란에 한 번에 붙인 뒤, 첫 줄(제목)만 잘라 제품명란으로 옮기기용 */
function formatMangoTitleAndIntroPaste_(title, intro, catId){
  var t = shortenMangoProductName_(title) || clampMangoTitle_(title);
  var body = ensureMangoIntroHasDesignBlock_(intro, catId);
  if(t && body) return t + '\n\n' + body;
  return t || body || '';
}

function readMangoTitleAndIntroFromSheet_(){
  var titleEl = document.getElementById('sheet-mango-title');
  var introEl = document.getElementById('sheet-mango-brief-paste');
  var content = state.published[state.selectedId]?.content || state.generatedOnly[state.selectedId];
  var brief = content && content.images && content.images.mangoBrief;
  var catId = state.selectedCatId;
  var title = titleEl ? String(titleEl.value || '').trim() : '';
  var intro = introEl ? String(introEl.value || '').trim() : '';
  if(!title) title = formatMangoTitlePaste_(brief);
  if(!intro) intro = formatMangoBriefPaste_(brief, catId);
  title = shortenMangoProductName_(title) || clampMangoTitle_(title);
  intro = ensureMangoIntroHasDesignBlock_(intro, catId);
  // 화면에 디자인 블록이 없으면 반영
  if(introEl && String(introEl.value || '').trim() !== intro){
    introEl.value = intro;
    if(typeof window.updateMangoFieldCounts_ === 'function') window.updateMangoFieldCounts_();
  }
  return { title: title, intro: intro, paste: formatMangoTitleAndIntroPaste_(title, intro, catId) };
}

function emptyMangoBrief_(catId){
  return {
    productName: '',
    intro: '',
    features: [],
    slidePlan: [],
    designTone: getMangoDesignToneLine_(catId),
    photoTip: getMangoModelGuideForCat_(catId).photoTip,
    mangoInputPaste: ''
  };
}

/** intro가 비었거나 디자인 톤만 있는 경우(붙여넣기 부적합) */
function isWeakMangoIntro_(s){
  var t = String(s || '').trim();
  if(!t) return true;
  if(t.length < 80) return true;
  // "[디자인] …" 만 있거나 디자인 톤만인 경우
  var withoutDesign = t.replace(/\n*\[디자인\][\s\S]*$/i, '').replace(/\n*\[레이아웃\][\s\S]*$/i, '').trim();
  if(!withoutDesign || withoutDesign.length < 60) return true;
  if(/디자인/i.test(t) && /흑[·.\s]*백|미니멀|로고는 후처리/i.test(t) && withoutDesign.length < 60) return true;
  if(/흑[·.\s]*백/.test(t) && /미니멀/.test(t) && /로고는 후처리|만화/.test(t) &&
    !/【\s*\d|헤드:|1\.\s*표지|문제 공감|셀프 케어|이런 분께/.test(t)) return true;
  return false;
}

/** 블로그 원문 붙여넣기·말줄임 등 이미지용으로 부적합한 구형 소개 */
function isLegacyBlogPasteMangoIntro_(s){
  var body = String(s || '')
    .replace(/\n*\[디자인\][\s\S]*$/i, '')
    .replace(/\n*\[레이아웃\][\s\S]*$/i, '')
    .trim();
  if(!body) return false;
  if(/헤드:\s*\S/.test(body) && /【\s*\d/.test(body)) return false;
  if(/…|\.\.\./.test(body)) return true;
  if(/1\.\s*표지/.test(body) && !/헤드:/.test(body)) return true;
  // 긴 산문만 있고 장 구분·불릿이 거의 없으면 덤프
  if(body.length > 900 && !/【\s*\d|STEP\s*\d/i.test(body) && (body.match(/•/g) || []).length < 3) return true;
  return false;
}

function trimMangoSection_(s, maxLen){
  var t = String(s || '').replace(/\s+/g, ' ').trim();
  if(!t) return '';
  if(t.length <= maxLen) return t;
  // 말줄임 대신 문장 경계에서 자름 (이미지용 — … 표시 안 함)
  var cut = t.slice(0, maxLen);
  var sp = cut.lastIndexOf(' ');
  var punct = Math.max(
    cut.lastIndexOf('.'), cut.lastIndexOf('。'),
    cut.lastIndexOf('요'), cut.lastIndexOf('다'),
    cut.lastIndexOf('까'), cut.lastIndexOf('죠'),
    cut.lastIndexOf('!'), cut.lastIndexOf('?'), cut.lastIndexOf('？')
  );
  if(punct >= Math.floor(maxLen * 0.4)) return cut.slice(0, punct + 1).trim();
  if(sp >= Math.floor(maxLen * 0.45)) return cut.slice(0, sp).trim();
  return cut.trim();
}

/** 산문에서 앞쪽 문장만 (이미지 헤드·불릿용 — 2000자 여유 반영) */
function mangoPickSentences_(text, maxCount, maxEach){
  maxCount = maxCount || 2;
  maxEach = maxEach || 52;
  var raw = String(text || '').replace(/\r\n/g, '\n').replace(/👉/g, '\n').trim();
  if(!raw) return [];
  var parts = [];
  if(typeof splitProseSentences_ === 'function'){
    parts = splitProseSentences_(raw.replace(/\n+/g, ' '));
  }
  if(!parts.length){
    parts = raw.split(/[.!?。？！]+/).map(function(x){ return x.trim(); }).filter(Boolean);
  }
  if(!parts.length) parts = [raw];
  var out = [];
  var seen = {};
  for(var i = 0; i < parts.length && out.length < maxCount; i++){
    var s = trimMangoSection_(parts[i].replace(/^[-•*]\s*/, '').replace(/^\d+[.)]\s*/, ''), maxEach);
    if(!s || s.length < 4) continue;
    var key = s.slice(0, 12);
    if(seen[key]) continue;
    seen[key] = 1;
    out.push(s);
  }
  return out;
}

function mangoStripStepPrefix_(s){
  return String(s || '')
    .replace(/^(👉|✅|▶|Step\s*\d+[.:)]?|\d+[.)]|[①②③④⑤⑥⑦⑧⑨⑩]|[-·•])\s*/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/** 셀프케어 → STEP 줄 (동작·초·회 우선) */
function mangoExtractSteps_(selfCare, maxSteps){
  maxSteps = maxSteps || 3;
  var raw = String(selfCare || '').trim();
  if(!raw) return [];
  var steps = (typeof parseSelfCareSteps_ === 'function') ? parseSelfCareSteps_(raw) : [raw];
  var out = [];
  var seen = {};
  for(var i = 0; i < steps.length && out.length < maxSteps; i++){
    var line = trimMangoSection_(mangoStripStepPrefix_(steps[i]), 56);
    if(!line || line.length < 4) continue;
    // 원리·주의 문장은 STEP에서 제외
    if(/병원|원리|때문에|왜냐하면|진단|치료/.test(line) && !/\d+\s*(초|회|분)/.test(line)) continue;
    var key = line.slice(0, 14);
    if(seen[key]) continue;
    seen[key] = 1;
    out.push(line);
  }
  return out;
}

function mangoFormatSlideBlock_(num, role, head, bullets, visual){
  var lines = ['【' + num + '. ' + role + '】'];
  var catId = (typeof state !== 'undefined' && state) ? state.selectedCatId : null;
  var h = scrubNonClinicalTreatmentCopy_(head, catId);
  if(h) lines.push('헤드: ' + h);
  (bullets || []).forEach(function(b){
    var line = scrubNonClinicalTreatmentCopy_(b, catId);
    if(line) lines.push('• ' + line);
  });
  if(visual) lines.push('비주얼: ' + visual);
  return lines.join('\n');
}

function getDraftTopicForMango_(draftId){
  draftId = draftId != null ? draftId : state.selectedId;
  if(!draftId) return '';
  var pub = state.published && state.published[draftId];
  if(pub && pub.topic) return String(pub.topic).trim();
  var catId = state.selectedCatId;
  var cat = CATEGORIES[catId];
  if(cat && Array.isArray(cat.drafts)){
    var hit = cat.drafts.find(function(d){ return d && d.id === draftId; });
    if(hit && hit.topic) return String(hit.topic).trim();
  }
  return '';
}

/** 블로그 → 망고보드용 장별 이미지 핵심 카피 (원문 붙여넣기·… 없음) */
function buildMangoBriefFromBlog_(content, topic, catId){
  catId = catId != null ? catId : state.selectedCatId;
  var palette = getMangoPaletteForCat_(catId);
  var blog = content && content.blog ? content.blog : null;
  var title = blog && String(blog.title || '').trim();
  var productName = shortenMangoProductName_(title || topic || '');
  var problem = '';
  var selfCare = '';
  var explanation = '';
  var cta = '';
  var hook = '';
  if(blog){
    problem = getGeneralBlogProblemText_(blog) || String(blog.problem || '').trim();
    selfCare = String(blog.selfCare || '').trim();
    explanation = String(blog.explanation || '').trim();
    cta = String(blog.cta || '').trim();
    hook = String(blog.hook || '').trim();
    if(!selfCare && !explanation && blog.draft){
      var draftBody = String(blog.draft || '').trim();
      if(draftBody) explanation = draftBody;
    }
    if(!problem && hook) problem = hook;
    if(!problem && Array.isArray(blog.outline) && blog.outline.length){
      problem = blog.outline.map(function(x){ return String(x || '').trim(); }).filter(Boolean).join(' ');
    }
  }

  var coverHead = trimMangoSection_(title || topic || hook || '유연한데 왜 자꾸 삐끗할까요?', 42);
  var problemSents = mangoPickSentences_(problem, 3, 52);
  var empathyHead = problemSents[0] || '스트레칭은 되는데 자꾸 삐끗해요';
  var empathyBullets = problemSents.slice(1, 3);
  if(!empathyBullets.length){
    empathyBullets = ['특정 동작에서 힘이 빠지는 느낌', '늘어나는 것과 버티는 힘은 다름'];
  }
  // 표지와 공감 헤드가 같으면 공감은 다른 각도
  if(empathyHead.slice(0, 10) === coverHead.slice(0, 10) && problemSents[1]){
    empathyHead = problemSents[1];
    empathyBullets = problemSents.slice(2, 3).concat(['일상에서 반복되는 흔들림']);
  }

  var audienceHead = '이런 분께 맞춰 정리했어요';
  var audienceBullets = [];
  if(/삐끗|접질|불안정|흔들/.test(problem + coverHead)){
    audienceBullets.push('잘 늘어나는데도 자주 삐끗하는 분');
  }
  if(/스트레칭|유연|가동/.test(problem + coverHead + selfCare)){
    audienceBullets.push('스트레칭만 열심히 해 온 분');
  }
  if(!audienceBullets.length){
    audienceBullets = ['움직임이 불안정하게 느껴지는 분', '무리하게 범위만 키워 온 분'];
  }
  audienceBullets = audienceBullets.slice(0, 2);

  var steps = mangoExtractSteps_(selfCare, 3);
  if(!steps.length){
    steps = [
      '지금 가능한 범위에서 10초만 정확히 버티기',
      '흔들리면 멈추고 범위 줄이기',
      '같은 동작 3회만 반복'
    ];
  }

  var whySents = mangoPickSentences_(explanation, 3, 52);
  var whyHead = whySents[0] || '범위보다 버티는 힘이 먼저예요';
  var whyBullets = whySents.slice(1, 3);
  if(!whyBullets.length){
    whyBullets = ['조절이 따라와야 움직임이 안전해요', '먼저 버티고, 그다음 범위를 넓혀요'];
  }
  // 원리 헤드가 공감과 겹치면 교체
  if(whyHead.slice(0, 12) === empathyHead.slice(0, 12)){
    whyHead = '왜 그런지, 한 줄로';
  }

  var cautionBullets = [
    '갑자기 아파지거나 저림·마비가 커지면 중단',
    '무리해서 늘리지 말고 병원 진료를 먼저'
  ];

  var ctaClean = String(cta || '').replace(/https?:\/\/\S+/g, '').replace(/\?hub=\w+/g, '');
  // 일반인 채널: Real Movement 등 영문 프로그램명 → 한글 표기
  if(typeof localizeProgramDisplayName_ === 'function'){
    ctaClean = localizeProgramDisplayName_(ctaClean);
  }
  if(typeof scrubNonClinicalTreatmentCopy_ === 'function'){
    ctaClean = scrubNonClinicalTreatmentCopy_(ctaClean, catId);
  }
  var ctaSents = mangoPickSentences_(ctaClean, 2, 52).map(function(s){
    var line = typeof localizeProgramDisplayName_ === 'function' ? localizeProgramDisplayName_(s) : s;
    return typeof scrubNonClinicalTreatmentCopy_ === 'function' ? scrubNonClinicalTreatmentCopy_(line, catId) : line;
  }).filter(function(s){
    // 잘린·어색한 영문 잔여·미완성 문장 제외
    if(!s || /Re:\s*Al/i.test(s)) return false;
    if(/[은는이가을를의]\s*$/.test(s)) return false;
    if(s.length < 12) return false;
    return true;
  });
  var nextBullets;
  if(Number(catId) === 1 || Number(catId) === 5){
    // 리:얼 무브먼트 — 7장 CTA는 고정 카피(블로그 CTA 잘림·영문 잔여 방지)
    nextBullets = [
      '오늘 글처럼, 뭉침의 원인과 결과를 구분하는 것부터 시작해요',
      '\'왜 안 풀리는지\'를 먼저 이해하고 나면, 그다음 움직임이 달라져요'
    ];
  } else if(ctaSents.length){
    nextBullets = ctaSents;
  } else {
    nextBullets = [
      '궁금하면 프로필·상담으로 문의해 주세요',
      '일반 정보이며 치료·진단이 아니에요'
    ];
  }

  var cautionVisual = isMangoSparseAccentCat_(catId)
    ? ('주의 안내 카드(헤드 ' + palette.head + ' · 카드 ' + palette.card + ' · 체크만 포인트 ' + palette.point + ')')
    : ('주의 안내 카드(포인트 ' + palette.point + ' · 카드 ' + palette.card + ')');
  var blocks = [
    mangoFormatSlideBlock_(1, '표지', coverHead, [], getMangoModelGuideForCat_(catId).visualCover),
    mangoFormatSlideBlock_(2, '공감', empathyHead, empathyBullets, '일상 장면(앉았다 일어서기·계단·방향 전환)'),
    mangoFormatSlideBlock_(3, '대상', audienceHead, audienceBullets, '주의·안내 카드형, 픽토그램 OK'),
    mangoFormatSlideBlock_(4, '따라하기', '지금 범위에서 이렇게', steps.map(function(s, i){ return 'STEP' + (i + 1) + ' ' + s; }), getMangoModelGuideForCat_(catId).visualStep),
    mangoFormatSlideBlock_(5, '원리', whyHead, whyBullets, '전/후 비교(스트레칭만 vs 버티며 움직이기)'),
    mangoFormatSlideBlock_(6, '주의', '이땐 따라 하지 마세요', cautionBullets, cautionVisual),
    mangoFormatSlideBlock_(7, '다음', '다음에 할 일', nextBullets, 'CTA 한 줄, 여백 넉넉히')
  ];

  var intro = ensureMangoIntroHasDesignBlock_(blocks.join('\n\n'), catId);
  return {
    productName: productName,
    intro: intro,
    mangoInputPaste: intro,
    designTone: getMangoDesignToneLine_(catId)
  };
}

function fillMangoBriefFromContent_(content, opts){
  opts = opts || {};
  if(!content || !content.images) return content;
  var catId = opts.catId != null ? opts.catId : state.selectedCatId;
  if(isHeiljagyaeCategory(catId)) return content;
  var brief = content.images.mangoBrief;
  if(!brief || typeof brief !== 'object'){
    brief = emptyMangoBrief_(catId);
    content.images.mangoBrief = brief;
  } else {
    brief = normalizeMangoBrief_(brief) || emptyMangoBrief_(catId);
    content.images.mangoBrief = brief;
  }
  var topic = opts.topic || getDraftTopicForMango_(opts.draftId);
  // 시트 제목(블로그 주제)도 보조로 사용
  if(!topic){
    var titleEl = document.getElementById('sheet-title');
    if(titleEl) topic = String(titleEl.textContent || '').trim();
  }
  var combinedIntro = String(brief.intro || brief.mangoInputPaste || '').trim();
  // designTone이 intro로 잘못 들어온 경우도 감지
  if(!combinedIntro && brief.designTone && isWeakMangoIntro_(brief.designTone)){
    combinedIntro = '';
  }
  var needTitle = !String(brief.productName || '').trim();
  var fullTitle = (content.blog && String(content.blog.title || '').trim()) || topic || '';
  // 긴 제목을 그냥 앞에서 자른 상태면 포인트 살려 다시 줄임
  if(!needTitle && fullTitle.length > MANGO_DETAIL_TITLE_MAX){
    var cur = String(brief.productName || '').trim();
    if(cur === fullTitle.slice(0, MANGO_DETAIL_TITLE_MAX) || cur.length > MANGO_DETAIL_TITLE_MAX){
      needTitle = true;
    }
  }
  var needIntro = isWeakMangoIntro_(combinedIntro) ||
    isWeakMangoIntro_(brief.intro) ||
    isWeakMangoIntro_(brief.mangoInputPaste) ||
    isLegacyBlogPasteMangoIntro_(combinedIntro) ||
    isLegacyBlogPasteMangoIntro_(brief.intro) ||
    isLegacyBlogPasteMangoIntro_(brief.mangoInputPaste);
  if(needTitle || needIntro){
    var built = buildMangoBriefFromBlog_(content, topic, catId);
    if(needTitle && built.productName) brief.productName = built.productName;
    else if(brief.productName) brief.productName = shortenMangoProductName_(brief.productName);
    if(needIntro && built.intro){
      brief.intro = built.intro;
      brief.mangoInputPaste = built.intro;
    }
  } else {
    // intro·paste 동기화 + 제품명 30자 정리
    var intro = clampMangoIntro_(brief.intro || brief.mangoInputPaste || '');
    brief.intro = intro;
    brief.mangoInputPaste = intro;
    if(brief.productName) brief.productName = shortenMangoProductName_(brief.productName);
  }
  // 복사·망고보드용: 소개 끝에 카테고리 팔레트 디자인 블록 보장
  brief.intro = ensureMangoIntroHasDesignBlock_(brief.intro || brief.mangoInputPaste || '', catId);
  brief.mangoInputPaste = brief.intro;
  brief.designTone = getMangoDesignToneLine_(catId);
  var modelGuide = getMangoModelGuideForCat_(catId);
  var tip = String(brief.photoTip || '');
  var tipMismatch = !tip ||
    (modelGuide.gender === 'female' && /남성/.test(tip) && !/여성/.test(tip)) ||
    (modelGuide.gender === 'male' && /여성/.test(tip) && !/남성/.test(tip)) ||
    (modelGuide.gender === 'female' && !/여성/.test(tip)) ||
    (modelGuide.gender === 'male' && !/남성/.test(tip));
  if(tipMismatch) brief.photoTip = modelGuide.photoTip;
  content.images.mangoBrief = normalizeMangoBrief_(brief) || brief;
  return content;
}

function ensureMangoBriefOnContent_(content){
  if(!content || !content.images) return content;
  fillMangoBriefFromContent_(content, {
    catId: state.selectedCatId,
    draftId: state.selectedId,
    topic: getDraftTopicForMango_(state.selectedId)
  });
  return content;
}

function renderMangoDetailInputCard_(brief){
  var catId = state.selectedCatId;
  var p = getMangoPaletteForCat_(catId);
  brief = brief || emptyMangoBrief_(catId);
  var titleVal = formatMangoTitlePaste_(brief);
  var introVal = formatMangoBriefPaste_(brief, catId);
  var html = '';
  html += '<div class="img-section-title">선택 · 망고보드 7장 상세페이지</div>';
  html += '<p style="font-size:12px;color:#6B7280;margin:0 0 10px;line-height:1.55;">본문 삽입 사진이 우선입니다. 망고보드가 필요할 때만 주황 버튼으로 <strong>제목+소개</strong> 복사 → 소개란에 붙여넣고 첫 줄만 제품명으로. 소개는 <strong>장별 헤드+짧은 불릿</strong>(블로그 원문·… 붙여넣기 X). 결과물: <strong>' + escapeHtml(p.label) + '</strong> · 배경 <strong>' + escapeHtml(p.bg + '·' + p.bg2) + '</strong>·헤드 <strong>' + escapeHtml(p.head) + '</strong>·포인트 <strong>' + escapeHtml(p.point) + '</strong>' + (isMangoSparseAccentCat_(catId) ? '(작은 체크·기호만 · <strong>빨강 전체 배경·큰 빨간 원 아이콘 금지</strong> · 표지 스크림은 차콜만)' : '') + '·카드 <strong>' + escapeHtml(p.card + '·' + p.card2) + '</strong>·구분선 <strong>' + escapeHtml(p.divider || p.head) + '</strong>(지정 외 색·흑백 모노 X), 주의·안내형, ' + escapeHtml(getMangoModelGuideForCat_(catId).uiHint) + ', 픽토그램 OK.</p>';
  html += '<div class="img-tool-card">';
  html += '<label style="display:block;font-size:11px;color:#374151;margin:0 0 4px;">제품명 혹은 주제 <span id="sheet-mango-title-count" style="color:#9CA3AF;">' + titleVal.length + '/' + MANGO_DETAIL_TITLE_MAX + '</span></label>';
  html += '<input type="text" class="sheet-edit" id="sheet-mango-title" maxlength="' + MANGO_DETAIL_TITLE_MAX + '" value="' + escapeHtml(titleVal) + '" oninput="updateMangoFieldCounts_()" style="width:100%;margin-bottom:12px;padding:8px 10px;font-size:13px;border:1px solid #E5E7EB;border-radius:8px;box-sizing:border-box;">';
  html += '<label style="display:block;font-size:11px;color:#374151;margin:0 0 4px;">소개 (7장 · 이미지용 핵심 카피) <span id="sheet-mango-intro-count" style="color:#9CA3AF;">' + introVal.length + '/' + MANGO_DETAIL_INTRO_MAX + '</span></label>';
  html += '<textarea class="sheet-edit" id="sheet-mango-brief-paste" rows="10" maxlength="' + MANGO_DETAIL_INTRO_MAX + '" oninput="updateMangoFieldCounts_()">' + escapeHtml(introVal) + '</textarea>';
  if(brief.photoTip){
    html += '<div style="margin-top:10px;padding:10px 12px;background:#F5F3FF;border-radius:8px;font-size:12px;color:#5B21B6;line-height:1.55;"><strong>TIP · 참고 사진</strong><br>' + escapeHtml(brief.photoTip) + '</div>';
  } else {
    html += '<div style="margin-top:10px;padding:10px 12px;background:#F5F3FF;border-radius:8px;font-size:12px;color:#5B21B6;line-height:1.55;"><strong>TIP · 참고 사진</strong><br>서비스·시연 장면 사진을 올리세요. ② 셀프 케어 전신 컷(실사)을 권장합니다. 제품이 잘린 사진·글자만 있는 캡처는 피하세요.</div>';
  }
  html += '<div class="img-tool-actions" style="margin-top:10px;">';
  html += '<button type="button" class="img-tool-main-btn mango" onclick="copyMangoBriefAndOpen_()">망고보드 열기 · 제목·소개 복사</button>';
  html += '<button type="button" class="img-tool-copy-btn" onclick="copyMangoTitleOnly_()">제품명만 복사</button>';
  html += '<button type="button" class="img-tool-copy-btn" onclick="copyMangoBriefOnly_()">소개만 복사</button>';
  html += '<button type="button" class="img-tool-copy-btn" data-regen="mango" onclick="genContent(event)">소개 재생성</button>';
  html += '</div></div>';
  return html;
}

