const THUMB_SIZE_PRESETS = {
  '4x5': { w: 1080, h: 1350, label: '4:5 (인스타)' },
  '9x16': { w: 1080, h: 1920, label: '9:16 (스토리)' },
  '1x1': { w: 1080, h: 1080, label: '1:1 (정사각)' }
};

function getThumbBrandPreset_(catId){
  var id = parseInt(catId, 10);
  if(isNaN(id) || !THUMB_BRAND_PRESETS[id]) return THUMB_BRAND_PRESETS[1];
  return THUMB_BRAND_PRESETS[id];
}

/** 썸네일 하단 스크림 — THUMB_SCRIM_BY_CAT (망고 팔레트와 동일 hue) */
function getThumbPosterPaletteForCat_(catId){
  var id = parseInt(catId, 10);
  if(isNaN(id) || !THUMB_SCRIM_BY_CAT[id]) return THUMB_SCRIM_BY_CAT[1];
  return THUMB_SCRIM_BY_CAT[id];
}

function clampThumbLine_(text, maxLen){
  var s = String(text || '').replace(/\s+/g, ' ').trim();
  if(!s) return '';
  if(s.length <= maxLen) return s;
  return s.slice(0, Math.max(1, maxLen - 1)).replace(/\s+\S*$/, '') + '…';
}

/** 주제·키워드·초안에서 썸네일 카피 자동 채움 */
function buildThumbMakerCopy_(content, catId, opts){
  opts = opts || {};
  catId = catId != null ? catId : state.selectedCatId;
  var preset = getThumbBrandPreset_(catId);
  var programMode = opts.programMode || (window.__thumbMakerState && window.__thumbMakerState.programMode) || 'topic';
  var topic = getDraftTopicForMango_(state.selectedId);
  var title = '';
  var hook = '';
  var angle = '';
  var keywords = [];

  if(content && content._addForm){
    topic = String(content.addTopic || topic || '').trim();
    angle = String(content.addAngle || '').trim();
    title = String((content.blog && content.blog.title) || topic || '').trim();
    hook = String((content.blog && content.blog.hook) || angle || topic || '').trim();
    if(Array.isArray(content.addKeywords)){
      content.addKeywords.forEach(function(kw){
        var s = String(kw || '').trim();
        if(s && keywords.indexOf(s) < 0) keywords.push(clampThumbLine_(s, 28));
      });
    }
  }

  if(content && content.blog){
    title = String(content.blog.title || title || '').trim();
    hook = String(content.blog.hook || hook || '').trim();
    if(!hook) hook = getGeneralBlogProblemText_(content.blog) || String(content.blog.problem || '').trim();
  }
  if(content && content.community){
    if(!title) title = String(content.community.title || '').trim();
    if(!hook) hook = String(content.community.hook || content.community.problem || '').trim();
  }
  if(content && content.thread){
    if(!title) title = String(content.thread.topicTitle || '').trim();
    if(!hook) hook = String(content.thread.summary || '').trim();
  }
  if(content && content.images && content.images.mangoBrief){
    var pn = String(content.images.mangoBrief.productName || '').trim();
    if(pn && !title) title = pn;
  }

  var cat = CATEGORIES[catId];
  if(cat && Array.isArray(cat.drafts) && state.selectedId){
    var draft = cat.drafts.find(function(d){ return d && d.id === state.selectedId; });
    if(draft){
      if(!topic && draft.topic) topic = String(draft.topic).trim();
      if(draft.angle) angle = String(draft.angle).trim();
    }
  }

  // 키워드: 문장 분절 대신 제목·주제에서 의미 단위만
  [title, topic].forEach(function(chunk){
    var s = String(chunk || '').trim();
    if(s && keywords.indexOf(s) < 0) keywords.push(clampThumbLine_(s, 24));
  });
  if(angle) keywords.push(clampThumbLine_(angle, 28));

  var brandName = normalizeThumbBrandOneLine_(preset.hero) || preset.hero;
  var hero = brandName;
  var program = normalizeThumbBrandOneLine_(preset.program) || preset.program;
  if(programMode === 'topic'){
    // 그리드 후킹: 큰 타이틀 = 주제/제목, 그 아래 = 브랜드명
    var topicHero = (opts.preferTopic ? (topic || title) : (title || topic)) || '';
    topicHero = clampThumbLine_(topicHero, 32);
    if(topicHero.length >= 4){
      hero = topicHero;
      program = brandName;
    }
  }

  // preferTopic(「주제 다시 반영」): 훅보다 주제·각도·제목을 우선해 체감 변화를 만듦
  var bodySrc = opts.preferTopic
    ? (topic || title || angle || hook || preset.defaultBody)
    : (hook || angle || topic || title || preset.defaultBody);
  bodySrc = String(bodySrc).replace(/^[:：]\s*/, '').replace(/\s+/g, ' ').trim();
  if(!opts.preferTopic){
    var sentMatch = bodySrc.match(/^.{12,110}?[.。!?？]/);
    if(sentMatch) bodySrc = sentMatch[0];
  }
  bodySrc = clampThumbLine_(bodySrc, 108);
  if(!bodySrc) bodySrc = preset.defaultBody;
  // 핵심 문장 앞 `: ` 접두어 제거 (가독성·중복 브랜드명 방지)
  var body = bodySrc.replace(/^[:：]\s*/, '');
  body = scrubNonClinicalTreatmentCopy_(body, catId);
  if(!body) body = scrubNonClinicalTreatmentCopy_(preset.defaultBody, catId) || preset.defaultBody;

  return {
    hero: expandThumbHeroLinesForEdit_(hero),
    tagline: preset.tagline,
    program: program,
    body: body,
    keywords: keywords.slice(0, 4),
    brandProgram: normalizeThumbBrandOneLine_(preset.program) || preset.program
  };
}

function ensureThumbMakerState_(){
  if(!window.__thumbMakerState){
    window.__thumbMakerState = {
      bgDataUrl: null,
      bgImg: null,
      fileName: '',
      sizeKey: '4x5',
      lastCopy: null,
      fields: null,
      programMode: 'topic',
      draftId: null,
      catId: null,
      hitRegions: [],
      activeField: null,
      paintGen: 0,
      focusX: 0.5,
      focusY: 0.45,
      zoom: 1,
      outFocus: false,
      enhance: false,
      dragPan: null,
      galleryCache: null,
      _wsRestoreGen: 0,
      typeScale: 1,
      heroOneLine: false
    };
  }
  var st = window.__thumbMakerState;
  if(isThumbPhotoOnlyMode_()){
    st.programMode = 'photo';
    st.outFocus = false;
    st.sizeKey = '4x5';
  } else if(st.programMode === 'photo'){
    st.programMode = 'topic';
  }
  if(st.photoIndex == null) st.photoIndex = 0;
  if(st.programMode !== 'topic' && st.programMode !== 'brand' && st.programMode !== 'photo') st.programMode = 'topic';
  if(st.focusX == null) st.focusX = 0.5;
  if(st.focusY == null) st.focusY = 0.45;
  if(st.zoom == null) st.zoom = 1;
  if(st.typeScale == null) st.typeScale = 1;
  if(st.heroOneLine == null) st.heroOneLine = false;
  if(st.outFocus == null) st.outFocus = false;
  if(st.enhance == null) st.enhance = false;
  if(st.aiUpscaleOn == null) st.aiUpscaleOn = false;
  // 이전 버전 호환: BeforeUpscale → Original
  if(st.bgDataUrlBeforeUpscale && !st.bgDataUrlOriginal){
    st.bgDataUrlOriginal = st.bgDataUrlBeforeUpscale;
  }
  return st;
}

/** 초안별 작업 상태 · 최근 생성 5개 — 이 기기 IndexedDB (Drive 동기화 아님) */
const THUMB_WS_KEY_PREFIX = 'thumb_ws:';
const THUMB_GALLERY_KEY = 'ht_thumb_gallery_v1';
const THUMB_GALLERY_MAX = 5;
var _thumbWsPersistTimer = null;

function resetThumbMakerVisualState_(st){
  if(st.bgImg && typeof st.bgImg.close === 'function'){
    try { st.bgImg.close(); } catch(e){}
  }
  st.bgDataUrl = null;
  st.bgImg = null;
  st.fileName = '';
  st.activeField = null;
  st.focusX = 0.5;
  st.focusY = 0.45;
  st.zoom = 1;
  st.outFocus = false;
  st.enhance = false;
  st.bgDataUrlOriginal = null;
  st.bgDataUrlUpscaled = null;
  st.bgDataUrlBeforeUpscale = null;
  st.aiUpscaleOn = false;
  st.addFormPicks = null;
  st.addFormPickIndex = 0;
}

function serializeThumbWorkspace_(st){
  st = st || ensureThumbMakerState_();
  var fields = st.fields || st.lastCopy || null;
  return {
    v: 2,
    draftId: st.draftId,
    catId: st.catId,
    savedAt: Date.now(),
    bgDataUrl: st.bgDataUrlOriginal || st.bgDataUrl || null,
    fileName: st.fileName || '',
    fields: fields ? {
      hero: fields.hero || '',
      tagline: fields.tagline || '',
      program: fields.program || '',
      body: String(fields.body || '').replace(/^[:：]\s*/, ''),
      keywords: fields.keywords || [],
      brandProgram: fields.brandProgram || ''
    } : null,
    programMode: st.programMode || 'topic',
    photoIndex: st.photoIndex || 0,
    sizeKey: st.sizeKey || '4x5',
    focusX: st.focusX != null ? st.focusX : 0.5,
    focusY: st.focusY != null ? st.focusY : 0.45,
    zoom: st.zoom != null ? st.zoom : 1,
    typeScale: st.typeScale != null ? st.typeScale : 1,
    heroOneLine: !!st.heroOneLine,
    outFocus: !!st.outFocus,
    enhance: !!st.enhance
  };
}

function schedulePersistThumbWorkspace_(immediate){
  var st = ensureThumbMakerState_();
  if(!st.draftId) return;
  var draftIdSnap = st.draftId;
  function doSave_(){
    // 저장 키가 바뀌었으면(초안 전환) 스냅샷 시점의 draftId로만 기록
    var payload = serializeThumbWorkspace_(st);
    payload.draftId = draftIdSnap;
    if(!payload.bgDataUrl && !payload.fields) return;
    idbPutKv_(THUMB_WS_KEY_PREFIX + draftIdSnap, payload).catch(function(err){
      console.warn('[thumb workspace]', err);
    });
  }
  if(immediate){
    if(_thumbWsPersistTimer) clearTimeout(_thumbWsPersistTimer);
    _thumbWsPersistTimer = null;
    // 전환 직전: 현재 st를 직렬화하되 키는 snap
    var snapFields = st.fields;
    doSave_();
    return;
  }
  if(_thumbWsPersistTimer) clearTimeout(_thumbWsPersistTimer);
  _thumbWsPersistTimer = setTimeout(function(){
    if(st.draftId !== draftIdSnap) return;
    doSave_();
  }, 450);
}

function loadThumbWorkspace_(draftId){
  if(!draftId) return Promise.resolve(null);
  return idbGetKv_(THUMB_WS_KEY_PREFIX + draftId).then(function(row){
    if(!row || row.v < 1 || row.v > 2) return null;
    return row;
  }).catch(function(){ return null; });
}

async function applyThumbWorkspaceRow_(st, row){
  if(!st || !row) return false;
  st.programMode = (row.programMode === 'brand') ? 'brand' : ((row.programMode === 'photo' || isDailyShareCategory(st.catId)) ? 'photo' : 'topic');
  if(isDailyShareCategory(st.catId)){
    st.programMode = 'photo';
    st.sizeKey = '4x5';
    st.outFocus = false;
  } else {
    st.sizeKey = row.sizeKey || '4x5';
    st.outFocus = !!row.outFocus;
  }
  st.photoIndex = row.photoIndex != null ? row.photoIndex : 0;
  st.focusX = row.focusX != null ? row.focusX : 0.5;
  st.focusY = row.focusY != null ? row.focusY : 0.45;
  st.zoom = row.zoom != null ? row.zoom : 1;
  st.typeScale = row.typeScale != null ? clampThumbTypeScale_(row.typeScale) : 1;
  st.heroOneLine = !!row.heroOneLine;
  st.enhance = !!row.enhance;
  st.aiUpscaleOn = false;
  st.bgDataUrlUpscaled = null;
  st.bgDataUrlBeforeUpscale = null;
  if(row.fields){
    var loadedFields = {
      hero: row.fields.hero || '',
      tagline: row.fields.tagline || '',
      program: row.fields.program || '',
      body: String(row.fields.body || '').replace(/^[:：]\s*/, ''),
      keywords: row.fields.keywords || [],
      brandProgram: row.fields.brandProgram || ''
    };
    if(row.v === 1){
      loadedFields = migrateThumbCopyToHookHero_(loadedFields, st.programMode);
    }
    st.fields = loadedFields;
    st.lastCopy = st.fields;
  }
  st.fileName = row.fileName || '';
  var bg = row.bgDataUrl || null;
  st.bgDataUrl = bg;
  st.bgDataUrlOriginal = bg;
  if(st.bgImg && typeof st.bgImg.close === 'function'){
    try { st.bgImg.close(); } catch(e){}
  }
  st.bgImg = null;
  if(bg){
    try { st.bgImg = await loadBitmapForThumb_(bg); } catch(e2){ st.bgImg = null; }
  }
  return true;
}

function refreshThumbMakerDomFromState_(){
  var st = ensureThumbMakerState_();
  if(st.fields) applyThumbFieldsToDom_(st.fields);
  var sizeEl = document.getElementById('thumb-size');
  if(sizeEl && st.sizeKey) sizeEl.value = st.sizeKey;
  var btns = document.querySelectorAll('.thumb-maker-mode-btn[data-thumb-mode]');
  for(var i = 0; i < btns.length; i++){
    btns[i].classList.toggle('on', btns[i].getAttribute('data-thumb-mode') === (st.programMode || 'topic'));
  }
  updateThumbZoomLabel_();
  updateThumbTypeLabel_();
  syncThumbHeroOneLineButton_();
  syncThumbFocusPresetButtons_();
  syncThumbFxButtons_();
  updateThumbPhotoBadge_();
}

function beginThumbWorkspaceRestore_(draftId, catId, content){
  var st = ensureThumbMakerState_();
  st._wsRestoreGen = (st._wsRestoreGen || 0) + 1;
  var gen = st._wsRestoreGen;
  loadThumbWorkspace_(draftId).then(function(row){
    if(gen !== st._wsRestoreGen) return;
    if(st.draftId !== draftId) return;
    var staleDailyWs = isDailyShareCategory(catId) && row && row.programMode !== 'photo';
    if(row && row.fields && !staleDailyWs){
      applyThumbWorkspaceRow_(st, row).then(function(){
        if(gen !== st._wsRestoreGen || st.draftId !== draftId) return;
        refreshThumbMakerDomFromState_();
        paintThumbMakerPreview_();
        renderThumbGalleryStrip_();
        fillTopicPhotoPreview_(st.fileName === '주제 사진.jpg' ? st.bgDataUrl : '');
        maybeAutoloadDailyRefPhoto_(st.photoIndex || 0);
      });
    } else {
      st.programMode = isDailyShareCategory(catId) ? 'photo' : 'topic';
      st.fields = isDailyShareCategory(catId) ? emptyThumbPhotoCopy_() : buildThumbMakerCopy_(content, catId, { programMode: 'topic' });
      st.lastCopy = st.fields;
      refreshThumbMakerDomFromState_();
      paintThumbMakerPreview_();
      renderThumbGalleryStrip_();
      maybeAutoloadDailyRefPhoto_(0);
    }
  });
}

function loadThumbGallery_(){
  return idbGetKv_(THUMB_GALLERY_KEY).then(function(list){
    return Array.isArray(list) ? list : [];
  }).catch(function(){ return []; });
}

function saveThumbGallery_(list){
  return idbPutKv_(THUMB_GALLERY_KEY, (list || []).slice(0, THUMB_GALLERY_MAX));
}

async function pushThumbGalleryEntry_(entry){
  var list = await loadThumbGallery_();
  list = (list || []).filter(function(x){ return x && x.id !== entry.id; });
  list.unshift(entry);
  list = list.slice(0, THUMB_GALLERY_MAX);
  await saveThumbGallery_(list);
  var st = ensureThumbMakerState_();
  st.galleryCache = list;
  return list;
}

function renderThumbGalleryStrip_(){
  var root = document.getElementById('thumb-gallery-strip');
  if(!root) return;
  loadThumbGallery_().then(function(list){
    var st = ensureThumbMakerState_();
    var photoOnly = isThumbPhotoOnlyMode_();
    list = list || [];
    if(photoOnly) list = list.filter(function(item){ return Number(item.catId) === 6; });
    st.galleryCache = list;
    if(!list.length){
      root.innerHTML = photoOnly
        ? '<p class="thumb-gallery-empty">이 기기에서 맞춘 4:5 JPEG가 여기 최대 5개까지 남아요.</p>'
        : '<p class="thumb-gallery-empty">최근 생성한 썸네일이 여기 최대 5개까지 남아요. (이 기기 · 새로고침해도 유지)</p>';
      return;
    }
    var html = '<div class="thumb-gallery-hd">' + (photoOnly ? '최근 4:5' : '최근 생성') + ' <span>' + list.length + '/' + THUMB_GALLERY_MAX + '</span></div>';
    html += '<div class="thumb-gallery-row">';
    list.forEach(function(item, idx){
      var label = escapeHtml(String(item.label || item.program || (photoOnly ? '일상 4:5' : '썸네일')).slice(0, 22));
      var src = String(item.previewUrl || '').replace(/"/g, '');
      html += '<div class="thumb-gallery-item">';
      if(src) html += '<img src="' + src + '" alt="">';
      html += '<div class="thumb-gallery-label">' + label + '</div>';
      html += '<div class="thumb-gallery-actions">';
      html += '<button type="button" class="img-tool-copy-btn" onclick="restoreThumbGalleryItem_(' + idx + ')">불러오기</button>';
      html += '<button type="button" class="img-tool-copy-btn" onclick="downloadThumbGalleryItem_(' + idx + ')">받기</button>';
      html += '<button type="button" class="img-tool-copy-btn" onclick="deleteThumbGalleryItem_(' + idx + ')" title="삭제">×</button>';
      html += '</div></div>';
    });
    html += '</div>';
    root.innerHTML = html;
  });
}

window.restoreThumbGalleryItem_ = async function(index){
  var list = (ensureThumbMakerState_().galleryCache) || await loadThumbGallery_();
  var item = list[index];
  if(!item){ setAppToast('항목을 찾지 못했어요.', { duration: 1800, variant: 'err' }); return; }
  var st = ensureThumbMakerState_();
  if(item.workspace){
    await applyThumbWorkspaceRow_(st, item.workspace);
    st.draftId = state.selectedId;
    st.catId = state.selectedCatId;
    refreshThumbMakerDomFromState_();
    schedulePersistThumbWorkspace_(true);
    await paintThumbMakerPreview_();
    setAppToast('갤러리 항목을 편집기로 불러왔어요.', { duration: 2000, variant: 'ok' });
  } else if(item.fields){
    st.fields = item.fields;
    st.lastCopy = item.fields;
    applyThumbFieldsToDom_(st.fields);
    await paintThumbMakerPreview_();
    setAppToast('문안만 불러왔어요. (배경 없음)', { duration: 2200, variant: 'ok' });
  }
};

window.downloadThumbGalleryItem_ = async function(index){
  var list = (ensureThumbMakerState_().galleryCache) || await loadThumbGallery_();
  var item = list[index];
  if(!item || !item.previewUrl){
    setAppToast('다운로드할 이미지가 없어요.', { duration: 1800, variant: 'err' });
    return;
  }
  try {
    var res = await fetch(item.previewUrl);
    var blob = await res.blob();
    var name = (item.fileName || (item.label || 'thumbnail') + '-썸네일.jpg').replace(/[\\/:*?"<>|]+/g, '');
    var result = await saveThumbMakerBlob_(blob, name);
    if(result === 'aborted') setAppToast('공유를 취소했어요.', { duration: 1600, variant: 'ok' });
    else if(result === 'shared') setAppToast('공유 시트에서 「이미지 저장」을 선택하세요.', { duration: 2600, variant: 'ok' });
    else setAppToast('갤러리 저장본을 내려받았어요.', { duration: 1800, variant: 'ok' });
  } catch(err){
    setAppToast((err && err.message) || '다운로드 실패', { duration: 2200, variant: 'err' });
  }
};

window.deleteThumbGalleryItem_ = async function(index){
  var list = await loadThumbGallery_();
  if(index < 0 || index >= list.length) return;
  list.splice(index, 1);
  await saveThumbGallery_(list);
  ensureThumbMakerState_().galleryCache = list;
  renderThumbGalleryStrip_();
  setAppToast('갤러리에서 삭제했어요.', { duration: 1500, variant: 'ok' });
};

function getCurrentDraftForThumb_(){
  var cat = CATEGORIES[state.selectedCatId];
  if(!cat || !Array.isArray(cat.drafts)) return null;
  return cat.drafts.find(function(d){ return d && d.id === state.selectedId; }) || null;
}

function getCurrentDraftRefImagesForThumb_(){
  return getDraftRefImages_(getCurrentDraftForThumb_());
}

function resolveThumbMakerContent_(){
  try {
    return (state.published[state.selectedId] && state.published[state.selectedId].content)
      || state.generatedOnly[state.selectedId]
      || null;
  } catch(e){
    return null;
  }
}

/** 초안이 바뀌면 이전 작업 저장 후 복원, 같으면 수정값 유지 */
function syncThumbMakerFields_(content, force){
  var st = ensureThumbMakerState_();
  var addForm = !!(content && content._addForm) || (state.showAdd && st.draftId === '__add_form__');
  var draftId = addForm ? '__add_form__' : state.selectedId;
  var catId = addForm
    ? ((state.newItem && state.newItem.catId != null) ? state.newItem.catId : state.currentCat)
    : state.selectedCatId;
  var changed = st.draftId !== draftId || st.catId !== catId;
  if(changed){
    if(st.draftId && st.draftId !== '__add_form__'){
      try { persistThumbMakerFieldsFromDom_(); } catch(eDom){}
      schedulePersistThumbWorkspace_(true);
    }
    var catOnlyOnAdd = addForm && st.draftId === '__add_form__' && st.catId !== catId;
    var keepVisual = catOnlyOnAdd && !!st.bgDataUrl;
    st.draftId = draftId;
    st.catId = catId;
    if(!keepVisual) resetThumbMakerVisualState_(st);
    st.fields = null;
    st.programMode = isDailyShareCategory(catId) ? 'photo' : 'topic';
    st.sizeKey = '4x5';
    if(!keepVisual) st.photoIndex = 0;
    st.fields = isDailyShareCategory(catId)
      ? emptyThumbPhotoCopy_()
      : buildThumbMakerCopy_(content || buildAddFormThumbContent_(), catId, { programMode: 'topic', preferTopic: !!addForm });
    st.lastCopy = st.fields;
    if(!isDailyShareCategory(catId)) st.programMode = 'topic';
    if(!addForm) beginThumbWorkspaceRestore_(draftId, catId, content);
  } else if(force || !st.fields){
    if(isDailyShareCategory(catId)){
      st.programMode = 'photo';
      st.fields = emptyThumbPhotoCopy_();
    } else {
      st.programMode = 'topic';
      st.fields = buildThumbMakerCopy_(content || (addForm ? buildAddFormThumbContent_() : null), catId, {
        programMode: 'topic',
        preferTopic: !!addForm || !!force
      });
    }
  }
  st.lastCopy = st.fields;
  return st.fields;
}

function persistThumbMakerFieldsFromDom_(){
  var st = ensureThumbMakerState_();
  var copy = readThumbMakerFields_();
  st.fields = {
    hero: copy.hero,
    tagline: copy.tagline,
    program: copy.program,
    body: String(copy.body || '').replace(/^[:：]\s*/, ''),
    keywords: (st.fields && st.fields.keywords) || [],
    brandProgram: (st.fields && st.fields.brandProgram) || getThumbBrandPreset_(state.selectedCatId).program
  };
  st.lastCopy = st.fields;
  schedulePersistThumbWorkspace_(false);
  return st.fields;
}

function getThumbMakerSize_(){
  var st = ensureThumbMakerState_();
  var key = st.sizeKey || '4x5';
  return THUMB_SIZE_PRESETS[key] || THUMB_SIZE_PRESETS['4x5'];
}

function readThumbMakerFields_(){
  var heroEl = document.getElementById('thumb-hero');
  var tagEl = document.getElementById('thumb-tagline');
  var progEl = document.getElementById('thumb-program');
  var bodyEl = document.getElementById('thumb-body');
  var sizeEl = document.getElementById('thumb-size');
  var st = ensureThumbMakerState_();
  if(isThumbPhotoOnlyMode_()){
    st.sizeKey = '4x5';
    return emptyThumbPhotoCopy_();
  }
  if(sizeEl && sizeEl.value) st.sizeKey = sizeEl.value;
  if(heroEl || tagEl || progEl || bodyEl){
    var heroRaw = heroEl ? String(heroEl.value || '') : '';
    heroRaw = heroRaw.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
    // 후킹은 줄바꿈 유지(최대 3줄). 한 줄이면 그대로(이미지에도 한 줄).
    var heroNorm = heroRaw.indexOf('\n') >= 0
      ? heroRaw.split('\n').slice(0, 3).map(function(l){ return l.trim(); }).filter(Boolean).join('\n')
      : String(heroRaw || '').replace(/\s+/g, ' ').trim();
    var bodyRaw = bodyEl ? String(bodyEl.value || '') : '';
    bodyRaw = bodyRaw.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
    var bodyNorm = bodyRaw.indexOf('\n') >= 0
      ? bodyRaw.split('\n').slice(0, 3).map(function(l){ return l.trim(); }).filter(Boolean).join('\n')
      : bodyRaw.replace(/\s+/g, ' ').trim();
    return {
      hero: heroNorm,
      tagline: tagEl ? String(tagEl.value || '').trim() : '',
      program: normalizeThumbBrandOneLine_(progEl ? String(progEl.value || '').trim() : '') || (progEl ? String(progEl.value || '').trim() : ''),
      body: scrubNonClinicalTreatmentCopy_(bodyNorm, st.catId != null ? st.catId : state.selectedCatId)
    };
  }
  return st.fields || st.lastCopy || buildThumbMakerCopy_(null, state.selectedCatId);
}

function clamp01_(v){
  return Math.max(0, Math.min(1, Number(v) || 0));
}

function clampThumbZoom_(z){
  return Math.max(0.55, Math.min(2.6, Math.round((Number(z) || 1) * 100) / 100));
}
function clampThumbTypeScale_(s){
  return Math.max(0.5, Math.min(1.6, Math.round((Number(s) || 1) * 100) / 100));
}

function hexToRgba_(hex, alpha){
  var h = String(hex || '').replace('#', '').trim();
  if(h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  var n = parseInt(h, 16);
  if(isNaN(n) || h.length !== 6) return 'rgba(0,0,0,' + alpha + ')';
  return 'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + alpha + ')';
}

/** cover 크롭: zoom>1 확대, zoom<1 축소(레터박스). 100%에서도 상·하·좌·우 드래그 여유 확보 */
function drawImageCoverCanvas_(ctx, img, W, H, focusX, focusY, zoom){
  var iw = img.naturalWidth || img.width || 1;
  var ih = img.naturalHeight || img.height || 1;
  var zoomFactor = Math.max(0.55, Math.min(2.6, Number(zoom) || 1));
  var coverScale = Math.max(W / iw, H / ih);
  var panHeadroom = zoomFactor <= 1.02 ? 1.08 : 1;
  var scale = coverScale * zoomFactor * panHeadroom;
  var dw = iw * scale;
  var dh = ih * scale;
  var fx = clamp01_(focusX == null ? 0.5 : focusX);
  var fy = clamp01_(focusY == null ? 0.45 : focusY);
  var dx;
  var dy;
  if(dw >= W) dx = Math.max(W - dw, Math.min(0, -(dw - W) * fx));
  else dx = (W - dw) / 2;
  if(dh >= H) dy = Math.max(H - dh, Math.min(0, -(dh - H) * fy));
  else dy = (H - dh) / 2;
  if(dw < W || dh < H){
    ctx.fillStyle = '#0a0a0a';
    ctx.fillRect(0, 0, W, H);
  }
  ctx.imageSmoothingEnabled = true;
  if(ctx.imageSmoothingQuality) ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(img, dx, dy, dw, dh);
}

function getThumbFxCanvas_(key, W, H){
  var st = ensureThumbMakerState_();
  if(!st._fxCanvases) st._fxCanvases = {};
  var c = st._fxCanvases[key];
  if(!c){
    c = document.createElement('canvas');
    st._fxCanvases[key] = c;
  }
  if(c.width !== W) c.width = W;
  if(c.height !== H) c.height = H;
  return c;
}

/** 저해상도 확대 시 대비·선명도 살짝 보정 (AI 업스케일 아님) */
function applyThumbEnhancePass_(ctx, W, H){
  var tmp = getThumbFxCanvas_('enhance', W, H);
  var tctx = tmp.getContext('2d');
  if(!tctx) return;
  tctx.clearRect(0, 0, W, H);
  try {
    tctx.filter = 'contrast(1.07) saturate(1.05) brightness(1.02)';
    tctx.drawImage(ctx.canvas, 0, 0);
    tctx.filter = 'none';
  } catch(e){
    tctx.drawImage(ctx.canvas, 0, 0);
  }
  var blur = getThumbFxCanvas_('enhanceTiny', Math.max(1, Math.round(W / 10)), Math.max(1, Math.round(H / 10)));
  var bctx = blur.getContext('2d');
  if(bctx){
    bctx.clearRect(0, 0, blur.width, blur.height);
    bctx.drawImage(tmp, 0, 0, blur.width, blur.height);
    tctx.save();
    tctx.globalAlpha = 0.22;
    tctx.globalCompositeOperation = 'overlay';
    tctx.imageSmoothingEnabled = true;
    if(tctx.imageSmoothingQuality) tctx.imageSmoothingQuality = 'high';
    tctx.drawImage(blur, 0, 0, W, H);
    tctx.restore();
  }
  ctx.clearRect(0, 0, W, H);
  ctx.drawImage(tmp, 0, 0);
}

/** 중심은 선명, 바깥은 블러. focusX/Y에 맞춰 선명 원 이동 */
function applyThumbRadialOutFocus_(ctx, W, H, focusX, focusY){
  var sharp = getThumbFxCanvas_('ofSharp', W, H);
  sharp.getContext('2d').drawImage(ctx.canvas, 0, 0);

  var tinyW = Math.max(1, Math.round(W / 14));
  var tinyH = Math.max(1, Math.round(H / 14));
  var tiny = getThumbFxCanvas_('ofTiny', tinyW, tinyH);
  tiny.getContext('2d').drawImage(sharp, 0, 0, tinyW, tinyH);

  var blurLayer = getThumbFxCanvas_('ofBlur', W, H);
  var bctx = blurLayer.getContext('2d');
  bctx.imageSmoothingEnabled = true;
  if(bctx.imageSmoothingQuality) bctx.imageSmoothingQuality = 'high';
  bctx.clearRect(0, 0, W, H);
  bctx.drawImage(tiny, 0, 0, W, H);

  var masked = getThumbFxCanvas_('ofMask', W, H);
  var mctx = masked.getContext('2d');
  mctx.clearRect(0, 0, W, H);
  mctx.globalCompositeOperation = 'source-over';
  mctx.drawImage(blurLayer, 0, 0);
  mctx.globalCompositeOperation = 'destination-in';
  var cx = W * (0.38 + clamp01_(focusX == null ? 0.5 : focusX) * 0.24);
  var cy = H * (0.34 + clamp01_(focusY == null ? 0.45 : focusY) * 0.22);
  var inner = Math.min(W, H) * 0.2;
  var outer = Math.min(W, H) * 0.7;
  var g = mctx.createRadialGradient(cx, cy, inner, cx, cy, outer);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.45, 'rgba(0,0,0,0.35)');
  g.addColorStop(1, 'rgba(0,0,0,1)');
  mctx.fillStyle = g;
  mctx.fillRect(0, 0, W, H);
  mctx.globalCompositeOperation = 'source-over';

  ctx.clearRect(0, 0, W, H);
  ctx.drawImage(sharp, 0, 0);
  ctx.drawImage(masked, 0, 0);
}

function fitHeroFontSize_(ctx, lines, maxWidth, startPx, minPx){
  var size = startPx;
  while(size > minPx){
    ctx.font = '900 ' + size + 'px "Archivo Black","Arial Black","Helvetica Neue","Noto Sans KR",sans-serif';
    var widest = 0;
    for(var i = 0; i < lines.length; i++){
      widest = Math.max(widest, ctx.measureText(lines[i]).width);
    }
    if(widest <= maxWidth) return size;
    size -= 2;
  }
  return minPx;
}

/** 썸네일 브랜드명: 리얼무브먼트 등 한 줄 유지용 */
function isThumbBrandKeepOneLine_(text){
  var t = String(text || '').replace(/\s+/g, '');
  return /^리:?얼무브먼트/i.test(t) || /^리:?얼페이스/i.test(t) || /^리얼무브먼트/.test(t) || /^리얼페이스/.test(t);
}
function isKnownThumbBrandHero_(text){
  var t = String(text || '').replace(/\s+/g, ' ').trim();
  if(!t) return false;
  if(isThumbBrandKeepOneLine_(t)) return true;
  var compact = t.replace(/\s+/g, '').toLowerCase();
  for(var id in THUMB_BRAND_PRESETS){
    if(!Object.prototype.hasOwnProperty.call(THUMB_BRAND_PRESETS, id)) continue;
    var p = THUMB_BRAND_PRESETS[id];
    var hero = String(p.hero || '').replace(/\s+/g, '').toLowerCase();
    var prog = String(p.program || '').replace(/\s+/g, '').toLowerCase();
    if(compact === hero || compact === prog) return true;
  }
  return /^(real\s*(movement|life|care|face)|cmt(\s*academy)?|ifc|re:?al)/i.test(t);
}
/** v1 작업공간: 큰 타이틀이 브랜드명이면 주제와 자리를 바꿈 */
function migrateThumbCopyToHookHero_(fields, programMode){
  if(!fields || programMode === 'brand') return fields;
  var hero = String(fields.hero || '').trim();
  var program = String(fields.program || '').trim();
  if(!hero || !program) return fields;
  if(isKnownThumbBrandHero_(hero) && !isKnownThumbBrandHero_(program) && program.replace(/\s+/g, '').length >= 6){
    return {
      hero: program,
      tagline: fields.tagline,
      program: hero,
      body: fields.body,
      keywords: fields.keywords,
      brandProgram: fields.brandProgram
    };
  }
  return fields;
}
function normalizeThumbBrandOneLine_(text){
  var raw = String(text || '').trim();
  if(!raw) return '';
  var compact = raw.replace(/\s+/g, '');
  if(/^리:?얼무브먼트$/i.test(compact) || /^리:?얼\s*무브먼트$/i.test(raw)) return '리얼무브먼트';
  if(/^리:?얼페이스$/i.test(compact) || /^리:?얼\s*페이스$/i.test(raw) || /^리얼\s*페이스$/i.test(raw)) return '리얼 페이스';
  return raw.replace(/\s+/g, ' ');
}

function splitThumbHeroLines_(heroRaw){
  var raw = String(heroRaw || '').trim();
  if(!raw) return ['REAL', 'MOVEMENT'];

  // 리얼무브먼트: 공백·콜론 변형을 붙여 쓰고 반드시 한 줄
  var compact = raw.replace(/\s+/g, '');
  if(/^리:?얼무브먼트$/i.test(compact) || /^리:?얼\s*무브먼트$/i.test(raw)){
    return ['리얼무브먼트'];
  }
  // 리얼 페이스: 한글은 공백 유지, 한 줄 고정
  if(/^리:?얼페이스$/i.test(compact) || /^리:?얼\s*페이스$/i.test(raw) || /^리얼\s*페이스$/i.test(raw)){
    return ['리얼 페이스'];
  }

  // 기타 한글 히어로: 공백으로 강제 2줄 분리하지 않음(큰 타이틀 한 줄)
  if(/[가-힣]/.test(raw)){
    return [raw.replace(/\s+/g, ' ')];
  }

  var upper = raw.toUpperCase();
  var lines = upper.split(/\s+/).filter(Boolean);
  if(lines.length === 1 && upper.length > 10 && /^(REAL|IFC|CMT)/.test(upper)){
    // 알려진 영문 브랜드만 안전하게 분리, 임의 mid-split 금지
    if(/^REAL\s*/.test(upper) && upper.length > 4){
      var rest = upper.replace(/^REAL\s*/, '');
      if(rest) lines = ['REAL', rest];
    }
  }
  if(!lines.length) lines = ['REAL', 'MOVEMENT'];
  return lines;
}

function wrapThumbLinesAtBreaks_(ctx, text, maxWidth, maxLines){
  var t = String(text || '').replace(/\s+/g, ' ').trim();
  if(!t) return [''];
  if(ctx.measureText(t).width <= maxWidth) return [t];

  var breakAfter = /[\s—–\-·|/,:;…]/;
  var lines = [];
  var rest = t;
  while(rest){
    if(ctx.measureText(rest).width <= maxWidth){
      lines.push(rest);
      break;
    }
    var cut = -1;
    var acc = '';
    for(var i = 0; i < rest.length; i++){
      acc += rest[i];
      if(ctx.measureText(acc).width > maxWidth) break;
      if(breakAfter.test(rest[i])) cut = i + 1;
    }
    if(cut < 1){
      // soft wrap: 가능한 한 길게, 한 글자 고아 줄 방지
      cut = Math.max(1, acc.length - 1);
      if(cut < rest.length && rest.length - cut <= 2 && cut > 4){
        cut = Math.max(1, cut - 2);
      }
    }
    // 다음 줄이 1~2자면 앞 줄에서 더 넘겨 균형
    var nextLen = rest.length - cut;
    if(nextLen > 0 && nextLen <= 2 && cut > 6){
      cut = Math.max(1, cut - (3 - nextLen));
    }
    lines.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
    if(maxLines && lines.length >= maxLines){
      if(rest){
        var last = lines[lines.length - 1];
        while(last.length > 1 && ctx.measureText(last.replace(/…$/, '') + '…').width > maxWidth){
          last = last.slice(0, -1);
        }
        lines[lines.length - 1] = (last.replace(/…$/, '') + '…');
      }
      break;
    }
  }
  return lines.length ? lines : [''];
}

/** 가능하면 한 줄: 글자 크기를 줄이고, 그래도 넘치면 의미 단위로만 줄바꿈.
 *  입력에 엔터(줄바꿈)가 있으면 그 줄을 그대로 씀. */
function fitThumbTextBlock_(ctx, text, maxWidth, maxSize, minSize, weight, maxLines){
  var fontFamily = '"Noto Sans KR","Apple SD Gothic Neo",sans-serif';
  var size = maxSize;
  maxLines = maxLines == null ? 2 : maxLines;
  var raw = String(text || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  if(!raw) return { size: maxSize, lines: [''] };

  if(raw.indexOf('\n') >= 0){
    var explicit = raw.split('\n').map(function(l){ return l.trim(); }).filter(Boolean).slice(0, maxLines);
    if(!explicit.length) return { size: maxSize, lines: [''] };
    while(size >= minSize){
      ctx.font = weight + ' ' + size + 'px ' + fontFamily;
      var ok = true;
      for(var ei = 0; ei < explicit.length; ei++){
        if(ctx.measureText(explicit[ei]).width > maxWidth + 1){ ok = false; break; }
      }
      if(ok) return { size: size, lines: explicit };
      size -= 1;
    }
    ctx.font = weight + ' ' + minSize + 'px ' + fontFamily;
    return { size: minSize, lines: explicit };
  }

  var t = raw.replace(/\s+/g, ' ').trim();
  size = maxSize;
  while(size >= minSize){
    ctx.font = weight + ' ' + size + 'px ' + fontFamily;
    if(ctx.measureText(t).width <= maxWidth){
      return { size: size, lines: [t] };
    }
    size -= 1;
  }
  ctx.font = weight + ' ' + minSize + 'px ' + fontFamily;
  return { size: minSize, lines: wrapThumbLinesAtBreaks_(ctx, t, maxWidth, maxLines) };
}


/** 브랜드·긴 후킹을 편집칸에 미리보기와 같은 줄 수로 펼침 */
function expandThumbHeroLinesForEdit_(hero){
  var raw = String(hero || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  if(!raw) return '';
  if(raw.indexOf('\n') >= 0){
    return raw.split('\n').slice(0, 3).map(function(l){ return l.trim(); }).filter(Boolean).join('\n');
  }
  if(isKnownThumbBrandHero_(raw)){
    var brandLines = splitThumbHeroLines_(raw);
    if(brandLines && brandLines.length) return brandLines.slice(0, 3).join('\n');
  }
  return raw.replace(/\s+/g, ' ');
}

function syncThumbHeroTextareaRows_(heroText){
  var el = document.getElementById('thumb-hero');
  if(!el) return;
  var n = String(heroText || '').split('\n').filter(function(l){ return String(l || '').trim(); }).length;
  el.rows = Math.min(3, Math.max(1, n || 1));
}

function syncThumbHeroTextareaFromLayout_(heroLines){
  var el = document.getElementById('thumb-hero');
  var st = ensureThumbMakerState_();
  if(!el || st.activeField === 'hero') return;
  var lines = (heroLines || []).map(function(l){ return String(l || '').trim(); }).filter(Boolean).slice(0, 3);
  if(!lines.length) return;
  var next = lines.join('\n');
  if(String(el.value || '') === next){
    syncThumbHeroTextareaRows_(next);
    return;
  }
  el.value = next;
  syncThumbHeroTextareaRows_(next);
  if(st.fields) st.fields.hero = next;
  st.lastCopy = st.fields || st.lastCopy;
}

function layoutThumbPosterText_(ctx, W, H, copy, scale){
  scale = scale || 1;
  var padX = Math.round(W * 0.055);
  // 우측까지 넓게 써서 줄바꿈을 최소화 (기존 0.62 → 거의 전폭)
  var textMax = Math.max(40, W - padX * 2);
  var bottomPad = Math.round(H * 0.055);
  var heroRaw = String(copy.hero || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  var heroLines;
  var heroSize;
  var heroLineH;
  var heroKorean = /[가-힣]/.test(heroRaw);
  var typeScale = 1;
  try {
    var typeSt = ensureThumbMakerState_();
    typeScale = clampThumbTypeScale_(typeSt.typeScale);
    typeSt.heroOneLine = false;
    typeSt.outFocus = false;
  } catch(eType){}

  var explicitHero = heroRaw.split('\n').map(function(l){ return l.trim(); }).filter(Boolean).slice(0, 3);
  var hasExplicitBreaks = heroRaw.indexOf('\n') >= 0 && explicitHero.length > 0;
  if(hasExplicitBreaks){
    heroLines = explicitHero;
    heroSize = fitHeroFontSize_(
      ctx, heroLines, textMax,
      Math.round(W * (heroLines.length >= 3 ? 0.092 : 0.108) * scale * typeScale),
      Math.max(14, Math.round(W * 0.032 * Math.min(1, typeScale)))
    );
    heroLineH = Math.round(heroSize * (heroKorean ? 1.12 : 0.98));
  } else {
    // 한 줄 입력 → 이미지에도 한 줄
    var one = heroRaw.replace(/\s+/g, ' ').trim();
    heroLines = one ? [one] : [''];
    heroSize = fitHeroFontSize_(
      ctx, heroLines, textMax,
      Math.round(W * 0.1 * scale * typeScale),
      Math.max(13, Math.round(W * 0.028 * Math.min(1, typeScale)))
    );
    heroLineH = Math.round(heroSize * (heroKorean ? 1.12 : 0.95));
  }

  var tagFit = fitThumbTextBlock_(
    ctx, String(copy.tagline || ''), textMax,
    Math.max(14, Math.round(W * 0.028 * scale)),
    Math.max(11, Math.round(W * 0.018)),
    '500', 2
  );
  var progText = normalizeThumbBrandOneLine_(copy.program);
  var progIsBrand = isThumbBrandKeepOneLine_(progText) || isKnownThumbBrandHero_(progText);
  var progMaxLines = progIsBrand ? 1 : 2;
  var progFit = fitThumbTextBlock_(
    ctx, progText, textMax,
    Math.max(16, Math.round(W * (progIsBrand ? 0.056 : 0.034) * scale)),
    Math.max(12, Math.round(W * (progIsBrand ? 0.032 : 0.02))),
    '800', progMaxLines
  );
  var bodyMaxLines = scale < 0.85 ? 3 : 4;
  var bodyFit = fitThumbTextBlock_(
    ctx, String(copy.body || ''), textMax,
    Math.max(13, Math.round(W * 0.022 * scale)),
    Math.max(11, Math.round(W * 0.016)),
    '400', bodyMaxLines
  );

  var tagSize = tagFit.size;
  var progSize = progFit.size;
  var bodySize = bodyFit.size;
  var tagLines = tagFit.lines;
  var progLines = progFit.lines;
  var bodyLines = bodyFit.lines;

  var bodyLH = Math.round(bodySize * 1.45);
  var tagLH = Math.round(tagSize * 1.35);
  var progLH = Math.round(progSize * 1.35);
  var gapTag = Math.round(tagSize * 0.35);
  var gapProg = Math.round(progSize * 0.85);
  var gapBody = Math.round(bodySize * 0.55);

  var blockH =
    heroLines.length * heroLineH +
    gapTag + tagLines.length * tagLH +
    gapProg + progLines.length * progLH +
    gapBody + bodyLines.length * bodyLH;

  var yBottom = H - bottomPad;
  var y = yBottom - blockH;
  var minY = Math.round(H * 0.34);
  var overflow = false;
  if(y < minY){
    y = minY;
    if(y + blockH > yBottom) overflow = true;
  }

  return {
    padX: padX,
    textMax: textMax,
    y: y,
    bottom: y + blockH,
    overflow: overflow || (y + blockH > H - Math.round(H * 0.03)),
    heroLines: heroLines,
    heroSize: heroSize,
    heroLineH: heroLineH,
    tagLines: tagLines,
    tagSize: tagSize,
    tagLH: tagLH,
    gapTag: gapTag,
    progLines: progLines,
    progSize: progSize,
    progLH: progLH,
    gapProg: gapProg,
    bodyLines: bodyLines,
    bodySize: bodySize,
    bodyLH: bodyLH,
    gapBody: gapBody
  };
}

/** 첨부 스타일: 풀블리드 사진 + 하단 그라데이션 + 큰 흰 타이포 */
function drawThumbPosterOnCanvas_(ctx, W, H, copy, bgImg, opts){
  opts = opts || {};
  var activeField = opts.activeField || null;
  var st = ensureThumbMakerState_();
  var focusX = opts.focusX != null ? opts.focusX : st.focusX;
  var focusY = opts.focusY != null ? opts.focusY : st.focusY;
  var zoom = opts.zoom != null ? opts.zoom : st.zoom;
  var outFocus = false;
  var enhance = opts.enhance != null ? opts.enhance : !!st.enhance;
  st.outFocus = false;
  // 드래그 중에는 무거운 FX를 건너뛰어 끊김 방지
  if(st.dragPan && st.dragPan.moved){
    enhance = false;
  }
  ctx.clearRect(0, 0, W, H);
  if(bgImg){
    drawImageCoverCanvas_(ctx, bgImg, W, H, focusX, focusY, zoom);
    if(enhance) applyThumbEnhancePass_(ctx, W, H);
    if(outFocus && !isThumbPhotoOnlyMode_()) applyThumbRadialOutFocus_(ctx, W, H, focusX, focusY);
  } else {
    var fallback = ctx.createLinearGradient(0, 0, W, H);
    fallback.addColorStop(0, '#2a2a2a');
    fallback.addColorStop(1, '#0d0d0d');
    ctx.fillStyle = fallback;
    ctx.fillRect(0, 0, W, H);
  }

  if(isThumbPhotoOnlyMode_() || opts.photoOnly){
    return [];
  }

  var scale = 1;
  var layout = layoutThumbPosterText_(ctx, W, H, copy, scale);
  for(var attempt = 0; attempt < 14 && layout.overflow; attempt++){
    scale *= 0.9;
    layout = layoutThumbPosterText_(ctx, W, H, copy, scale);
  }
  try { syncThumbHeroTextareaFromLayout_(layout.heroLines); } catch(eSync){}

  // 스크림을 텍스트 바로 위부터 시작해 위쪽 빈 여백을 줄임
  var thumbPalette = getThumbPosterPaletteForCat_(st.catId != null ? st.catId : state.selectedCatId);
  var tint = thumbPalette.tint;
  var tint2 = thumbPalette.tint2;
  var glow = thumbPalette.glow || tint2;
  var textTop = layout.y;
  var scrimPad = Math.round(H * 0.045);
  var scrimStart = Math.max(0, textTop - scrimPad);
  var scrimDark = ctx.createLinearGradient(0, scrimStart, 0, H);
  scrimDark.addColorStop(0, 'rgba(0,0,0,0)');
  scrimDark.addColorStop(0.18, 'rgba(0,0,0,0.28)');
  scrimDark.addColorStop(0.55, 'rgba(0,0,0,0.58)');
  scrimDark.addColorStop(1, 'rgba(0,0,0,0.72)');
  ctx.fillStyle = scrimDark;
  ctx.fillRect(0, scrimStart, W, H - scrimStart);
  var scrimTint = ctx.createLinearGradient(0, scrimStart, 0, H);
  scrimTint.addColorStop(0, 'rgba(0,0,0,0)');
  scrimTint.addColorStop(0.28, hexToRgba_(tint, 0.22));
  scrimTint.addColorStop(0.58, hexToRgba_(glow, 0.48));
  scrimTint.addColorStop(0.82, hexToRgba_(tint2, 0.62));
  scrimTint.addColorStop(1, hexToRgba_(tint, 0.74));
  ctx.fillStyle = scrimTint;
  ctx.fillRect(0, scrimStart, W, H - scrimStart);
  var side = ctx.createLinearGradient(0, 0, W * 0.55, 0);
  side.addColorStop(0, 'rgba(0,0,0,0.24)');
  side.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = side;
  ctx.fillRect(0, scrimStart, W * 0.55, H - scrimStart);
  var sideTint = ctx.createLinearGradient(0, 0, W * 0.55, 0);
  sideTint.addColorStop(0, hexToRgba_(tint, 0.32));
  sideTint.addColorStop(0.45, hexToRgba_(glow, 0.14));
  sideTint.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = sideTint;
  ctx.fillRect(0, scrimStart, W * 0.55, H - scrimStart);

  var y = layout.y;
  var padX = layout.padX;
  var hitRegions = [];
  var blockPad = Math.round(W * 0.012);

  function pushHit(key, x0, y0, w0, h0){
    var x = Math.max(0, x0 - blockPad);
    var yy = Math.max(0, y0 - blockPad);
    hitRegions.push({
      key: key,
      x: x,
      y: yy,
      w: Math.min(W - x, w0 + blockPad * 2),
      h: Math.min(H - yy, h0 + blockPad * 2)
    });
  }

  function strokeActive(x0, y0, w0, h0){
    if(!activeField) return;
    ctx.save();
    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;
    ctx.strokeStyle = 'rgba(96, 165, 250, 0.95)';
    ctx.lineWidth = Math.max(2, Math.round(W * 0.003));
    ctx.setLineDash([8, 6]);
    ctx.strokeRect(x0, y0, w0, h0);
    ctx.restore();
  }

  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.shadowColor = 'rgba(0,0,0,0.55)';
  ctx.shadowBlur = Math.max(8, Math.round(W * 0.012));
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = Math.max(1, Math.round(W * 0.002));

  var heroY0 = y;
  var heroJoin = layout.heroLines.join('');
  var heroIsKo = /[가-힣]/.test(heroJoin);
  ctx.font = heroIsKo
    ? '900 ' + layout.heroSize + 'px "Noto Sans KR","Apple SD Gothic Neo",sans-serif'
    : '900 ' + layout.heroSize + 'px "Archivo Black","Arial Black","Helvetica Neue","Noto Sans KR",sans-serif';
  if(ctx.letterSpacing !== undefined) ctx.letterSpacing = heroIsKo ? '-0.04em' : '-0.02em';
  var heroW = 0;
  for(var hi = 0; hi < layout.heroLines.length; hi++){
    heroW = Math.max(heroW, ctx.measureText(layout.heroLines[hi]).width);
    ctx.fillText(layout.heroLines[hi], padX, y);
    y += layout.heroLineH;
  }
  if(ctx.letterSpacing !== undefined) ctx.letterSpacing = '0px';
  var heroH = y - heroY0;
  pushHit('hero', padX, heroY0, Math.max(heroW, layout.textMax * 0.7), heroH);
  if(activeField === 'hero') strokeActive(padX - blockPad, heroY0 - blockPad, Math.max(heroW, layout.textMax * 0.7) + blockPad * 2, heroH + blockPad * 2);

  y += layout.gapTag;
  var tagY0 = y;
  ctx.font = '500 ' + layout.tagSize + 'px "Noto Sans KR","Apple SD Gothic Neo",sans-serif';
  var tagW = 0;
  for(var ti = 0; ti < layout.tagLines.length; ti++){
    tagW = Math.max(tagW, ctx.measureText(layout.tagLines[ti]).width);
    ctx.fillText(layout.tagLines[ti], padX, y);
    y += layout.tagLH;
  }
  pushHit('tagline', padX, tagY0, Math.max(tagW, layout.textMax * 0.5), y - tagY0);
  if(activeField === 'tagline') strokeActive(padX - blockPad, tagY0 - blockPad, Math.max(tagW, layout.textMax * 0.5) + blockPad * 2, y - tagY0 + blockPad * 2);

  y += layout.gapProg;
  var progY0 = y;
  ctx.fillStyle = '#ffffff';
  ctx.font = '800 ' + layout.progSize + 'px "Noto Sans KR","Apple SD Gothic Neo",sans-serif';
  var progW = 0;
  for(var pi = 0; pi < layout.progLines.length; pi++){
    progW = Math.max(progW, ctx.measureText(layout.progLines[pi]).width);
    ctx.fillText(layout.progLines[pi], padX, y);
    y += layout.progLH;
  }
  pushHit('program', padX, progY0, Math.max(progW, layout.textMax * 0.55), y - progY0);
  if(activeField === 'program') strokeActive(padX - blockPad, progY0 - blockPad, Math.max(progW, layout.textMax * 0.55) + blockPad * 2, y - progY0 + blockPad * 2);

  y += layout.gapBody;
  var bodyY0 = y;
  ctx.fillStyle = '#ffffff';
  ctx.font = '400 ' + layout.bodySize + 'px "Noto Sans KR","Apple SD Gothic Neo",sans-serif';
  var bodyW = 0;
  for(var bi = 0; bi < layout.bodyLines.length; bi++){
    bodyW = Math.max(bodyW, ctx.measureText(layout.bodyLines[bi]).width);
    ctx.fillText(layout.bodyLines[bi], padX, y);
    y += layout.bodyLH;
  }
  pushHit('body', padX, bodyY0, Math.max(bodyW, layout.textMax * 0.7), y - bodyY0);
  if(activeField === 'body') strokeActive(padX - blockPad, bodyY0 - blockPad, Math.max(bodyW, layout.textMax * 0.7) + blockPad * 2, y - bodyY0 + blockPad * 2);

  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetY = 0;

  return hitRegions;
}

function applyThumbFieldsToDom_(copy){
  var heroVal = expandThumbHeroLinesForEdit_((copy && copy.hero) || '');
  if(copy) copy.hero = heroVal;
  var map = {
    'thumb-hero': heroVal,
    'thumb-tagline': (copy && copy.tagline) || '',
    'thumb-program': (copy && copy.program) || '',
    'thumb-body': (copy && copy.body) || ''
  };
  Object.keys(map).forEach(function(id){
    var el = document.getElementById(id);
    if(el) el.value = map[id];
  });
  syncThumbHeroTextareaRows_(heroVal);
  try {
    var st = ensureThumbMakerState_();
    st.heroLineLocked = false;
  } catch(e){}
}

function buildAddFormThumbContent_(){
  var raw = String((state.newItem && state.newItem.topic) || '').trim();
  var lines = raw.split(/\r?\n/).map(function(l){ return String(l || '').trim(); }).filter(Boolean);
  var phrases = [];
  lines.forEach(function(line){
    line.split(/\s*[·|/]\s*|,\s+/).forEach(function(p){
      p = String(p || '').trim();
      if(p && phrases.indexOf(p) < 0) phrases.push(p);
    });
  });
  var title = phrases[0] || raw.slice(0, 40);
  var hook = phrases[1] || phrases[0] || raw.slice(0, 80);
  return {
    _addForm: true,
    addTopic: title,
    addAngle: phrases.slice(1).join(' · ') || title,
    addKeywords: phrases,
    blog: {
      title: title,
      hook: hook,
      problem: raw
    }
  };
}

function renderAddFormThumbSectionHTML_(){
  return '<div class="form-field add-thumb-field" id="add-thumb-maker-root">' +
    renderThumbMakerCard_(buildAddFormThumbContent_()) +
  '</div>';
}

function parseAddFormKeywordPhrases_(){
  var c = buildAddFormThumbContent_();
  return c.addKeywords || [];
}

function addFormKeywordFileBoost_(fileName, phrases){
  var hay = String(fileName || '').toLowerCase().replace(/\s+/g, '');
  if(!hay || !phrases || !phrases.length) return 1;
  var boost = 1;
  for(var i = 0; i < phrases.length; i++){
    var tok = String(phrases[i] || '').toLowerCase().replace(/\s+/g, '');
    if(tok.length >= 2 && hay.indexOf(tok) >= 0) boost += 0.55;
    else if(tok.length >= 4 && hay.indexOf(tok.slice(0, 4)) >= 0) boost += 0.2;
  }
  return boost;
}

function isAddFormVideoFile_(file){
  return !!(file && ((file.type && file.type.indexOf('video/') === 0) || /\.(mp4|mov|m4v|webm|avi|mkv)$/i.test(file.name || '')));
}

function isAddFormImageFile_(file){
  return !!(file && ((file.type && file.type.indexOf('image/') === 0) || /\.(jpe?g|png|webp|gif|bmp)$/i.test(file.name || '')));
}

function scoreImageBitmapEnergy_(bitmap){
  try {
    var w = 80, h = 45;
    var c = document.createElement('canvas');
    c.width = w; c.height = h;
    var ctx = c.getContext('2d', { willReadFrequently: true });
    if(!ctx) return 0.5;
    ctx.drawImage(bitmap, 0, 0, w, h);
    var data = ctx.getImageData(0, 0, w, h).data;
    var sum = 0, sum2 = 0, n = w * h;
    for(var i = 0; i < data.length; i += 4){
      var y = 0.299 * data[i] + 0.587 * data[i + 1] + 0.114 * data[i + 2];
      sum += y; sum2 += y * y;
    }
    var mean = sum / n;
    var variance = Math.max(0, sum2 / n - mean * mean);
    return Math.sqrt(variance) / 128;
  } catch(e){
    return 0.5;
  }
}

async function pickBestFrameFromVideoFile_(file, phrases){
  var url = URL.createObjectURL(file);
  var best = null;
  try {
    var video = document.createElement('video');
    video.preload = 'auto';
    video.muted = true;
    video.playsInline = true;
    video.src = url;
    await new Promise(function(resolve, reject){
      video.onloadedmetadata = function(){ resolve(); };
      video.onerror = function(){ reject(new Error('영상을 열 수 없습니다')); };
    });
    var dur = video.duration || 0;
    if(!(dur > 0.2)) throw new Error('영상 길이가 너무 짧습니다');
    var samples = [];
    var n = dur <= 12 ? 5 : (dur <= 40 ? 8 : 10);
    for(var i = 0; i < n; i++){
      samples.push(0.12 + (dur - 0.25) * (i / Math.max(1, n - 1)));
    }
    var canvas = document.createElement('canvas');
    var ctx = canvas.getContext('2d', { willReadFrequently: true });
    for(var s = 0; s < samples.length; s++){
      var t = samples[s];
      await new Promise(function(resolve){
        var done = false;
        function finish(){ if(done) return; done = true; resolve(); }
        video.onseeked = finish;
        try { video.currentTime = t; } catch(e){ finish(); }
        setTimeout(finish, 900);
      });
      canvas.width = 160; canvas.height = 90;
      ctx.drawImage(video, 0, 0, 160, 90);
      var energy = scoreImageBitmapEnergy_(canvas);
      var score = energy * addFormKeywordFileBoost_(file.name || '', phrases);
      // 맨 앞·끝은 약간 감점
      if(t < 0.8) score *= 0.92;
      if(t > dur - 0.8) score *= 0.9;
      if(!best || score > best.score){
        var outW = Math.min(1280, video.videoWidth || 1080);
        var outH = Math.min(1600, video.videoHeight || 1350);
        var out = document.createElement('canvas');
        out.width = outW; out.height = outH;
        out.getContext('2d').drawImage(video, 0, 0, outW, outH);
        best = {
          score: score,
          dataUrl: out.toDataURL('image/jpeg', 0.88),
          name: (file.name || 'video') + ' · ' + (Math.floor(t / 60) + ':' + (t % 60 < 10 ? '0' : '') + Math.floor(t % 60)),
          kind: 'video'
        };
      }
    }
  } finally {
    try { URL.revokeObjectURL(url); } catch(e3){}
  }
  return best;
}

function estimateAddFormThumbScanSec_(files){
  var list = Array.prototype.slice.call(files || []);
  var imgs = Math.min(24, list.filter(isAddFormImageFile_).length);
  var vids = Math.min(4, list.filter(isAddFormVideoFile_).length);
  return Math.max(3, Math.min(90, Math.ceil(1.5 + imgs * 0.25 + vids * 4.5)));
}

function pushTopThumbCandidate_(list, item, limit){
  if(!item || !item.dataUrl) return;
  limit = limit || 3;
  // 동일 장면 중복 완화
  for(var i = 0; i < list.length; i++){
    if(list[i].name === item.name && Math.abs((list[i].score || 0) - (item.score || 0)) < 0.02){
      if((item.score || 0) > (list[i].score || 0)) list[i] = item;
      return;
    }
  }
  list.push(item);
  list.sort(function(a, b){ return (b.score || 0) - (a.score || 0); });
  if(list.length > limit) list.length = limit;
}

var _thumbFolderScanTimer = null;
var _thumbFolderScanStartedAt = 0;
var _thumbFolderScanEstimateSec = 0;

function stopThumbFolderScanCountdown_(){
  if(_thumbFolderScanTimer){
    clearInterval(_thumbFolderScanTimer);
    _thumbFolderScanTimer = null;
  }
}

function ensureThumbFolderProgressEl_(){
  var el = document.getElementById('thumb-folder-progress');
  if(el) return el;
  var nameEl = document.getElementById('thumb-photo-name');
  if(!nameEl || !nameEl.parentNode) return null;
  el = document.createElement('div');
  el.id = 'thumb-folder-progress';
  el.className = 'thumb-folder-progress';
  el.hidden = true;
  nameEl.parentNode.insertBefore(el, nameEl.nextSibling);
  return el;
}

function updateThumbFolderScanProgress_(opts){
  opts = opts || {};
  var el = ensureThumbFolderProgressEl_();
  if(!el) return;
  if(opts.done){
    stopThumbFolderScanCountdown_();
    el.hidden = true;
    el.textContent = '';
    el.classList.remove('is-busy');
    return;
  }
  el.hidden = false;
  el.classList.add('is-busy');
  var left = getCountdownSec_(_thumbFolderScanStartedAt, _thumbFolderScanEstimateSec);
  var parts = [];
  parts.push(opts.label || '폴더 장면 고르는 중…');
  if(opts.fileCount) parts.push('파일 ' + opts.fileCount + '개');
  if(_thumbFolderScanEstimateSec) parts.push('예상 약 ' + _thumbFolderScanEstimateSec + '초');
  if(opts.doneCount != null && opts.totalCount){
    parts.push(opts.doneCount + '/' + opts.totalCount);
  }
  parts.push(formatCountdownLong_(left));
  el.textContent = parts.join(' · ');
}

function startThumbFolderScanCountdown_(estimateSec, fileCount){
  stopThumbFolderScanCountdown_();
  _thumbFolderScanStartedAt = Date.now();
  _thumbFolderScanEstimateSec = Math.max(3, parseInt(estimateSec, 10) || 8);
  updateThumbFolderScanProgress_({ fileCount: fileCount, label: '폴더 장면 고르는 중…' });
  _thumbFolderScanTimer = setInterval(function(){
    updateThumbFolderScanProgress_({ fileCount: fileCount, label: '폴더 장면 고르는 중…' });
  }, 250);
}

function renderThumbFolderPicksHTML_(picks, selectedIndex){
  picks = picks || [];
  if(!picks.length) return '';
  var html = '<div class="thumb-folder-picks" id="thumb-folder-picks">';
  html += '<div class="thumb-folder-picks-hd">추천 사진 ' + picks.length + '장 · 눌러서 선택</div>';
  html += '<div class="thumb-folder-picks-grid">';
  picks.forEach(function(p, i){
    var on = i === (selectedIndex == null ? 0 : selectedIndex);
    html += '<button type="button" class="thumb-folder-pick' + (on ? ' on' : '') + '" onclick="selectAddFormThumbPick_(' + i + ')" title="' + escapeHtml(p.name || ('추천 ' + (i + 1))) + '">';
    html += '<img src="' + String(p.dataUrl || '').replace(/"/g, '&quot;') + '" alt="">';
    html += '<span class="thumb-folder-pick-rank">' + (i + 1) + '</span>';
    if(p.kind === 'video') html += '<span class="thumb-folder-pick-kind">영상</span>';
    html += '</button>';
  });
  html += '</div></div>';
  return html;
}

function refreshThumbFolderPicksUI_(){
  var st = ensureThumbMakerState_();
  var picks = st.addFormPicks || [];
  var host = document.getElementById('thumb-folder-picks');
  var html = renderThumbFolderPicksHTML_(picks, st.addFormPickIndex || 0);
  if(!html){
    if(host) host.remove();
    return;
  }
  if(host){
    host.outerHTML = html;
  } else {
    var progress = document.getElementById('thumb-folder-progress');
    var nameEl = document.getElementById('thumb-photo-name');
    var anchor = progress || nameEl;
    if(anchor && anchor.parentNode){
      anchor.insertAdjacentHTML('afterend', html);
    }
  }
}

async function applyAddFormThumbPick_(picked, opts){
  opts = opts || {};
  if(!picked || !picked.dataUrl) throw new Error('선택한 사진이 없어요.');
  clearThumbAiUpscaleCache_();
  var st = ensureThumbMakerState_();
  st.draftId = '__add_form__';
  st.catId = (state.newItem && state.newItem.catId != null) ? state.newItem.catId : state.currentCat;
  await setThumbMakerBackgroundFromDataUrl_(picked.dataUrl, picked.name || '썸네일 장면');
  if(!isThumbPhotoOnlyMode_()){
    st.programMode = 'topic';
    st.fields = buildThumbMakerCopy_(buildAddFormThumbContent_(), st.catId, { programMode: 'topic', preferTopic: true });
    st.lastCopy = st.fields;
    applyThumbFieldsToDom_(st.fields);
  }
  var nameEl = document.getElementById('thumb-photo-name');
  if(nameEl) nameEl.textContent = st.fileName || picked.name || '';
  await paintThumbMakerPreview_();
  refreshThumbFolderPicksUI_();
  if(!opts.silent){
    setAppToast(
      (picked.kind === 'video' ? '영상 장면을 골랐어요. ' : '추천 사진을 적용했어요. ') +
      '후킹·구도를 수정해 보세요.',
      { duration: 2600, variant: 'ok' }
    );
  }
}

window.selectAddFormThumbPick_ = async function(index){
  var st = ensureThumbMakerState_();
  var picks = st.addFormPicks || [];
  var i = parseInt(index, 10) || 0;
  if(!picks[i]){
    setAppToast('추천 사진이 없어요. 폴더를 다시 선택해 주세요.', { duration: 2600, variant: 'err' });
    return;
  }
  st.addFormPickIndex = i;
  try {
    await applyAddFormThumbPick_(picks[i]);
  } catch(err){
    setAppToast((err && err.message) || '사진을 적용하지 못했어요.', { duration: 3000, variant: 'err' });
  }
};

/** 폴더·다중 파일에서 점수 상위 후보(기본 3장) */
async function pickTopAddFormThumbCandidates_(fileList, opts){
  opts = opts || {};
  var limit = Math.max(1, parseInt(opts.limit, 10) || 3);
  var onProgress = typeof opts.onProgress === 'function' ? opts.onProgress : null;
  var files = Array.prototype.slice.call(fileList || []).filter(function(f){
    return isAddFormImageFile_(f) || isAddFormVideoFile_(f);
  });
  if(!files.length) throw new Error('사진 또는 영상 파일을 골라 주세요.');
  var phrases = parseAddFormKeywordPhrases_();
  var top = [];
  var imgFiles = files.filter(isAddFormImageFile_);
  var vidFiles = files.filter(isAddFormVideoFile_).slice(0, 4);
  var total = Math.min(24, imgFiles.length) + vidFiles.length;
  var done = 0;

  for(var i = 0; i < imgFiles.length && i < 24; i++){
    var img = imgFiles[i];
    if(isLikelyHeicFile_(img)){ done++; if(onProgress) onProgress({ done: done, total: total }); continue; }
    try {
      var payload = await prepareThumbBackgroundPayload_(img, img.name);
      var dataUrl = 'data:' + (payload.mediaType || 'image/jpeg') + ';base64,' + payload.data;
      var bitmap = await loadBitmapForThumb_(dataUrl);
      var energy = scoreImageBitmapEnergy_(bitmap);
      if(bitmap && bitmap.close) try { bitmap.close(); } catch(eClose){}
      var score = energy * addFormKeywordFileBoost_(img.name || '', phrases);
      if(phrases.length && addFormKeywordFileBoost_(img.name || '', phrases) > 1.2) score *= 1.15;
      pushTopThumbCandidate_(top, {
        score: score,
        dataUrl: dataUrl,
        name: payload.name || img.name,
        kind: 'image'
      }, limit);
    } catch(eImg){}
    done++;
    if(onProgress) onProgress({ done: done, total: total });
  }

  for(var v = 0; v < vidFiles.length; v++){
    try {
      var frame = await pickBestFrameFromVideoFile_(vidFiles[v], phrases);
      if(frame) pushTopThumbCandidate_(top, frame, limit);
    } catch(eVid){}
    done++;
    if(onProgress) onProgress({ done: done, total: total });
  }

  if(!top.length) throw new Error('맞는 장면을 찾지 못했어요. 다른 파일·폴더를 시도해 주세요.');
  return top;
}


window.onAddFormThumbFiles_ = async function(input){
  var files = input && input.files;
  if(!files || !files.length) return;
  var isFolder = !!(input && (input.id === 'add-thumb-folder-input' || input.hasAttribute('webkitdirectory')));
  var mediaFiles = Array.prototype.slice.call(files).filter(function(f){
    return isAddFormImageFile_(f) || isAddFormVideoFile_(f);
  });
  var fileCount = mediaFiles.length || files.length;
  var estimateSec = estimateAddFormThumbScanSec_(mediaFiles.length ? mediaFiles : files);
  startThumbFolderScanCountdown_(estimateSec, fileCount);
  setAppToast(
    (isFolder ? '폴더 ' : '') + '장면 고르는 중… 예상 약 ' + estimateSec + '초',
    { duration: Math.min(5000, estimateSec * 400), variant: 'ok' }
  );
  try {
    var top = await pickTopAddFormThumbCandidates_(files, {
      limit: 3,
      onProgress: function(p){
        updateThumbFolderScanProgress_({
          fileCount: fileCount,
          doneCount: p.done,
          totalCount: p.total,
          label: isFolder ? '폴더 장면 고르는 중…' : '장면 고르는 중…'
        });
      }
    });
    var st = ensureThumbMakerState_();
    st.addFormPicks = top;
    st.addFormPickIndex = 0;
    updateThumbFolderScanProgress_({ done: true });
    refreshThumbFolderPicksUI_();
    await applyAddFormThumbPick_(top[0], { silent: true });
    setAppToast(
      '추천 ' + top.length + '장을 준비했어요. 아래에서 골라 주세요.',
      { duration: 3200, variant: 'ok' }
    );
  } catch(err){
    updateThumbFolderScanProgress_({ done: true });
    setAppToast((err && err.message) || '장면을 고르지 못했어요.', { duration: 3200, variant: 'err' });
  }
  if(input) input.value = '';
};

