function getTabCopyText(tab, content){
  if(!content) return '';
  var catId = state.selectedCatId != null ? state.selectedCatId : getCatIdFromDraftId_(state.selectedId);
  if(tab === 'blog'){
    const b = content.blog;
    if(!b) return '';
    if(blogUsesStructuredGeneralFormat_(catId, b)) return formatGeneralBlogPostText(b, catId);
    const outline = (b.outline || []).map(function(o, i){ return (i + 1) + '. ' + o; }).join('\n');
    return withExpertCourseBlogFooter_(withRealMovementBlogFooter_('[블로그]\n제목: ' + b.title + '\n\n' + (b.hook || '') + '\n\n' + outline + '\n\n' + (b.draft || '') + '\n\n' + (b.cta || '') + '\n\n' + (b.hashtags || []).map(function(h){ return '#' + h; }).join(' '), catId), catId);
  }
  if(tab === 'insta'){
    const ig = content.insta;
    if(!ig) return '';
    return '[인스타]\n' + getInstaFullPasteText_(ig, catId);
  }
  if(tab === 'threads'){
    const ths = content.threads;
    if(!ths || !getThreadsBodyText_(ths)) return '';
    return getThreadsFullPasteText_(ths);
  }
  if(tab === 'community'){
    const c = content.community;
    if(!c) return '';
    return formatCommunityPostText(c);
  }
  if(tab === 'thread'){
    const th = normalizeThreadBlock(content.thread);
    if(!th || !th.summary) return '';
    return getThreadPlainText(th);
  }
  if(tab === 'news'){
    ensureNewsBlock_(content);
    return formatNewsChannelText_(getNewsChannelItem_(content, getNewsChannel_()), getNewsChannel_());
  }
  if(tab === 'images'){
    var imgCatId = state.selectedCatId != null ? state.selectedCatId : getCatIdFromDraftId_(state.selectedId);
    if(isDailyShareCategory(imgCatId)) return '';
    var imgCopy = getImagePromptTextForData_(content, imgCatId);
    return imgCopy ? imgCopy : '';
  }
  return '';
}


window.openExternalNaverBlog = function(){
  var writeUrl = EXT_NAVER_BLOG_WRITE;
  if(!isPhoneOrTablet()){
    window.open(writeUrl, '_blank', 'noopener,noreferrer');
    return;
  }
  if(isAndroidDevice()){
    openExternalLinkInGesture_('intent://write?blogId=allenjoy#Intent;scheme=naverblog;package=com.nhn.android.blog;S.browser_fallback_url=' + encodeURIComponent(writeUrl) + ';end');
    return;
  }
  if(isIOSLikeDevice()){
    openNaverBlogAppOnIOS_();
    setTimeout(function(){
      if(document.hidden) return;
      window.open(writeUrl, '_blank', 'noopener,noreferrer');
    }, 900);
    return;
  }
  window.open(writeUrl, '_blank', 'noopener,noreferrer');
};

function buildBlogPasteTextForPublish_(b, catId){
  if(!b) return '';
  if(blogUsesStructuredGeneralFormat_(catId, b)) return formatGeneralBlogPostText(b, catId);
  var outline = (b.outline || []).map(function(o, i){ return (i + 1) + '. ' + o; }).join('\n');
  var tags = (b.hashtags || []).map(function(h){ return '#' + String(h).replace(/^#/, ''); }).join(' ');
  if(isExpertCourseCategory(catId)){
    var expertParts = [b.title, b.hook, outline, b.draft, b.cta];
    if(tags) expertParts.push(tags);
    return withExpertCourseBlogFooter_(expertParts.filter(function(p){ return String(p || '').trim(); }).join('\n\n'), catId);
  }
  var parts = [b.title, b.hook, outline, b.draft, b.cta];
  if(tags) parts.push(tags);
  return withRealMovementBlogFooter_(parts.filter(function(p){ return String(p || '').trim(); }).join('\n\n'), catId);
}

function ensureNotifyForInstaBg_(){
  try {
    if(typeof Notification === 'undefined') return;
    if(Notification.permission !== 'default') return;
    if(localStorage.getItem('ht_notif_insta_prompt_done')) return;
    localStorage.setItem('ht_notif_insta_prompt_done', '1');
    if(typeof setAppToast === 'function'){
      setAppToast('블로그 앱에 있는 동안 인스타 캡션 완료 알림을 받으려면\n곧 뜨는 창에서 허용을 눌러 주세요.', { duration: 5200, variant: 'ok' });
    }
    setTimeout(function(){
      try { Notification.requestPermission(); } catch(e){}
    }, 700);
  } catch(e){}
}

function copyAndOpenNaverBlog_(text){
  openExternalNaverBlog();
  if(!text) return;
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).catch(function(){});
  }
}
function startInstaDraftAfterBlogPublish_(draftId, catId, topic, content){
  if(!isBlogInstaCategory(catId) || !content || !content.blog) return;
  if(instaContentReady_(content)) return;
  if(!state.apiKey) return;
  ensureNotifyForInstaBg_();
  enqueueInstaFromBlog_(draftId, catId, topic || '', content.blog);
}

function copyAndOpenInstagram_(text){
  var open = function(){ openExternalInstagramForPost_(); };
  if(!text){ open(); return; }
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(open).catch(open);
  } else {
    open();
  }
}

function copyTextOnly_(text, done){
  writeClipboardRich_(text, '', done);
}

/** text/plain + (선택) text/html — 리치 에디터에 붙여넣으면 카드형 유지 */
function writeClipboardRich_(plain, html, done){
  plain = String(plain || '');
  if(!plain){
    if(done) done(false);
    return;
  }
  var ok = function(){ if(done) done(true); };
  var fail = function(){
    try { window.prompt('복사할 내용:', plain); } catch(e){}
    if(done) done(true);
  };
  if(html && typeof ClipboardItem !== 'undefined' && navigator.clipboard && navigator.clipboard.write){
    try {
      var item = new ClipboardItem({
        'text/plain': new Blob([plain], { type: 'text/plain' }),
        'text/html': new Blob([String(html)], { type: 'text/html' })
      });
      navigator.clipboard.write([item]).then(ok).catch(function(){
        if(navigator.clipboard.writeText) navigator.clipboard.writeText(plain).then(ok).catch(fail);
        else fail();
      });
      return;
    } catch(e){}
  }
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(plain).then(ok).catch(fail);
    return;
  }
  fail();
}

window.openExternalInstagramForPost_ = function(){
  const u = getInstagramUrlForCat_(getActiveInstagramCatId_());
  if(!isPhoneOrTablet()){
    window.open(u, '_blank', 'noopener,noreferrer');
    return;
  }
  if(isAndroidDevice()){
    window.location.href =
      'intent:#Intent;package=com.instagram.android;action=android.intent.action.MAIN;category=android.intent.category.LAUNCHER;end';
    setTimeout(function(){
      if(document.hidden) return;
      window.location.href =
        'intent://www.instagram.com/#Intent;scheme=https;package=com.instagram.android;S.browser_fallback_url=' +
        encodeURIComponent(u) + ';end';
    }, 450);
    setTimeout(function(){
      if(document.hidden) return;
      window.open(u, '_blank', 'noopener,noreferrer');
    }, 1100);
    return;
  }
  if(isIOSLikeDevice()){
    window.location.href = 'instagram://camera';
    setTimeout(function(){
      if(document.hidden) return;
      window.location.href = 'instagram://app';
    }, 400);
    setTimeout(function(){
      if(document.hidden) return;
      window.location.href = u;
    }, 900);
    setTimeout(function(){
      if(document.hidden) return;
      window.open(u, '_blank', 'noopener,noreferrer');
    }, 1400);
    return;
  }
  openExternalInstagram();
};

function tryNotifyInstaReady_(topic, draftId, catId, ok, errMsg){
  ok = ok !== false;
  try {
    if(typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
    var title = ok ? '인스타 캡션 준비됐어요' : '인스타 캡션 생성 실패';
    var body = ok ? String(topic || '인스타') : String(errMsg || topic || '다시 시도해 주세요');
    var opts = {
      body: body,
      tag: 'ht-insta-' + String(draftId),
      data: { draftId: draftId, catId: catId, tab: 'insta' },
      requireInteraction: !!ok
    };
    var onClick = function(){
      focusPlannerAndOpenDraft_(draftId, catId);
      showInstaContentWhenReady_(draftId, catId);
    };
    if(document.hidden && navigator.serviceWorker){
      navigator.serviceWorker.ready.then(function(reg){
        return reg.showNotification(title, opts);
      }).catch(function(){
        var n = new Notification(title, opts);
        n.onclick = function(){ n.close(); onClick(); };
      });
      return;
    }
    var n = new Notification(title, opts);
    n.onclick = function(){ n.close(); onClick(); };
  } catch(e){}
}


