function sheetEditField_(label, id, value, opts){
  opts = opts || {};
  var rows = opts.rows || 4;
  var cls = 'sheet-edit' + (opts.title ? ' sheet-edit-title' : '');
  var help = opts.help ? '<div class="publish-field-help" style="margin:4px 0 6px;">' + escapeHtml(opts.help) + '</div>' : '';
  var wrapCls = 'cb' + (opts.title ? ' sheet-title-anchor' : '');
  var displayValue = opts.paragraphs ? ensureProseParagraphBreaks_(value) : (value || '');
  if(opts.regen) setSheetFieldBaseline_(id, displayValue);
  var tools = '';
  if(opts.regen || opts.copy){
    tools = '<span class="sheet-field-tools">';
    if(opts.regen){
      tools += '<button type="button" class="sheet-field-btn sheet-field-polish" data-for="' + escapeHtml(id) + '" disabled title="수정한 뒤 오타·문법·표현만 가볍게 다듬습니다" onclick="polishSheetField_(\'' + opts.regen + '\', this)">글 다듬기</button>';
      tools += '<button type="button" class="sheet-field-btn sheet-field-regen" title="제목·다른 칸·현재 박스 글을 참고해서 재작성할까요?" onclick="confirmRegenSheetField_(\'' + opts.regen + '\', this)">재생성</button>';
    }
    if(opts.copy){
      tools += '<button type="button" class="sheet-field-btn sheet-field-copy" onclick="copySheetField_(\'' + id + '\', this' + (opts.copyHashtags ? ', true' : '') + ')">복사</button>';
    }
    tools += '</span>';
  }
  var oninput = 'autoGrowTextarea_(this)' +
    (opts.regen ? ';onSheetFieldInput_(this)' : '') +
    (opts.stepPreview ? ';renderSelfCareStepsPreview_(this)' : '') +
    (opts.syncTopic ? ';onSheetTitleSyncTopic_(this)' : '');
  var onblur = opts.syncTopic ? ' onblur="flushSheetTitleBackgroundWork_()"' : '';
  var previewAttr = opts.stepPreview ? ' data-selfcare-preview="1"' : '';
  var previewHost = opts.stepPreview ? '<div class="selfcare-steps" data-steps-for="' + id + '"></div>' : '';
  return '<div class="' + wrapCls + '"><div class="cb-label">' + escapeHtml(label) + tools + '</div>' + help +
    '<textarea class="' + cls + '" id="' + id + '" rows="' + rows + '"' + previewAttr + onblur + ' oninput="' + oninput + '">' + escapeHtml(displayValue) + '</textarea>' + previewHost + '</div>';
}

/**
 * 마침표마다 빈 줄. 짧은 문장(36자 미만)은 다음 문장과 한 단락으로 이어져도 된다.
 * 목록·셀프케어(👉)는 그대로 둔다.
 */
function ensureProseParagraphBreaks_(text){
  var t = String(text || '').replace(/\r\n/g, '\n').trim();
  if(!t) return '';
  if(/(^|\n)\s*👉/.test(t)) return stripProseParagraphIndents_(t.replace(/\n{3,}/g, '\n\n'));
  if(/(^|\n)\s*(?:[-•*]|\d+[.)])\s/.test(t)) return stripProseParagraphIndents_(t.replace(/\n{3,}/g, '\n\n'));
  var sentences = splitProseSentences_(t.replace(/\n+/g, ' '));
  if(sentences.length < 2) return stripProseParagraphIndents_(sentences[0] || t);
  var groups = [];
  var i = 0;
  while(i < sentences.length){
    var cur = sentences[i];
    var next = sentences[i + 1];
    if(next && String(cur).length < 36){
      groups.push(cur + ' ' + next);
      i += 2;
    } else {
      groups.push(cur);
      i += 1;
    }
  }
  return stripProseParagraphIndents_(groups.join('\n\n'));
}
/** 문단 시작 들여쓰기(앞 공백) 제거 — 목록·셀프케어·해시태그는 그대로 */
function stripProseParagraphIndents_(text){
  var t = String(text || '').replace(/\r\n/g, '\n');
  if(!t.trim()) return '';
  return t.split(/\n\s*\n/).map(function(para){
    var lines = String(para || '').split('\n');
    var first = lines[0] || '';
    var trimmed = first.replace(/^[ \t\u00A0\u3000]+/, '');
    if(!trimmed) return para;
    if(/^👉/.test(trimmed)){
      lines[0] = trimmed;
      return lines.join('\n');
    }
    if(/^(?:[-•*]|\d+[.)])\s/.test(trimmed)) return para;
    if(/^#/.test(trimmed)) return para;
    lines[0] = trimmed;
    return lines.join('\n');
  }).join('\n\n');
}
function splitProseSentences_(text){
  var t = String(text || '').trim();
  if(!t) return [];
  var parts = [];
  var buf = '';
  for(var i = 0; i < t.length; i++){
    var ch = t.charAt(i);
    buf += ch;
    var end = /[.!?。？！]/.test(ch);
    var next = t.charAt(i + 1);
    if(end && (!next || /\s/.test(next))){
      var s = buf.trim();
      if(s) parts.push(s);
      buf = '';
      while(i + 1 < t.length && /\s/.test(t.charAt(i + 1))) i++;
    }
  }
  var rest = buf.trim();
  if(rest) parts.push(rest);
  return parts.length ? parts : [t];
}

/* ── 구분 박스: 박스별 복사·재생성 + 상단 전체 복사 + 셀프 케어 단계 미리보기 ── */
function sheetFullCopyBar_(){
  return '<div class="sheet-fullcopy-bar">' +
    '<button type="button" class="sheet-fullcopy-btn" onclick="copyWholeTab_(this)">전체 복사</button>' +
    '<span class="sheet-fullcopy-hint">구분된 내용을 한 줄씩 띄워 복사해요</span></div>';
}

window.copySheetField_ = function(id, btn, isHashtags){
  var el = document.getElementById(id);
  if(!el) return;
  var text = String(el.value || '');
  var html = '';
  if(isHashtags){
    text = text.split(/[\s,#]+/).map(function(t){ return t.replace(/^#/, '').trim(); })
      .filter(Boolean).map(function(t){ return '#' + t; }).join(' ');
  } else if(el.getAttribute('data-selfcare-preview') === '1'){
    html = formatSelfCareStepsHtmlForCopy_(text);
    text = formatSelfCareStepsForCopy_(text);
  }
  text = text.trim();
  if(!text){ setAppToast('복사할 내용이 없어요.', { duration: 2600, variant: 'err' }); return; }
  var label = btn ? btn.textContent : '';
  writeClipboardRich_(text, html, function(){
    if(btn){
      btn.textContent = '복사됨'; btn.classList.add('copied');
      setTimeout(function(){ btn.textContent = label || '복사'; btn.classList.remove('copied'); }, 1500);
    }
  });
};

window.copyWholeTab_ = function(btn){
  var draftId = state.selectedId;
  var tab = state.activeTab;
  var content = tab === 'blog' ? ensureSheetBlogOnContent_(draftId) : getDraftContent_(draftId);
  if(!content && tab !== 'blog'){ setAppToast('복사할 내용이 없어요.', { duration: 3000, variant: 'err' }); return; }
  var catId = state.selectedCatId != null ? state.selectedCatId : getCatIdFromDraftId_(draftId);
  var clone = content ? JSON.parse(JSON.stringify(content)) : {};
  if(content) applySheetEditsForTab_(clone, tab);
  var text = '';
  var html = '';
  if(tab === 'blog'){
    text = buildBlogPasteTextForPublish_(clone.blog, catId);
    if(!String(text || '').trim()){
      var sheetBlog = readSheetBlogEdits_();
      if(sheetBlog){
        clone.blog = sheetBlog;
        text = buildBlogPasteTextForPublish_(sheetBlog, catId);
      }
    }
  }
  else if(tab === 'community') text = formatCommunityPostText(clone.community);
  else if(tab === 'insta') text = getInstaFullPasteText_(clone.insta, catId);
  else if(tab === 'threads') text = getThreadsFullPasteText_(clone.threads);
  else if(tab === 'thread') text = getThreadPlainText(normalizeThreadBlock(clone.thread));
  else text = getTabCopyText(tab, clone);
  text = String(text || '').trim();
  if(!text){ setAppToast('복사할 내용이 없어요.', { duration: 3000, variant: 'err' }); return; }
  if(tab === 'community' && clone.community){
    html = formatCommunityPostHtmlForCopy_(clone.community);
  } else if(tab === 'blog' && clone.blog && blogUsesStructuredGeneralFormat_(catId, clone.blog)){
    // 리얼무브먼트·리얼페이스는 말미 URL이 OG 카드로 바뀌도록 평문만 복사
    html = isBranchBookingBlogCategory_(catId) ? '' : formatGeneralBlogPostHtmlForCopy_(clone.blog, catId);
  } else {
    html = '<div style="white-space:pre-wrap;line-height:1.7;font-size:14px;color:#1F2937;font-family:sans-serif;word-break:keep-all;">' +
      escapeHtml(text).replace(/\n/g, '<br/>') + '</div>';
  }
  var label = btn ? btn.textContent : '';
  writeClipboardRich_(text, html, function(){
    if(btn){
      btn.textContent = '복사됨'; btn.classList.add('copied');
      setTimeout(function(){ btn.textContent = label || '전체 복사'; btn.classList.remove('copied'); }, 1600);
    }
  });
};

